    assert.equal(anthropic.apiParameters.some((spec) => spec.key === 'topK'), false);
    assert.deepEqual(anthropic.reasoning.efforts, ['low', 'medium', 'high', 'max']);

    const qwen = backend._test.descriptorFor({ provider: 'auto', model: 'qwen3-max' });
