test('message actions are outside bubbles, reserve a stable gutter during generation, and Copy uses raw stored response text', async () => {
    const chat = read('backend/renderer/chat.js');
    const messageActions = read('backend/renderer/message-actions.js');
    const css = read('backend/shell/styles.css');
    const uiState = read('backend/renderer/ui-state.js');
    assert.match(messageActions, /messageActionsClass\('user'\)[\s\S]*?data-ui-action="edit-message"[\s\S]*?data-ui-action="retry-message"/u);
    assert.match(messageActions, /data-ui-action="copy-message" data-message-index="' \+ index \+ '"/u);
    assert.match(read('backend/renderer/event-listeners.js'), /action === 'copy-message'[\s\S]*?copyAssistantMessage\(copyIndex, control\)/u);
    assert.match(messageActions, /messageActionsClass\('assistant'\)[\s\S]*?continueButton/u);
    assert.ok(messageActions.includes('stroke-width=\"1.7\"'),
        'message actions must use a consistent lightweight stroke');
    assert.ok(messageActions.includes('stroke-linecap=\"round\"') && messageActions.includes('stroke-linejoin=\"round\"'),
        'message actions must use one consistent rounded-stroke icon system');
    assert.match(messageActions, /kind === 'retry'[\s\S]*?return start \+ '<path/u,
        'Retry must be a vector icon, never selectable text');
    assert.match(messageActions, /kind === 'delete'[\s\S]*?return start \+ '<path/u,
        'Delete must be a vector icon, never selectable text');
    assert.doesNotMatch(messageActions, />[↻−]<\/span>/u,
        'message action source must not contain copyable text-glyph icons');
    assert.doesNotMatch(css, /\.action-symbol(?:-retry|-delete|\s*\{)/u,
        'retired text-glyph presentation rules must not remain in the stylesheet');
    assert.match(chat, /<div class="message-stack"><div class="message-content">' \+ messageBody \+ '<\/div><\/div>' \+ actionsHtml/u,
        'actions must be outside message-stack so they cannot affect bubble/avatar geometry');
    assert.doesNotMatch(chat, /<div class="message-content">' \+ messageBody \+ actionsHtml/u);
    assert.match(chat, /var actionsHtml = messageActionsHtml\(role, messageIndex, messageId\);/u,
        'typing/generating messages must still render the reserved action gutter');
    assert.doesNotMatch(chat, /var actionsHtml = isTyping \? '' : messageActionsHtml/u);
    assert.match(css, /\.message-actions \{[\s\S]*?grid-row: 2;[\s\S]*?width: max-content;[\s\S]*?height: 30px;[\s\S]*?min-height: 30px;/u);
    const generationActionRule = css.match(/\.message\.assistant\.generating \.message-actions,\s*\n\.message\.adversary\.generating \.message-actions \{([\s\S]*?)\n\}/u);
    assert.ok(generationActionRule, 'only live assistant-like generating messages may suppress their own action row');
    assert.match(generationActionRule[1], /visibility: hidden;/u,
        'generation must hide controls without removing their occupied layout space');
    assert.doesNotMatch(generationActionRule[1], /display:\s*none/u,
        'generation must never collapse the reserved action gutter');
    assert.match(generationActionRule[1], /pointer-events: none;/u);
    assert.doesNotMatch(css, /\.message\.generating \.message-actions/u,
        'user Edit/Retry actions must never be hidden by a generic generating-message selector');
    assert.doesNotMatch(css, /\.chat-container\.generation-active \.message-actions/u,
        'message actions must not depend on a stale container generation-active CSS class');
    assert.match(css, /\.message-actions-user \{ justify-content: flex-end; justify-self: end; \}/u);
    assert.match(css, /\.message-actions-assistant \{ justify-content: flex-start; justify-self: start; \}/u);
    assert.match(uiState, /syncRenderedMessageActionVisibility/u,
        'generation state changes must explicitly resynchronize action visibility');

    let copied = null;
    const context = {
        console, Promise, Map, Set, JSON, Math, Number, String, Boolean, Array, Object, RegExp,
        navigator: { clipboard: { async writeText(text) { copied = text; } } },
        document: { head: null, body: null, getElementById() { return null; } },
        getActiveTab() { return { history: [{ role: 'assistant', content: '**raw markdown**' }] }; },
        setTimeout() {},
    };
    context.window = context; context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(messageActions, context, { filename: 'message-actions.js' });
    assert.equal(await context.copyAssistantMessage(0, null), true);
    assert.equal(copied, '**raw markdown**');
});

