test('Stop during later reasoning never marks or deletes an earlier completed tool call, and Continue remains visible', () => {
    const context = sendContext();
    vm.runInContext(read('backend/renderer/message-actions.js'), context, { filename: 'message-actions.js' });
    context.__timeline = [
        { id: 'worked-good', type: 'worked', activityId: 'activity-good', toolCallId: 'call-good', state: 'complete', status: 'complete' },
        { id: 'tool-good', type: 'tool-call', activityId: 'activity-good', toolCallId: 'call-good', name: 'read_file', phase: 'complete', state: 'complete', status: 'complete' },
        { id: 'reasoning-live', type: 'reasoning', content: 'unfinished thought', state: 'streaming', status: 'running' },
    ];
    context.__stopped = vm.runInContext('finalizeInterruptedTimeline(__timeline)', context);
    assert.equal(context.__stopped[0].interrupted, undefined, 'completed Worked activity must remain completed');
    assert.equal(context.__stopped[1].interrupted, undefined, 'completed tool call must never inherit interruption from a later Stop');
    assert.equal(context.__stopped[1].status, 'complete');
    assert.equal(context.__stopped[1].phase, 'complete');
    assert.equal(context.__stopped[2].interrupted, true, 'only the reasoning patch active at Stop is interrupted');
    assert.equal(context.__stopped[2].status, 'stopped');

    context.__message = {
        id: 'reasoning-stop', role: 'assistant', content: '', reasoning: 'unfinished thought',
        interrupted: true, continuable: true, finishReason: 'interrupted', continuationMode: 'reasoning',
        toolContext: [
            { role: 'assistant', content: null, tool_calls: [{ id: 'call-good', type: 'function', function: { name: 'read_file', arguments: '{}' } }] },
            { role: 'tool', tool_call_id: 'call-good', name: 'read_file', content: 'ok' },
        ],
        working: [{ id: 'activity-good', toolCallId: 'call-good', name: 'read_file', status: 'complete' }],
        agentTimeline: context.__stopped,
    };
    assert.equal(vm.runInContext('enforceAtomicToolState(__message)', context), false,
        'atomic normalization must leave a completed tool untouched when later reasoning is interrupted');
    assert.equal(context.__message.toolContext.length, 2);
    assert.equal(context.__message.agentTimeline.some((segment) => segment.id === 'tool-good'), true);

    vm.runInContext(`
        tabs = [{ id: 92, history: [__message] }];
        activeTabId = 92;
        generationSessionForTab = function() { return null; };
        getActiveTab = function() { return tabs[0]; };
    `, context);
    assert.equal(vm.runInContext('assistantMessageCanContinue(tabs[0], 0)', context), true);
    const html = vm.runInContext("messageActionsHtml('assistant', 0, 'reasoning-stop')", context);
    assert.match(html, /data-ui-action="continue-message"/u, 'Continue must remain visible when the actual interrupted patch is reasoning');
});

test('atomic tool normalization removes incomplete tools before Continue ever sees historical state', () => {
    const context = sendContext();
    context.__message = {
        id: 'assistant-stop', role: 'assistant', content: 'I will edit the file.', reasoning: 'Plan carefully.',
        interrupted: true, continuable: true, continuationMode: 'content',
        partialToolCall: { id: 'call-bad', preparationId: 'prep-bad', function: { name: 'replace_file', arguments: '{"path":"game.html"' } },
        toolContext: [
            { role: 'assistant', content: null, tool_calls: [{ id: 'call-good', type: 'function', function: { name: 'read_file', arguments: '{}' } }] },
            { role: 'tool', tool_call_id: 'call-good', name: 'read_file', content: 'ok' },
            { role: 'assistant', content: null, tool_calls: [{ id: 'call-bad', type: 'function', function: { name: 'replace_file', arguments: '{}' } }] },
        ],
        working: [
            { id: 'activity-good', toolCallId: 'call-good', name: 'read_file', status: 'complete' },
            { id: 'activity-bad', toolCallId: 'call-bad', preparationId: 'prep-bad', name: 'replace_file', status: 'running' },
        ],
        agentTimeline: [
            { id: 'reasoning-1', type: 'reasoning', content: 'Plan carefully.', state: 'complete', status: 'complete' },
            { id: 'worked-good', type: 'worked', activityId: 'activity-good', toolCallId: 'call-good', status: 'complete' },
            { id: 'tool-good', type: 'tool-call', activityId: 'activity-good', toolCallId: 'call-good', name: 'read_file', phase: 'executing', status: 'complete' },
            { id: 'reasoning-2', type: 'reasoning', content: 'Now edit it.', state: 'complete', status: 'complete' },
            { id: 'worked-bad', type: 'worked', activityId: 'activity-bad', toolCallId: 'call-bad', status: 'running' },
            { id: 'tool-bad', type: 'tool-call', activityId: 'activity-bad', toolCallId: 'call-bad', preparationId: 'prep-bad', name: 'replace_file', phase: 'preparing', state: 'streaming', status: 'running' },
        ],
    };

    assert.equal(vm.runInContext('enforceAtomicToolState(__message)', context), true);
    assert.equal(context.__message.partialToolCall, undefined);
    assert.deepEqual(Array.from(context.__message.agentTimeline, (segment) => segment.id), ['reasoning-1', 'worked-good', 'tool-good', 'reasoning-2']);
    assert.deepEqual(Array.from(context.__message.working, (entry) => entry.id), ['activity-good']);
    assert.equal(context.__message.toolContext.length, 2);
    assert.equal(context.__message.toolContext[0].tool_calls[0].id, 'call-good');
    assert.equal(context.__message.toolContext[1].tool_call_id, 'call-good');
    assert.doesNotMatch(JSON.stringify(context.__message), /call-bad|prep-bad|replace_file/u);

    context.__completedError = {
        toolContext: [
            { role: 'assistant', content: null, tool_calls: [{ id: 'call-error', type: 'function', function: { name: 'read_file', arguments: '{}' } }] },
            { role: 'tool', tool_call_id: 'call-error', name: 'read_file', content: '{"success":false,"error":"missing"}' },
        ],
        working: [{ id: 'activity-error', toolCallId: 'call-error', name: 'read_file', status: 'error' }],
        agentTimeline: [{ id: 'tool-error', type: 'tool-call', activityId: 'activity-error', toolCallId: 'call-error', name: 'read_file', phase: 'executing', status: 'error' }],
    };
    assert.equal(vm.runInContext('enforceAtomicToolState(__completedError)', context), false,
        'a tool that returned an error result is still an atomic completed tool round and must survive');
    assert.equal(context.__completedError.toolContext.length, 2);

    const chat = read('backend/renderer/chat.js');
    assert.match(chat, /Incomplete tool state is not retained in conversation history\./u);
    assert.doesNotMatch(chat, /Continue resumes this exact partial tool call\./u);
});

