test('adversary continuation mounts and paints into the existing adversary bubble live', () => {
    const content = { innerHTML: '' };
    const classes = new Set(['message', 'adversary']);
    const message = {
        isConnected: true,
        dataset: { messageId: 'adv-live' },
        classList: { add(value) { classes.add(value); } },
        querySelector(selector) { return selector === '.message-answer' ? content : null; },
    };
    const selectors = [];
    const container = { contains(element) { return element === message; } };
    const context = {
        console, Date, Math, Number, String, Boolean, Array, Object, Set, Map, Promise,
        performance: { now() { return 100; } },
        setTimeout() { return 1; }, clearTimeout() {},
        document: {
            getElementById(id) { return id === 'chatContainer' ? container : null; },
            querySelector(selector) {
                selectors.push(selector);
                return selector === '.message.adversary[data-message-id="adv-live"]' ? message : null;
            },
        },
        Darkstar: {},
    };
    context.window = context;
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(read('backend/renderer/generation-stream-surface.js'), context, { filename: 'generation-stream-surface.js' });
    vm.runInContext(read('backend/renderer/generation-ui.js'), context, { filename: 'generation-ui.js' });
    const session = { id: 91, continuationMessageId: 'adv-live', assistantIndex: 0, responseText: 'old critique', continuationBaseText: 'old critique', agentTimeline: [] };
    const coordinator = context.Darkstar.generationUi.createCoordinator({
        session,
        continuingFinalMessage: true,
        isCurrent() { return true; },
        isActiveTab() { return true; },
        displayRole() { return 'adversary'; },
        addMessage() { throw new Error('Continuation must reuse the persisted adversary bubble.'); },
        formatMessage(text) { return `<p>${text}</p>`; },
        updateMessageAgentTimeline() {},
        updateRenderedMessageActions() {},
        updateTokenCounter() {},
        smartScrollToBottom() {},
    });
    assert.ok(coordinator.mount());
    assert.ok(selectors.includes('.message.adversary[data-message-id="adv-live"]'));
    session.responseText = 'old critique + streamed continuation';
    coordinator.queueAnswer();
    coordinator.flushPaint();
    assert.match(content.innerHTML, /^<p>old critique \+ streamed continuation<\/p>.*typing-indicator/u);
    assert.ok(classes.has('generating'));
});


