// TEST MODULE: backend/Dev/tests/chat-sidebar-space-theme-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/chat-sidebar-space-theme-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const root = path.resolve(__dirname, '..', '..', '..');
const css = fs.readFileSync(path.join(root, 'backend', 'shell', 'styles.css'), 'utf8');
const html = fs.readFileSync(path.join(root, 'backend', 'shell', 'index.html'), 'utf8');
const workspaceSource = fs.readFileSync(path.join(root, 'backend', 'renderer', 'workspace.js'), 'utf8');
const chatSessionSource = fs.readFileSync(path.join(root, 'backend', 'renderer', 'chat-session.js'), 'utf8');
const initSource = fs.readFileSync(path.join(root, 'backend', 'renderer', 'init.js'), 'utf8');

function rule(selector) {
    const escaped = selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = css.match(new RegExp(`${escaped}\\s*\\{([^}]*)\\}`));
    assert.ok(match, `Missing CSS rule for ${selector}`);
    return match[1];
}

test('chat Schema sidebar remains independent while Nodes reserves enough width for Authorization', () => {
    assert.match(css, /--workspace-sidebar-width:\s*280px\s*;/u);
    assert.match(rule('.workspace-sidebar'), /width:\s*var\(--workspace-sidebar-width\)\s*;/u);
    assert.match(rule('.main-content'), /margin-left:\s*var\(--workspace-sidebar-width\)\s*;/u);
    assert.match(rule('.tab-bar'), /left:\s*var\(--workspace-sidebar-width\)\s*;/u);
    assert.match(rule('.node-workflow-sidebar'), /width:\s*76px\s*;/u, 'Settings sidebar must reserve enough width for the full Authorization label');
    assert.match(rule('.node-editor-sidebar-button'), /width:\s*64px\s*;/u);

    assert.match(workspaceSource, /tabBar\.style\.left = collapsed \? '28px' : currentWorkspaceSidebarWidth\(\) \+ 'px'/u);
    assert.match(chatSessionSource, /tabBar\.style\.left = collapsed === true \? '28px' : \(typeof currentWorkspaceSidebarWidth === 'function' \? currentWorkspaceSidebarWidth\(\) : 280\) \+ 'px'/u);
    assert.match(initSource, /tabBar\.style\.left = '28px'/u, 'startup must keep the existing collapsed width behavior');
    assert.doesNotMatch(workspaceSource + chatSessionSource, /tabBar\.style\.left[^\n]*'300px'/u, 'expanded tab offset must not retain the old 300px width');
});

test('Nodes workflow controls start near the top of the usable node surface', () => {
    const sidebar = rule('.node-workflow-sidebar');
    assert.match(sidebar, /padding:\s*8px\s+5px\s*;/u,
        'Settings sidebar must not reserve the obsolete 46px top gutter above Save');
    assert.doesNotMatch(sidebar, /padding[^;]*46px/u);
});

test('Space chat theme has no cosmetic star field or readability blur layer', () => {
    assert.doesNotMatch(html, /space-starfield|space-star(?:--|\b)|space-readability-blur/u);
    assert.doesNotMatch(css, /\.space-starfield|\.space-star(?:--|\s*\{)|\.space-readability-blur|@keyframes\s+space-star-/u);
    assert.match(css, /html\[data-theme='space'\][\s\S]*?--theme-bg-gradient:\s*#000000\s*;/u,
        'Space must retain a plain black background after removing the decoration');
});
});

