// TEST MODULE: backend/Dev/tests/chat-trace-expansion-toggle-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/chat-trace-expansion-toggle-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..', '..', '..');
const chatSource = fs.readFileSync(path.join(root, 'backend', 'renderer', 'chat.js'), 'utf8');
const html = fs.readFileSync(path.join(root, 'backend', 'shell', 'index.html'), 'utf8');
const css = fs.readFileSync(path.join(root, 'backend', 'shell', 'styles.css'), 'utf8');

function makeClassList(initial) {
    const values = new Set(initial || []);
    return {
        contains(name) { return values.has(name); },
        toggle(name, force) {
            const enabled = force === undefined ? !values.has(name) : Boolean(force);
            if (enabled) values.add(name);
            else values.delete(name);
            return enabled;
        },
        has(name) { return values.has(name); },
    };
}

function makeAttributeNode() {
    const attributes = new Map();
    return {
        scrollHeight: 120,
        clientHeight: 30,
        scrollTop: 0,
        setAttribute(name, value) { attributes.set(name, String(value)); },
        getAttribute(name) { return attributes.get(name); },
    };
}

function makeTraceBlock(type, { active = false, image = false } = {}) {
    const classes = [];
    if (type === 'thinking') classes.push('thinking-block');
    if (type === 'working') classes.push('working-block');
    if (type === 'tool-call') classes.push('tool-call-block');
    if (image) classes.push('context-image-block');

    const prefix = type;
    const header = makeAttributeNode();
    const preview = image ? null : makeAttributeNode();
    const content = makeAttributeNode();
    const beforeExpand = { count: 0 };
    const disclosureChanges = [];

    const block = {
        dataset: {
            userExpanded: 'false',
            segmentState: active ? 'streaming' : 'complete',
            segmentStatus: active ? 'running' : 'complete',
        },
        classList: makeClassList(classes),
        querySelector(selector) {
            if (selector === `.${prefix}-header`) return header;
            if (selector === `.${prefix}-preview`) return preview;
            if (selector === `.${prefix}-content`) return content;
            return null;
        },
        _onBeforeExpand() { beforeExpand.count += 1; },
        _onDisclosureChange(expanded) { disclosureChanges.push(expanded); },
    };

    return { block, header, preview, content, beforeExpand, disclosureChanges };
}

function makeButton() {
    const attributes = new Map([['aria-pressed', 'false']]);
    return {
        title: 'Expand all chat traces',
        classList: makeClassList([]),
        setAttribute(name, value) { attributes.set(name, String(value)); },
        getAttribute(name) { return attributes.get(name); },
    };
}

function loadTraceHarness(blocks) {
    const button = makeButton();
    const container = { querySelectorAll() { return blocks.map((item) => item.block); } };
    const context = {
        console,
        URL,
        document: {
            getElementById(id) {
                if (id === 'chatContainer') return container;
                if (id === 'nodeChatTraceButton') return button;
                return null;
            },
        },
    };
    vm.createContext(context);
    vm.runInContext(
        `${chatSource}
this.__chatTraceHarness = {
    setChatTraceExpansionEnabled,
    toggleChatTraceExpansion,
    applyChatTraceExpansionToConversation,
    get enabled() { return chatTraceExpansionEnabled; }
};`,
        context,
        { filename: 'backend/renderer/chat.js' }
    );
    return { api: context.__chatTraceHarness, button };
}

test('Nodes Traces toggle expands and collapses every chat disclosure family through the real disclosure state primitive', () => {
    const reasoning = makeTraceBlock('thinking', { active: true });
    const image = makeTraceBlock('thinking', { image: true });
    const worked = makeTraceBlock('working', { active: true });
    const tool = makeTraceBlock('tool-call', { active: true });
    const blocks = [reasoning, image, worked, tool];
    const { api, button } = loadTraceHarness(blocks);

    const expanded = api.setChatTraceExpansionEnabled(true);
    assert.deepEqual({ expanded: expanded.expanded, affected: expanded.affected }, { expanded: true, affected: 4 });
    assert.equal(api.enabled, true);
    assert.equal(button.getAttribute('aria-pressed'), 'true');
    assert.equal(button.getAttribute('aria-label'), 'Collapse all chat traces');
    assert.equal(button.title, 'Collapse all chat traces');
    assert.equal(button.classList.has('is-active'), true);

    for (const item of blocks) {
        assert.equal(item.block.dataset.userExpanded, 'true');
        assert.equal(item.block.classList.has('expanded'), true);
        assert.equal(item.header.getAttribute('aria-expanded'), 'true');
        assert.equal(item.content.getAttribute('aria-hidden'), 'false');
        assert.deepEqual(item.disclosureChanges, [true]);
        assert.equal(item.beforeExpand.count, 1);
    }
    assert.equal(reasoning.block.classList.has('previewing'), false);
    assert.equal(worked.block.classList.has('previewing'), false);
    assert.equal(tool.block.classList.has('previewing'), false);

    const collapsed = api.setChatTraceExpansionEnabled(false);
    assert.deepEqual({ expanded: collapsed.expanded, affected: collapsed.affected }, { expanded: false, affected: 4 });
    assert.equal(api.enabled, false);
    assert.equal(button.getAttribute('aria-pressed'), 'false');
    assert.equal(button.getAttribute('aria-label'), 'Expand all chat traces');
    assert.equal(button.title, 'Expand all chat traces');
    assert.equal(button.classList.has('is-active'), false);

    for (const item of blocks) {
        assert.equal(item.block.dataset.userExpanded, 'false');
        assert.equal(item.block.classList.has('expanded'), false);
        assert.equal(item.header.getAttribute('aria-expanded'), 'false');
        assert.equal(item.content.getAttribute('aria-hidden'), 'true');
        assert.deepEqual(item.disclosureChanges, [true, false]);
    }
    assert.equal(reasoning.block.classList.has('previewing'), true);
    assert.equal(worked.block.classList.has('previewing'), true);
    assert.equal(tool.block.classList.has('previewing'), true);
    assert.equal(reasoning.preview.scrollTop, 90);
    assert.equal(worked.preview.scrollTop, 90);
    assert.equal(tool.preview.scrollTop, 90);
});

test('new chat image patches start collapsed like other traces and render without visible filename chrome', () => {
    const assignments = chatSource.match(/block\.dataset\.userExpanded = chatTraceExpansionEnabled \? 'true' : 'false';/gu) || [];
    assert.equal(assignments.length, 5, 'reasoning, worked, compacting, tool-call, and image-patch constructors must inherit the global trace-toggle state');
    assert.match(chatSource, /function createReasoningBlock\(\)[\s\S]*?chatTraceExpansionEnabled \? 'true' : 'false'/u);
    const imageConstructor = chatSource.match(/function createImageBlock\(\) \{[\s\S]*?\n\}/u);
    const imageRenderer = chatSource.match(/function renderImageSegment\(block, segment\) \{[\s\S]*?\n\}/u);
    assert.ok(imageConstructor && imageRenderer, 'context-image constructor and renderer must exist');
    assert.match(imageConstructor[0], /block\.dataset\.userExpanded = chatTraceExpansionEnabled \? 'true' : 'false'/u,
        'context-image trace blocks must inherit the same collapsed-by-default trace state as the other patches');
    assert.doesNotMatch(imageRenderer[0], /context-image-meta|metaText|segment\.imageName \|\| 'Tool image'/u,
        'tool-produced image patches must not render source filenames as visible metadata');
    assert.match(imageRenderer[0], /image\.alt = 'Tool image'/u,
        'image accessibility fallback text must stay descriptive without exposing the source filename');
    assert.match(chatSource, /function createWorkedBlock\(\)[\s\S]*?chatTraceExpansionEnabled \? 'true' : 'false'/u);
    assert.match(chatSource, /function createCompactingBlock\(\)[\s\S]*?chatTraceExpansionEnabled \? 'true' : 'false'/u);
    assert.match(chatSource, /function createToolCallBlock\(\)[\s\S]*?chatTraceExpansionEnabled \? 'true' : 'false'/u);
    assert.match(chatSource, /if \(disclosureState\.has\(segment\.id\)\) \{[\s\S]*?disclosureState\.get\(segment\.id\) === true \? 'true' : 'false'/u,
        'an explicit per-image disclosure choice must survive later timeline patches');
});

test('Settings sidebar exposes an accessible pressed-state Traces button with a visible active style', () => {
    assert.match(html, /id="nodeChatTraceButton"[^>]*aria-pressed="false"/u);
    assert.match(fs.readFileSync(path.join(root, 'backend', 'renderer', 'event-listeners.js'), 'utf8'), /bindClickById\('nodeChatTraceButton', toggleChatTraceExpansion\)/u);
    assert.match(html, /id="nodeChatTraceButton"[\s\S]*?<span class="node-editor-sidebar-label">Traces<\/span>/u);
    assert.match(css, /#nodeChatTraceButton\.is-active/u);
});
});

