    const buttonMatch = sidebarMatch[0].match(/<button\b[^>]*id="nodeChatTraceButton"[^>]*>[\s\S]*?<\/button>/u);
    assert.ok(buttonMatch, 'the Traces button must remain inside the Settings sidebar');
