const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const root = path.resolve(__dirname, '..', '..', '..');
const read = (file) => fs.readFileSync(path.join(root, file), 'utf8');

function attrs(fragment) {
    const out = {};
    const re = /([:\w-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/gu;
    for (const match of fragment.matchAll(re)) out[match[1]] = match[2] ?? match[3] ?? match[4] ?? '';
    return out;
}

function stripMarkup(value) {
    return String(value || '').replace(/<[^>]+>/gu, ' ').replace(/\s+/gu, ' ').trim();
}

function staticButtons() {
    const html = read('backend/shell/index.html');
    return Array.from(html.matchAll(/<button\b([^>]*)>([\s\S]*?)<\/button>/giu)).map((match) => {
        const a = attrs(match[1]);
        return {
            id: a.id || '',
            className: a.class || '',
            effort: a['data-effort'] || '',
            title: a.title || '',
            ariaLabel: a['aria-label'] || '',
            disabled: Object.prototype.hasOwnProperty.call(a, 'disabled'),
            text: stripMarkup(match[2]),
        };
    });
}

