// TEST MODULE: backend/Dev/tests/context-contract-immediate-stop-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/context-contract-immediate-stop-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const test = require('node:test');
const { consumeChatCompletionStream } = require('../../runtime/streaming');

function abortableReader() {
    let pendingResolve = null;
    let cancelled = false;
    return {
        get cancelled() { return cancelled; },
        async read() {
            if (cancelled) return { done: true, value: undefined };
            return new Promise((resolve) => { pendingResolve = resolve; });
        },
        async cancel() {
            cancelled = true;
            if (pendingResolve) {
                const resolve = pendingResolve;
                pendingResolve = null;
                resolve({ done: true, value: undefined });
            }
        },
    };
}

test('aborting a generation explicitly cancels the SSE reader and terminates as AbortError without a buffered tail', async () => {
    const controller = new AbortController();
    const reader = abortableReader();
    const response = { body: { getReader() { return reader; } } };
    const run = consumeChatCompletionStream(response, { signal: controller.signal });

    controller.abort();
    await assert.rejects(run, (error) => error && error.name === 'AbortError');
    assert.equal(reader.cancelled, true, 'transport reader must be cancelled immediately when the generation signal aborts');
});
});

