function read(relative) {
    return fs.readFileSync(path.join(root, relative), 'utf8');
}

function loadDefinition(relative, portTypes) {
    let definition = null;
    const controls = new Proxy({}, { get(_target, property) {
        if (property === 'status') return () => '[status]';
        if (property === 'group') return (_title, _description, content) => String(content || '');
        return (label, value, _id, param) => `[${String(property)}:${label}:${value}:${param}]`;
    } });
    const nodes = {
        controls,
        PORT_TYPES: portTypes,
        builtinCommon: { baseNode(def, nodeId, x, y, extra) { return { id: nodeId, type: def.id, x, y, ...extra }; } },
        registerNode(value) { definition = value; },
    };
    const sandbox = { Darkstar: { nodes, imageData: { safeDataUrl() { return null; } } }, console, String, Number, Array, Object, Promise };
    sandbox.globalThis = sandbox;
    const file = path.join(root, relative);
    vm.runInNewContext(fs.readFileSync(file, 'utf8'), vm.createContext(sandbox), { filename: file });
    assert.ok(definition, `${relative} must register`);
    return definition;
}

