    const args = buildSharedArgs(config, capabilities, '127.0.0.1');
    assert.deepEqual(args.slice(args.indexOf('--ctx-size'), args.indexOf('--ctx-size') + 2), ['--ctx-size', '262144']);
    assert.equal(args.includes('--n-gpu-layers'), false, 'auto layers must remain unset so llama.cpp may offload weights');
