test('GGUF discovery reads architecture-specific context_length and block_count', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-gguf-meta-'));
    const file = path.join(dir, 'model.gguf');
    const parts = [];
    const u32 = (value) => { const b = Buffer.alloc(4); b.writeUInt32LE(value); return b; };
    const u64 = (value) => { const b = Buffer.alloc(8); b.writeBigUInt64LE(BigInt(value)); return b; };
    const str = (value) => { const b = Buffer.from(value, 'utf8'); return Buffer.concat([u64(b.length), b]); };
    parts.push(Buffer.from('GGUF'), u32(3), u64(0), u64(8));
    parts.push(str('general.architecture'), u32(8), str('test'));
    parts.push(str('test.block_count'), u32(4), u32(48));
    parts.push(str('test.context_length'), u32(4), u32(262144));
    parts.push(str('test.embedding_length'), u32(4), u32(4096));
    parts.push(str('test.attention.head_count'), u32(4), u32(32));
    parts.push(str('test.attention.head_count_kv'), u32(4), u32(8));
    parts.push(str('test.attention.key_length'), u32(4), u32(128));
    parts.push(str('test.attention.value_length'), u32(4), u32(128));
    fs.writeFileSync(file, Buffer.concat(parts));
    try {
        assert.deepEqual(readGgufModelMetadata(file), { layerCount: 48, contextLength: 262144, reasoning: null, mtp: null });
        assert.deepEqual(readGgufMemoryMetadata(file), { architecture: 'test', layerCount: 48, embeddingLength: 4096, headCount: 32, headCountKv: 8, keyLength: 128, valueLength: 128 });
    } finally {
        fs.rmSync(dir, { recursive: true, force: true });
    }
});

test('local llama streaming transport survives silent prefill and has no client body-idle timeout', async () => {
    const { requestLocalStream } = require('../../runtime/server-stream');
    const streamSource = fs.readFileSync(path.join(__dirname, '..', '..', 'runtime', 'server-stream.js'), 'utf8');
    const completionSource = fs.readFileSync(path.join(__dirname, '..', '..', 'runtime', 'chat-completion.js'), 'utf8');
    assert.doesNotMatch(streamSource, /setTimeout|bodyTimeout|headersTimeout/u, 'local streaming must not inherit a five-minute body-idle timer');
    assert.match(completionSource, /fetchImpl === globalThis\.fetch[\s\S]*?requestLocalStream/u, 'production local chat must bypass generic fetch/Undici streaming timeouts');

    const server = http.createServer((request, response) => {
        if (request.url !== '/v1/chat/completions') return response.writeHead(404).end();
        response.writeHead(200, { 'Content-Type': 'text/event-stream' });
        response.flushHeaders();
        setTimeout(() => response.end('data: {"choices":[{"delta":{"content":"ok"}}]}\n\ndata: [DONE]\n\n'), 75);
    });
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    const port = server.address().port;
    try {
        const response = await requestLocalStream({ host: '127.0.0.1', port, pathname: '/v1/chat/completions', body: { stream: true } });
        assert.equal(response.ok, true);
        const reader = response.body.getReader();
        let text = '';
        while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            text += Buffer.from(value).toString('utf8');
        }
        assert.match(text, /data: \[DONE\]/u);
    } finally {
        await new Promise((resolve) => server.close(resolve));
    }
});

test('local llama streaming transport preserves AbortController cancellation before response headers', async () => {
    const { requestLocalStream } = require('../../runtime/server-stream');
    const server = http.createServer(() => undefined);
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    const controller = new AbortController();
    const pending = requestLocalStream({ host: '127.0.0.1', port: server.address().port, pathname: '/v1/chat/completions', body: {}, signal: controller.signal });
    setTimeout(() => controller.abort(), 25);
    try {
        await assert.rejects(pending, (error) => error?.name === 'AbortError' && error?.code === 'ABORTED');
    } finally {
        await new Promise((resolve) => server.close(resolve));
    }
});

