test('three scheduled messages on one tab remain FIFO while the first launch handshake is asynchronous', async () => {
    const sendCalls = [];
    const resolvers = [];
    const tab = {
        id: 7,
        projectId: 0,
        history: [],
        generationQueued: false,
        scheduled: [
            { id: 's1', text: 'first', image: null, order: 1, tabId: 7 },
            { id: 's2', text: 'second', image: null, order: 2, tabId: 7 },
            { id: 's3', text: 'third', image: null, order: 3, tabId: 7 },
        ],
    };
    const context = {
        console,
        Map, Set, Promise, Math, Number, String, Array, Object, RegExp,
        tabs: [tab],
        activeTabId: -1,
        scheduledMessageSequence: 3,
        scheduledDispatchTimer: null,
        scheduledDispatchReservations: new Set(),
        getTabWorkspaceRoot() { return 'C:/SyntheticProject'; },
        generationSessionForTab() { return null; },
        activeGenerationCount() { return 0; },
        configuredParallelSlots() { return 4; },
        generationCapacityAvailable() { return true; },
        scheduleChatSessionSave() {},
        renderQueue() {},
        collapseScheduledQueueUi() {},
        getActiveTab() { return null; },
        sendMessage(_regenerateFromIndex, options) {
            sendCalls.push(options.messageOverride);
            return new Promise((resolve) => resolvers.push(resolve));
        },
        setTimeout, clearTimeout,
        Darkstar: { imageData: { normalizeSource() { return null; }, safeDataUrl() { return ''; } } },
    };
    context.window = context;
    context.globalThis = context;
    run('backend/renderer/queue.js', context);

    assert.equal(context.dispatchNextScheduledMessage(0), true);
    await new Promise((resolve) => setTimeout(resolve, 15));
    assert.deepEqual(sendCalls, ['first'], 'one tab may have only one scheduled launch handshake in flight');
    assert.deepEqual(tab.scheduled.map((entry) => entry.text), ['second', 'third'], 'later entries must remain stored until the first launch finishes');
    assert.equal(context.scheduledDispatchReservations.has(7), true);

    resolvers.shift()({ success: true });
    await new Promise((resolve) => setTimeout(resolve, 15));
    assert.deepEqual(sendCalls, ['first', 'second']);
    assert.deepEqual(tab.scheduled.map((entry) => entry.text), ['third']);

    resolvers.shift()({ success: true });
    await new Promise((resolve) => setTimeout(resolve, 15));
    assert.deepEqual(sendCalls, ['first', 'second', 'third']);
    assert.deepEqual(tab.scheduled, []);

    resolvers.shift()({ success: true });
    await new Promise((resolve) => setTimeout(resolve, 15));
    assert.equal(context.scheduledDispatchReservations.size, 0);
});

