test('diagnostics fall back to a writable location instead of silently disabling Crashpad when the primary path is unwritable', (t) => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-diag-fallback-'));
    t.after(() => fs.rmSync(root, { recursive: true, force: true }));
    const preferred = diagnosticsDirectory(path.join(root, 'protected'));
    const fallbackRoot = path.join(root, 'fallback');
    const realFs = fs;
    const fakeFs = {
        ...realFs,
        mkdirSync(target, options) {
            if (path.resolve(target) === path.resolve(preferred)) {
                const error = new Error('access denied');
                error.code = 'EACCES';
                throw error;
            }
            return realFs.mkdirSync(target, options);
        },
    };
    const location = resolveDiagnosticsDirectory({
        masterDir: path.join(root, 'protected'),
        tempDir: fallbackRoot,
        userDataDir: '',
        env: {},
        fs: fakeFs,
        pid: 9001,
    });
    assert.equal(location.directory, path.join(fallbackRoot, 'Darkstar', 'backend', 'Dev', 'Diagnostics'));
    assert.equal(location.failures.length, 1);
    assert.equal(location.failures[0].code, 'EACCES');
    assert.ok(fs.statSync(location.directory).isDirectory());
});

