// TEST MODULE: backend/Dev/tests/delegated-static-button-execution-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/delegated-static-button-execution-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..', '..', '..');
const workspaceSource = fs.readFileSync(path.join(root, 'backend/renderer/workspace.js'), 'utf8');
const uipSource = fs.readFileSync(path.join(root, 'backend/renderer/uip.js'), 'utf8');

test('delegated button execution: workspace Choose Directory invokes chooser for the active project with required/root-rename semantics', () => {
    const match = workspaceSource.match(/openButton\.addEventListener\('click', function\(\) \{([\s\S]*?)\n\s*\}\);/u);
    assert.ok(match, 'workspace delegated click listener missing');
    const calls = [];
    const handler = vm.runInNewContext(`(function() {${match[1]}\n})`, {
        activeProjectId: 42,
        chooseWorkspaceFolder(options) { calls.push(options); },
    });
    handler();
    assert.equal(calls.length, 1);
    assert.equal(calls[0].projectId, 42);
    assert.equal(calls[0].required, true);
    assert.equal(calls[0].renameDefaultProject, true);
});

function createUipHarness() {
    const listeners = { add: {}, close: {}, document: {} };
    const overlay = [];
    let listWindowsCalls = 0;
    const classSet = new Set();
    const modal = {
        classList: {
            add(value) { classSet.add(value); },
            remove(value) { classSet.delete(value); },
            contains(value) { return classSet.has(value); },
        },
        setAttribute() {},
        addEventListener(type, handler) { listeners.modal = { type, handler }; },
    };
    const pickerList = {
        innerHTML: '',
        querySelectorAll() { return []; },
        insertAdjacentHTML() {},
    };
    const targetList = { innerHTML: '' };
    const add = { addEventListener(type, handler) { listeners.add[type] = handler; } };
    const close = { addEventListener(type, handler) { listeners.close[type] = handler; } };
    const elements = {
        uipAddButton: add,
        uipWindowPickerClose: close,
        uipWindowPicker: modal,
        uipWindowPickerList: pickerList,
        uipTargetList: targetList,
    };
    const api = {
        async listTargets() { return { success: true, targets: [] }; },
        async listWindows() { listWindowsCalls += 1; return { success: true, windows: [] }; },
    };
    const windowObject = {
        activeProjectId: 9,
        darkstar: { uip: api },
        workspaceIdForProject(projectId) { return `project-${projectId}`; },
        async setOfflineBrowserOverlayBlockReason(reason, blocked) { overlay.push([reason, blocked]); },
    };
    const document = {
        getElementById(id) { return elements[id] || null; },
        addEventListener(type, handler) { listeners.document[type] = handler; },
    };
    const context = vm.createContext({ window: windowObject, document, console: { error() {} }, Set, Array, Number, String, Math, Promise });
    vm.runInContext(uipSource, context, { filename: 'backend/renderer/uip.js' });
    return { windowObject, listeners, overlay, classSet, getListWindowsCalls: () => listWindowsCalls };
}

test('delegated button execution: UIP Connect application opens the picker and scans windows', async () => {
    const harness = createUipHarness();
    await harness.windowObject.initializeUipUi();
    assert.equal(typeof harness.listeners.add.click, 'function', 'UIP Add click listener missing');
    await harness.listeners.add.click();
    assert.equal(harness.classSet.has('visible'), true);
    assert.equal(harness.getListWindowsCalls(), 1);
    assert.deepEqual(harness.overlay.at(-1), ['uip-picker', true]);
});

test('delegated button execution: UIP picker Close hides the picker and releases browser overlay blocking', async () => {
    const harness = createUipHarness();
    await harness.windowObject.initializeUipUi();
    await harness.listeners.add.click();
    assert.equal(harness.classSet.has('visible'), true);
    assert.equal(typeof harness.listeners.close.click, 'function', 'UIP Close click listener missing');
    harness.listeners.close.click();
    assert.equal(harness.classSet.has('visible'), false);
    assert.deepEqual(harness.overlay.at(-1), ['uip-picker', false]);
});
});

