// TEST MODULE: backend/Dev/tests/dom-utils-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/dom-utils-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const source = fs.readFileSync(path.resolve(__dirname, '..', '..', 'renderer', 'core-utils.js'), 'utf8');

function loadUtilities(debugLog) {
    const context = { darkstarDebugLog: debugLog };
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(source, context, { filename: 'backend/renderer/core-utils.js' });
    return context.Darkstar.dom;
}

function fakeInput() {
    const listeners = new Map();
    return {
        listeners,
        focused: false,
        selected: false,
        addEventListener(type, handler) { listeners.set(type, handler); },
        focus() { this.focused = true; },
        select() { this.selected = true; },
    };
}

function event(key = '') {
    return {
        key,
        prevented: false,
        stopped: false,
        preventDefault() { this.prevented = true; },
        stopPropagation() { this.stopped = true; },
    };
}

test('shared DOM escaping handles text and attribute metacharacters consistently', () => {
    const dom = loadUtilities();
    assert.equal(dom.escapeHtml(`<tag a="x">Tom & 'Ada'</tag>`), '&lt;tag a=&quot;x&quot;&gt;Tom &amp; &#039;Ada&#039;&lt;/tag&gt;');
    assert.equal(dom.escapeHtml(null), '');
});

test('shared inline commit binding owns Enter, Escape, blur, focus, and propagation behavior', () => {
    const dom = loadUtilities();
    const input = fakeInput();
    const commits = [];
    assert.equal(dom.bindInlineCommitInput(input, (commit) => commits.push(commit)), true);
    assert.equal(input.focused, true);
    assert.equal(input.selected, true);

    const click = event();
    input.listeners.get('click')(click);
    assert.equal(click.stopped, true);

    const enter = event('Enter');
    input.listeners.get('keydown')(enter);
    assert.deepEqual(commits, [true]);
    assert.equal(enter.prevented, true);
    assert.equal(enter.stopped, true);

    const escape = event('Escape');
    input.listeners.get('keydown')(escape);
    assert.deepEqual(commits, [true, false]);
    assert.equal(escape.prevented, true);
    assert.equal(escape.stopped, true);

    input.listeners.get('blur')();
    assert.deepEqual(commits, [true, false, true]);
});
});

