// TEST MODULE: backend/Dev/tests/edit-modal-browser-focus-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/edit-modal-browser-focus-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');
const fs = require('node:fs');
const { EventEmitter } = require('node:events');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const { OfflineBrowserService } = require(path.join(ROOT, 'backend', 'browser', 'offline-browser-service.js'));

class FakeSession extends EventEmitter {
    constructor() {
        super();
        this.webRequest = { onBeforeRequest() {} };
    }
    setPermissionCheckHandler() {}
    setPermissionRequestHandler() {}
}

class FakeWebContents extends EventEmitter {
    constructor() {
        super();
        this.session = new FakeSession();
        this.debugger = new EventEmitter();
        this.debugger.isAttached = () => false;
    }
    setAudioMuted() {}
    setZoomFactor() {}
    setWindowOpenHandler() {}
    canGoBack() { return false; }
    canGoForward() { return false; }
    isDestroyed() { return false; }
    destroy() {}
}

class FakeBrowserView {
    constructor() {
        this.webContents = new FakeWebContents();
        this.bounds = { x: 0, y: 0, width: 0, height: 0 };
    }
    setAutoResize() {}
    setBounds(bounds) { this.bounds = { ...bounds }; }
    getBounds() { return { ...this.bounds }; }
}

class FocusSensitiveWindow extends EventEmitter {
    constructor() {
        super();
        this.contentBounds = { x: 0, y: 0, width: 1440, height: 900 };
        this.attached = null;
        this.focusOwner = 'renderer';
        this.focused = true;
        this.blurWebViewCalls = 0;
        this.rendererFocusCalls = 0;
        this.focusEvents = [];
        this.webContents = {
            send() {},
            isDestroyed() { return false; },
            focus: () => {
                this.rendererFocusCalls += 1;
                this.focusEvents.push('focus-renderer');
                // Models the Windows BrowserView focus failure we are guarding
                // against: focusing the main WebContents is not a reliable
                // transfer while the native BrowserView still owns webview focus.
                if (this.focusOwner !== 'browser') this.focusOwner = 'renderer';
            },
            isFocused: () => this.focusOwner === 'renderer',
        };
    }
    isDestroyed() { return false; }
    isFocused() { return this.focused; }
    getContentBounds() { return { ...this.contentBounds }; }
    setBrowserView(view) { this.attached = view; }
    removeBrowserView(view) {
        this.focusEvents.push('detach-browser-view');
        if (this.attached === view) this.attached = null;
    }
    blurWebView() {
        this.blurWebViewCalls += 1;
        this.focusEvents.push('blur-browser-view');
        if (this.focusOwner === 'browser') this.focusOwner = 'none';
    }
}

function fixture(options = {}) {
    const service = new OfflineBrowserService({ BrowserView: FakeBrowserView, baseDir: ROOT });
    const window = new FocusSensitiveWindow();
    service.attachWindow(window);
    service.setBounds({ x: 900, y: 80, width: 500, height: 760 });
    service.setVisible(true);
    return { service, window };
}

test('foreground blocking explicitly releases BrowserView keyboard focus before the native view is detached', async () => {
    const { service, window } = fixture();
    window.focusOwner = 'browser';

    service.setOverlayBlocked(true);

    assert.ok(window.blurWebViewCalls >= 1, 'BrowserWindow.blurWebView() must explicitly release native BrowserView focus');
    assert.ok(window.rendererFocusCalls >= 1, 'main renderer WebContents must be focused after releasing BrowserView focus');
    const firstBlur = window.focusEvents.indexOf('blur-browser-view');
    const detach = window.focusEvents.indexOf('detach-browser-view');
    const lastRendererFocus = window.focusEvents.lastIndexOf('focus-renderer');
    assert.ok(firstBlur >= 0 && firstBlur < detach, 'BrowserView focus must be released while the native view is still attached');
    assert.ok(lastRendererFocus > detach, 'renderer focus must be reasserted after native BrowserView detachment');
    assert.equal(window.focusOwner, 'renderer', 'keyboard focus must belong to the renderer when a foreground overlay is shown');
    assert.equal(window.attached, null, 'the BrowserView should still be detached for foreground z-order');
    await service.destroy();
});

test('browser close/parking cannot leave keyboard focus trapped on an off-canvas BrowserView', async () => {
    const { service, window } = fixture();
    window.focusOwner = 'browser';

    service.setVisible(false);

    assert.ok(window.blurWebViewCalls >= 1, 'closing the browser must release BrowserView focus before it is parked');
    assert.equal(window.focusOwner, 'renderer');
    await service.destroy();
});

test('focus restoration never steals OS focus when Darkstar itself is not the focused window', async () => {
    const { service, window } = fixture();
    window.focused = false;
    window.focusOwner = 'other-app';
    window.blurWebViewCalls = 0;
    window.rendererFocusCalls = 0;
    window.focusEvents.length = 0;

    service.setOverlayBlocked(true);

    assert.equal(window.blurWebViewCalls, 0);
    assert.equal(window.rendererFocusCalls, 0);
    assert.equal(window.focusOwner, 'other-app');
    await service.destroy();
});


test('Edit Message focuses the inline textarea in the existing user bubble without a native modal handoff', () => {
    let activeElement = null;
    const listeners = new Map();
    const contentClasses = new Set();
    const children = [];
    const content = {
        innerHTML: 'old',
        classList: { add(name) { contentClasses.add(name); }, contains(name) { return contentClasses.has(name); } },
        appendChild(child) { children.push(child); },
    };
    const userElement = { querySelector(selector) { return selector === '.message-content' ? content : null; } };
    function element(tag) {
        return {
            tagName: String(tag).toUpperCase(),
            className: '', value: '', style: {}, textContent: '', type: '', scrollHeight: 70,
            setAttribute() {},
            addEventListener(type, fn) { listeners.set(`${tag}:${type}:${this.textContent || this.className}`, fn); },
            appendChild(child) { (this.children ||= []).push(child); },
            focus() { activeElement = this; },
            setSelectionRange() {},
        };
    }
    const document = {
        get activeElement() { return activeElement; },
        querySelector(selector) { return selector.startsWith('.message.user[') ? userElement : null; },
        createElement: element,
    };
    const tab = { id: 7, history: [{ id: 'm1', role: 'user', content: 'hello' }] };
    const context = {
        console, Promise, Array, Boolean, Number, Object, String, Map, Math,
        document,
        globalThis: null,
        activeTabId: 7,
        tabs: [tab],
        getActiveTab() { return tab; },
        editingMessageIndex: -1,
        editingMessageTabId: null,
        editingMessageId: null,
    };
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'edit.js'), 'utf8'), context, { filename: 'edit.js' });

    assert.equal(context.editMessage(0), true);
    assert.equal(contentClasses.has('editing-inline'), true);
    assert.equal(children[0].className, 'message-inline-editor');
    assert.equal(children[0].value, 'hello');
    assert.equal(activeElement, children[0], 'inline editor should receive focus immediately inside the existing bubble');
    assert.doesNotMatch(fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'edit.js'), 'utf8'), /setOfflineBrowserOverlayBlockReason|edit-modal-open/u);
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/editor-rules-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/editor-rules-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const ROOT = path.resolve(__dirname, '..', '..', '..');

function read(relativePath) {
    return fs.readFileSync(path.join(ROOT, relativePath), 'utf8');
}

test('agent-editor rules are the sole durable engineering contract and stale production tables stay retired', () => {
    assert.equal(fs.existsSync(path.join(ROOT, 'Development_Table.md')), false, 'the obsolete Development Table name must remain retired');
    assert.equal(fs.existsSync(path.join(ROOT, 'Production_Table.md')), false, 'the obsolete Production Table must not return as a duplicate implementation inventory');
    assert.equal(fs.existsSync(path.join(ROOT, 'Rules_For_Agent_Editors.md')), true);
    assert.equal(fs.existsSync(path.join(ROOT, 'Index_for_Agents.txt')), true);

    const rules = read('Rules_For_Agent_Editors.md');
    const verifier = read('backend/scripts/verify-source.js');

    assert.match(rules, /All harness features must be model invariant/u);
    assert.match(rules, /correct architectural owner/u);
    assert.match(rules, /Spaghetti code, band-aids, and shallow compatibility patches are prohibited/u);
    assert.match(rules, /Every fix must be locked by regression coverage/u);
    assert.match(rules, /Tool calls are atomic historical objects/u);
    assert.match(rules, /Preserve Electron security and privilege boundaries/u);
    assert.match(rules, /IPC has one canonical registry/u);
    assert.match(rules, /Persistence has one canonical binary\/atomic-write architecture/u);
    assert.match(rules, /Production_Table\.md.*must not be recreated/u);
    assert.match(rules, /Index_for_Agents\.txt/u);
    assert.match(rules, /npm --prefix backend\/shell run verify/u);

    assert.match(verifier, /'Rules_For_Agent_Editors\.md'/u);
    assert.match(verifier, /'Index_for_Agents\.txt'/u);
    assert.doesNotMatch(verifier, /'Production_Table\.md'/u);
    assert.doesNotMatch(verifier, /'Development_Table\.md'/u);
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/electron-navigation-history-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/electron-navigation-history-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..', '..', '..');

test('browser services use Electron navigationHistory instead of deprecated WebContents navigation methods', () => {
    const offline = fs.readFileSync(path.join(root, 'backend/browser/offline-browser-service.js'), 'utf8');
    const online = fs.readFileSync(path.join(root, 'backend/browser/online-browser-host.js'), 'utf8');
    for (const [name, source] of [['offline browser', offline], ['online browser', online]]) {
        assert.match(source, /navigationHistory/u, `${name} must use Electron navigationHistory`);
        assert.doesNotMatch(source, /webContents\.(?:canGoBack|canGoForward|goBack|goForward)\s*\(/u, `${name} must not call deprecated WebContents navigation methods`);
        assert.doesNotMatch(source, /contents\?*\.(?:canGoBack|canGoForward)\?*\.\(/u, `${name} must not call deprecated canGoBack/canGoForward methods`);
    }
});
});

