TEST_FACTORIES.set("backend/Dev/tests/every-static-button-execution-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..', '..', '..');
const html = fs.readFileSync(path.join(root, 'backend', 'shell', 'index.html'), 'utf8');
const listenerSource = fs.readFileSync(path.join(root, 'backend', 'renderer', 'event-listeners.js'), 'utf8');

function makeElement(id, dataset = {}) {
    const listeners = new Map();
    return {
        id,
        dataset: { ...dataset },
        style: {},
        value: '',
        hidden: true,
        scrollHeight: 0,
        nativeClicks: 0,
        focusCalls: 0,
        addEventListener(type, handler) { listeners.set(type, handler); },
        listener(type) { return listeners.get(type); },
        click() { this.nativeClicks += 1; },
        focus() { this.focusCalls += 1; },
        contains() { return false; },
    };
}

function harness() {
    const ids = [
        'btnSettings', 'mobileClearChatButton', 'nodeWorkflowSaveButton', 'nodeWorkflowLoadButton',
        'nodeClearContextButton', 'nodeChatTraceButton', 'nodeChatAutosaveButton',
        'nodeMuteButton', 'nodeThemeButton', 'workflowAddSectionButton', 'tabNav', 'newTabButton',
        'workspaceToggle', 'projectAddButton', 'offlineBrowserBack',
        'offlineBrowserForward', 'offlineBrowserReload', 'offlineBrowserOpenButton',
        'offlineBrowserChooseFileButton', 'offlineBrowserReset',
        'offlineBrowserFocusAddressButton', 'offlineBrowserAddress', 'queueToggle', 'removeImageButton',
        'projectDirectoryChooseButton', 'imageUploadButton', 'imageInput', 'scheduleBtn', 'sendBtn',
        'statusSettings', 'workflowAddSectionButton', 'projectDeleteCancelButton', 'projectDeleteConfirmButton', 'workspaceDeleteCancelButton',
        'workspaceDeleteConfirmButton', 'nodeSearchInput', 'messageInput', 'slashCommandMenu',
    ];
    const elements = new Map(ids.map((id) => [id, makeElement(id)]));
    const efforts = ['off', 'low', 'medium', 'high'].map((effort) => makeElement(`effort-${effort}`, { effort }));
    const calls = [];
    const record = (name) => (...args) => { calls.push({ name, args }); };
    const functionNames = [
        'toggleSettings', 'setThinkingEffort', 'clearChat', 'saveNodeWorkflow', 'loadNodeWorkflow',
        'clearNodeContext', 'toggleChatTraceExpansion', 'toggleChatAutosave',
        'toggleDarkstarUiMuted', 'toggleDarkstarTheme', 'resetNodeGraph', 'switchView', 'toggleStatusView', 'createNewTab',
        'toggleOfflineBrowser', 'toggleWorkspace', 'createNewProject',
        'offlineBrowserBack', 'offlineBrowserForward', 'offlineBrowserReload', 'openOfflineBrowserAddress', 'chooseOfflineBrowserFile',
        'resetBrowser', 'toggleQueue', 'removeImage', 'chooseActiveProjectDirectory',
        'handleGenerationAction', 'stopGeneration', 'sendMessage', 'closeProjectDeleteModal',
        'confirmProjectDeleteModal', 'closeWorkspaceDeleteModal', 'confirmWorkspaceDeleteModal',
        'editMessage', 'retryMessage', 'copyAssistantMessage', 'continueGeneration', 'deleteChatMessage', 'removeScheduled',
        'removeQueuedGenerationById', 'toggleUipTarget', 'disconnectUipTarget', 'closeTab',
        'onNodeSearchInput', 'onNodeSearchKeydown', 'onOfflineBrowserAddressKeydown', 'chooseComposerImage',
        'handleKeydown', 'updateScheduleButton', 'handleComposerImagePaste', 'setGenerationControlHeld',
        'closeEditModal', 'openWorkflowSectionSearch',
    ];
    const documentListeners = new Map();
    const windowListeners = new Map();
    const context = {
        console,
        document: {
            getElementById(id) { return elements.get(id) || null; },
            querySelectorAll(selector) { return selector === '.effort-btn[data-effort]' ? efforts : []; },
            addEventListener(type, handler) { documentListeners.set(type, handler); },
        },
        window: { addEventListener(type, handler) { windowListeners.set(type, handler); } },
        editModalIsActive: () => false,
        updateSlashCommandMenu: () => undefined,
        scheduleChatSessionSave: () => undefined,
        repairComposerFocusAfterNodeViewInteraction: () => undefined,
    };
    for (const name of functionNames) context[name] = record(name);
    vm.runInNewContext(listenerSource, context, { filename: 'backend/renderer/event-listeners.js' });
    return { calls, elements, efforts, documentListeners, windowListeners };
}

const staticCases = [
    ['mobile settings', 'btnSettings', [['toggleSettings', []]]],
    ['clear conversation', 'mobileClearChatButton', [['clearChat', []], ['toggleSettings', []]]],
    ['workflow Save', 'nodeWorkflowSaveButton', [['saveNodeWorkflow', []]]],
    ['workflow Load', 'nodeWorkflowLoadButton', [['loadNodeWorkflow', []]]],
    ['clear active context', 'nodeClearContextButton', [['clearNodeContext', []]]],
    ['chat trace expand/collapse', 'nodeChatTraceButton', [['toggleChatTraceExpansion', []]]],
    ['chat autosave', 'nodeChatAutosaveButton', [['toggleChatAutosave', []]]],
    ['mute', 'nodeMuteButton', [['toggleDarkstarUiMuted', []]]],
    ['theme', 'nodeThemeButton', [['toggleDarkstarTheme', []]]],
    ['add custom section', 'workflowAddSectionButton', [['openWorkflowSectionSearch', []]]],
    ['hidden node-editor nav', 'tabNav', [['switchView', ['settings']]]],
    ['new tab', 'newTabButton', [['createNewTab', []]]],
    ['workspace toggle', 'workspaceToggle', [['toggleWorkspace', []]]],
    ['new project', 'projectAddButton', [['createNewProject', []]]],
    ['browser Back', 'offlineBrowserBack', [['offlineBrowserBack', []]]],
    ['browser Forward', 'offlineBrowserForward', [['offlineBrowserForward', []]]],
    ['browser Reload', 'offlineBrowserReload', [['offlineBrowserReload', []]]],
    ['browser Go', 'offlineBrowserOpenButton', [['openOfflineBrowserAddress', []]]],
    ['browser choose local HTML', 'offlineBrowserChooseFileButton', [['chooseOfflineBrowserFile', []]]],
    ['browser reset session', 'offlineBrowserReset', [['resetBrowser', []]]],
    ['queue toggle', 'queueToggle', [['toggleQueue', []]]],
    ['remove image', 'removeImageButton', [['removeImage', []]]],
    ['choose active project directory', 'projectDirectoryChooseButton', [['chooseActiveProjectDirectory', []]]],
    ['send message', 'sendBtn', [['sendMessage', []]]],
    ['status view toggle', 'statusSettings', [['toggleStatusView', []]]],
    ['project delete Cancel', 'projectDeleteCancelButton', [['closeProjectDeleteModal', []]]],
    ['project delete Confirm', 'projectDeleteConfirmButton', [['confirmProjectDeleteModal', []]]],
    ['workspace delete Cancel', 'workspaceDeleteCancelButton', [['closeWorkspaceDeleteModal', []]]],
    ['workspace delete Confirm', 'workspaceDeleteConfirmButton', [['confirmWorkspaceDeleteModal', []]]],
];

for (const [name, id, expected] of staticCases) {
    test(`button execution: ${name} invokes the external handler with the original call signature`, () => {
        const h = harness();
        const handler = h.elements.get(id)?.listener('click');
        assert.equal(typeof handler, 'function', `${id} is not externally bound`);
        handler({ marker: 'click' });
        assert.deepEqual(h.calls, expected.map(([functionName, args]) => ({ name: functionName, args })));
    });
}


test('button execution: the primary composer control routes stop mode to stopGeneration', () => {
    const h = harness();
    const button = h.elements.get('sendBtn');
    button.dataset.mode = 'stop';
    const handler = button.listener('click');
    assert.equal(typeof handler, 'function');
    handler({ currentTarget: button });
    assert.deepEqual(h.calls, [{ name: 'stopGeneration', args: [] }]);
});

for (const effort of ['off', 'low', 'medium', 'high']) {
    test(`button execution: thinking effort ${effort} passes only the declared effort`, () => {
        const h = harness();
        h.efforts.find((button) => button.dataset.effort === effort).listener('click')({ marker: 'click' });
        assert.deepEqual(h.calls, [{ name: 'setThinkingEffort', args: [effort] }]);
    });
}

test('button execution: generation action deliberately receives the click event', () => {
    const h = harness();
    const event = { ctrlKey: true };
    h.elements.get('scheduleBtn').listener('click')(event);
    assert.equal(h.calls.length, 1);
    assert.equal(h.calls[0].name, 'handleGenerationAction');
    assert.equal(h.calls[0].args[0], event);
});

test('button execution: browser Enter-address affordance focuses the address input', () => {
    const h = harness();
    h.elements.get('offlineBrowserFocusAddressButton').listener('click')({});
    assert.equal(h.elements.get('offlineBrowserAddress').focusCalls, 1);
});

test('button execution: image upload affordance opens the Darkstar image browser entry point', () => {
    const h = harness();
    h.elements.get('imageUploadButton').listener('click')({});
    assert.deepEqual(h.calls, [{ name: 'chooseComposerImage', args: [] }]);
    assert.equal(h.elements.get('imageInput').nativeClicks, 0, 'the native hidden file input must never be opened by the composer button');
});

test('composer scrollbar is suppressed while auto-growing and restored only above the 200px cap', () => {
    const h = harness();
    const input = h.elements.get('messageInput');
    const onInput = input.listener('input');
    assert.equal(typeof onInput, 'function');

    input.scrollHeight = 40;
    onInput.call(input);
    assert.equal(input.style.height, '40px');
    assert.equal(input.style.overflowY, 'hidden', 'short composer must not instantiate native scrollbar chrome at fractional Windows DPI');

    input.scrollHeight = 320;
    onInput.call(input);
    assert.equal(input.style.height, '200px');
    assert.equal(input.style.overflowY, 'auto', 'long drafts must retain a real vertical scrollbar');

    input.scrollHeight = 60;
    onInput.call(input);
    assert.equal(input.style.overflowY, 'hidden', 'shrinking a long draft must remove the scrollbar again');
});

test('composer CSS avoids the standardized/native scrollbar path while preserving the custom long-text scrollbar', () => {
    const styles = fs.readFileSync(path.join(root, 'backend', 'shell', 'styles.css'), 'utf8');
    const composerRule = styles.match(/\.input-wrapper textarea\s*\{([^}]*)\}/m);
    assert.ok(composerRule);
    assert.match(composerRule[1], /overflow-y\s*:\s*hidden\s*;/u);
    assert.doesNotMatch(composerRule[1], /scrollbar-(?:width|color)\s*:/u,
        'standard scrollbar properties must not override the Chromium author scrollbar rules');
    assert.match(styles, /\.input-wrapper textarea::-webkit-scrollbar\s*\{[^}]*width\s*:\s*6px\s*;/u);
    assert.match(styles, /\.input-wrapper textarea::-webkit-scrollbar-button\s*\{[^}]*display\s*:\s*none\s*;[^}]*width\s*:\s*0\s*;[^}]*height\s*:\s*0\s*;/u);
});

test('every composer reset returns overflow to the short-draft hidden state', () => {
    const renderer = fs.readFileSync(path.join(root, 'backend', 'Darkstar_Renderer.js'), 'utf8');
    const resetWrites = [...renderer.matchAll(/(?:input|scheduledInput)\.style\.height = 'auto';([^\n]*)/gu)];
    assert.ok(resetWrites.length >= 11, 'expected all composer clear/restore paths to remain covered after centralizing tab-draft restoration');
    for (const match of resetWrites) {
        assert.match(match[1], /overflowY\s*=\s*'hidden'/u, 'composer height reset must synchronously suppress native vertical scrollbar chrome');
    }
    assert.match(renderer, /Math\.min\(input\.scrollHeight(?: \|\| 0)?, 200\) \+ 'px'; input\.style\.overflowY = \(?input\.scrollHeight/u,
        'programmatic composer insertion/restore must restore overflow only when content exceeds the cap');
});

test('static HTML contains no executable inline event attributes', () => {
    assert.doesNotMatch(html, /\son[a-z]+\s*=/iu);
});
});

