test('generation, title generation, and compaction never dereference the mutable node-services stream API at execution time', () => {
    const production = [
        'backend/renderer/nodes/builtin/sampler.js',
        'backend/renderer/send.js',
        'backend/renderer/commands.js',
        'backend/renderer/node-registry.js'
    ];
    for (const rel of production) {
        const text = source(rel);
        assert.doesNotMatch(text, /(?:Darkstar\.)?nodes\.services\.(?:streamChat|makeRequestId|copyToolContext)\s*\(/u, rel);
    }
    const servicesSource = source('backend/renderer/nodes/services.js');
    assert.match(servicesSource, /namespace\.chatRuntime\s*=\s*serviceApi/u);
    assert.match(servicesSource, /nodes\.services\s*=\s*serviceApi/u, 'legacy/custom-node compatibility alias must remain');
    assert.doesNotMatch(servicesSource, /applyPruningToTimeline:\s*applyPruningToTimeline/u, 'deleted reasoning-pruning symbol must never return to the startup export');
    assert.match(source('backend/renderer/nodes/builtin/sampler.js'), /var chatRuntime = root\.Darkstar\.chatRuntime \|\| nodes\.services/u);
    assert.match(source('backend/renderer/send.js'), /var darkstarChatRuntime[\s\S]*Darkstar\.chatRuntime/u);
    assert.match(source('backend/renderer/commands.js'), /var chatRuntime = root\.Darkstar[\s\S]*root\.Darkstar\.chatRuntime/u);
});

