// TEST MODULE: backend/Dev/tests/generation-token-rate-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/generation-token-rate-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..', '..', '..');
const generationUiSource = fs.readFileSync(path.join(root, 'backend/renderer/generation-ui.js'), 'utf8');
const { mergeUsage } = require(path.join(root, 'backend/runtime/tokens.js'));

function metricsHarness() {
    let now = 0;
    const context = {
        console,
        Date,
        Map,
        Set,
        JSON,
        Math,
        Number,
        String,
        Boolean,
        Array,
        Object,
        RegExp,
        performance: { now() { return now; } },
        setTimeout() { return 1; },
        clearTimeout() {},
    };
    context.window = context;
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(generationUiSource, context, { filename: 'generation-ui.js' });
    return {
        context,
        setNow(value) { now = value; },
    };
}

test('aggregate llama timings derive one weighted generation rate instead of adding per-second values', () => {
    const first = {
        completion_tokens: 130,
        timings: { predicted_n: 130, predicted_ms: 10_000, predicted_per_second: 13 },
    };
    const second = {
        completion_tokens: 260,
        timings: { predicted_n: 260, predicted_ms: 20_000, predicted_per_second: 13 },
    };
    const merged = mergeUsage(mergeUsage(null, first), second);
    assert.equal(merged.completion_tokens, 390);
    assert.equal(merged.timings.predicted_n, 390);
    assert.equal(merged.timings.predicted_ms, 30_000);
    assert.equal(merged.timings.predicted_per_second, 13,
        'derived throughput is weighted by aggregate generated tokens/time, never summed to 26 tok/s');
});

test('llama streaming forwards timing-only token frames instead of dropping them with empty visible text', async () => {
    const { consumeChatCompletionStream } = require(path.join(root, 'backend/runtime/streaming.js'));
    const encoder = new TextEncoder();
    const payload = [
        'data: ' + JSON.stringify({ choices: [{ delta: { role: 'assistant' } }], timings: { predicted_n: 1, predicted_ms: 250, predicted_per_second: 24 } }) + '\n\n',
        'data: ' + JSON.stringify({ choices: [{ delta: { content: 'hello' } }], timings: { predicted_n: 2, predicted_ms: 500, predicted_per_second: 24 } }) + '\n\n',
        'data: [DONE]\n\n',
    ].join('');
    let delivered = false;
    const reader = {
        async read() {
            if (delivered) return { done: true, value: undefined };
            delivered = true;
            return { done: false, value: encoder.encode(payload) };
        },
        async cancel() {},
    };
    const samples = [];
    const result = await consumeChatCompletionStream({ body: { getReader() { return reader; } } }, {
        onChunk(chunk) { if (chunk.tokenTiming) samples.push(structuredClone(chunk.tokenTiming)); },
    });

    assert.deepEqual(samples, [
        { generatedTokens: 1, generatedMs: 250, generatedPerSecond: 24 },
        { generatedTokens: 2, generatedMs: 500, generatedPerSecond: 24 },
    ]);
    assert.equal(result.text, 'hello');
});

test('TPS is zero until five exact generated-token timing samples exist', () => {
    const harness = metricsHarness();
    const tab = { tokensPerSecond: 99 };
    const published = [];
    const tracker = harness.context.Darkstar.generationMetrics.createTokenRateTracker(tab, (value) => published.push(value));

    tracker.resetRound();
    for (let n = 1; n <= 4; n += 1) {
        tracker.recordTokenTiming({ generatedTokens: n, generatedMs: n * 90, generatedPerSecond: 11.1 });
    }

    assert.equal(tab.tokensPerSecond, 0);
    assert.ok(published.every((value) => value === 0));
});

test('TPS publishes llama.cpp native predicted_per_second after the five-token gate', () => {
    const harness = metricsHarness();
    const tab = { tokensPerSecond: 0 };
    const tracker = harness.context.Darkstar.generationMetrics.createTokenRateTracker(tab);

    tracker.resetRound();
    const nativeRates = [3.1, 3.5, 3.7, 3.9, 4.02];
    for (let n = 1; n <= 5; n += 1) {
        // Deliberately make renderer wall time and predicted_ms disagree with the
        // authoritative llama.cpp rate. Neither is allowed to define displayed TPS.
        harness.setNow(n * 3_000);
        tracker.recordTokenTiming({ generatedTokens: n, generatedMs: n * 90, generatedPerSecond: nativeRates[n - 1] });
    }
    assert.equal(tab.tokensPerSecond, 4.02);
});

test('TPS tracks the latest native llama.cpp generation rate, not renderer delivery cadence', () => {
    const harness = metricsHarness();
    const tab = { tokensPerSecond: 0 };
    const tracker = harness.context.Darkstar.generationMetrics.createTokenRateTracker(tab);

    tracker.resetRound();
    for (let n = 1; n <= 5; n += 1) {
        harness.setNow(n * 250);
        tracker.recordTokenTiming({ generatedTokens: n, generatedMs: n * 80, generatedPerSecond: 6.25 });
    }
    assert.equal(tab.tokensPerSecond, 6.25);

    // Renderer/UI delivery now becomes much slower. Native decode throughput is
    // unchanged, so the displayed rate must remain the value reported by llama.cpp.
    for (let n = 6; n <= 10; n += 1) {
        harness.setNow(10_000 + n * 2_000);
        tracker.recordTokenTiming({ generatedTokens: n, generatedMs: 400 + n * 70, generatedPerSecond: 6.5 });
    }
    assert.equal(tab.tokensPerSecond, 6.5);
});

test('TPS ignores TTFT, renderer scheduling, visible text size, and usage totals', () => {
    const harness = metricsHarness();
    const tab = { tokensPerSecond: 0 };
    const tracker = harness.context.Darkstar.generationMetrics.createTokenRateTracker(tab);

    harness.setNow(50_000); // arbitrary TTFT / UI delay before first token
    tracker.resetRound();
    for (let n = 1; n <= 5; n += 1) {
        harness.setNow(50_000 + n * 8_000);
        tracker.recordTokenTiming({ generatedTokens: n, generatedMs: n * 25, predicted_per_second: 7.75 });
    }
    const finalRate = tracker.finalize({
        completion_tokens: 5000,
        timings: { predicted_n: 5000, predicted_ms: 1000, predicted_per_second: 5000 },
    });

    assert.equal(finalRate, 7.75);
    assert.equal(tab.tokensPerSecond, 7.75);
});

test('TPS resets between model rounds and cannot blend two rounds', () => {
    const harness = metricsHarness();
    const tab = { tokensPerSecond: 0 };
    const tracker = harness.context.Darkstar.generationMetrics.createTokenRateTracker(tab);

    tracker.resetRound();
    for (let n = 1; n <= 5; n += 1) {
        tracker.recordTokenTiming({ generatedTokens: n, generatedMs: n * 50, generatedPerSecond: 10 });
    }
    assert.equal(tab.tokensPerSecond, 10);

    tracker.resetRound();
    assert.equal(tab.tokensPerSecond, 0);
    for (let n = 1; n <= 4; n += 1) {
        tracker.recordTokenTiming({ generatedTokens: n, generatedMs: n * 20, generatedPerSecond: 2 });
    }
    assert.equal(tab.tokensPerSecond, 0);
    tracker.recordTokenTiming({ generatedTokens: 5, generatedMs: 100, generatedPerSecond: 2 });
    assert.equal(tab.tokensPerSecond, 2);
});

test('duplicate, malformed, missing, or non-native timing frames cannot create bogus TPS', () => {
    const harness = metricsHarness();
    const tab = { tokensPerSecond: 0 };
    const tracker = harness.context.Darkstar.generationMetrics.createTokenRateTracker(tab);

    tracker.resetRound();
    for (let n = 1; n <= 5; n += 1) {
        tracker.recordTokenTiming({ generatedTokens: n, generatedMs: n * 20, generatedPerSecond: 5 });
    }
    assert.equal(tab.tokensPerSecond, 5);

    tracker.recordTokenTiming({ generatedTokens: 5, generatedMs: 1, generatedPerSecond: 9999 });
    tracker.recordTokenTiming({ generatedTokens: 6, generatedMs: Number.NaN, generatedPerSecond: 9999 });
    tracker.recordTokenTiming({ generatedTokens: 6, generatedMs: -10, generatedPerSecond: 9999 });
    assert.equal(tab.tokensPerSecond, 5);

    // A gap means the five-exact-token contract cannot be satisfied yet.
    tracker.recordTokenTiming({ generatedTokens: 7, generatedMs: 140, generatedPerSecond: 9999 });
    assert.equal(tab.tokensPerSecond, 0);

    // Even with five exact timing samples, Darkstar must not invent a rate when
    // llama.cpp did not provide its native predicted_per_second metric.
    tracker.resetRound();
    for (let n = 1; n <= 5; n += 1) tracker.recordTokenTiming({ generatedTokens: n, generatedMs: n * 10 });
    assert.equal(tab.tokensPerSecond, 0);
});

test('renderer wires exact timing telemetry to TPS and never calls text-based accounting in send', () => {
    const services = fs.readFileSync(path.join(root, 'backend/renderer/nodes/services.js'), 'utf8');
    const send = fs.readFileSync(path.join(root, 'backend/renderer/send.js'), 'utf8');

    assert.match(services, /payload\.tokenTiming[\s\S]*context\.onTokenTiming/u);
    assert.match(send, /onTokenTiming:\s*function\(sample\)[\s\S]*tokenRate\.recordTokenTiming\(sample\)/u);
    assert.doesNotMatch(send, /tokenRate\.recordText\(/u, 'visible text chunks must never be used as token boundaries');
});


});

