// TEST MODULE: backend/Dev/tests/generation-ui-coordinator-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/generation-ui-coordinator-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const streamSource = fs.readFileSync(path.join(__dirname, '..', '..', 'renderer', 'generation-stream-surface.js'), 'utf8');
const source = fs.readFileSync(path.join(__dirname, '..', '..', 'renderer', 'generation-ui.js'), 'utf8');

function fixture(options = {}) {
    let now = 100;
    let active = true;
    let current = true;
    let mounted = null;
    let frame = null;
    let frameId = 0;
    const calls = { add: 0, timeline: [], tokens: 0, scrolls: 0, cancelled: [] };
    const contentDiv = {
        innerHTML: '',
        querySelector(selector) {
            return selector === '.typing-indicator' && /typing-indicator/u.test(this.innerHTML) ? {} : null;
        },
    };
    const assistantDiv = {
        dataset: {},
        classList: { add() {} },
        querySelector(selector) {
            return selector === '.message-answer' ? contentDiv : null;
        },
    };
    const container = { contains: (element) => element === mounted };
    const sandbox = {
        Darkstar: {},
        Date,
        setTimeout,
        clearTimeout,
        performance: { now: () => now },
        document: {
            getElementById(id) { return id === 'chatContainer' ? container : null; },
            querySelector() { return options.continuingFinalMessage === true ? assistantDiv : null; },
        },
        window: {
            requestAnimationFrame(callback) {
                frame = callback;
                frameId += 1;
                return frameId;
            },
            cancelAnimationFrame(id) { calls.cancelled.push(id); },
        },
    };
    sandbox.globalThis = sandbox;
    vm.runInNewContext(streamSource, sandbox, { filename: 'generation-stream-surface.js' });
    vm.runInNewContext(source, sandbox, { filename: 'generation-ui.js' });

    const session = {
        id: 7,
        assistantIndex: 3,
        responseText: '',
        agentTimeline: [],
    };
    const coordinator = sandbox.Darkstar.generationUi.createCoordinator({
        session,
        continuingFinalMessage: options.continuingFinalMessage === true,
        addMessage(options) {
            calls.add += 1;
            calls.addOptions = { ...options };
            mounted = assistantDiv;
            return assistantDiv;
        },
        formatMessage(value) { return `<formatted>${value}</formatted>`; },
        updateMessageAgentTimeline(_element, timeline) { calls.timeline.push(timeline); },
        updateTokenCounter() { calls.tokens += 1; },
        smartScrollToBottom() { calls.scrolls += 1; },
        isCurrent: () => current,
        isActiveTab: () => active,
        displayRole: () => 'assistant',
    });
    return {
        assistantDiv,
        calls,
        contentDiv,
        coordinator,
        session,
        setActive(value) { active = value; },
        setCurrent(value) { current = value; },
        setNow(value) { now = value; },
        detach() { mounted = null; },
        takeFrame() { const pending = frame; frame = null; return pending; },
    };
}

test('generation UI mounts once and coalesces answer, timeline, and token-counter paints into one frame', () => {
    const state = fixture();
    state.coordinator.mount();
    assert.equal(state.calls.add, 1);
    assert.equal(state.calls.addOptions.role, 'assistant');
    assert.equal(state.calls.addOptions.messageIndex, 3);
    assert.match(state.contentDiv.innerHTML, /typing-indicator/u);

    state.session.responseText = 'hello';
    const timeline = [{ id: 'reasoning-1', type: 'reasoning' }];
    state.coordinator.queueAnswer();
    state.coordinator.queueTimeline(timeline);
    state.coordinator.queueTokenCounter();
    const paint = state.takeFrame();
    assert.equal(typeof paint, 'function', 'all pending work should share a single animation frame');
    paint();

    assert.equal(state.contentDiv.innerHTML, '<formatted>hello</formatted><div class="typing-indicator"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>');
    assert.deepEqual(state.calls.timeline.at(-1), timeline);
    assert.equal(state.calls.tokens, 1);
    assert.equal(state.calls.scrolls, 1);
    assert.equal(state.calls.add, 1, 'painting should reuse the mounted message');
});

test('generation UI paints semantic timeline boundaries on the next frame instead of waiting for the streaming throttle', () => {
    const state = fixture();
    state.coordinator.mount();
    state.coordinator.queueTimeline([{ id: 'initial', type: 'reasoning' }]);
    const initialPaint = state.takeFrame();
    assert.equal(typeof initialPaint, 'function');
    initialPaint();

    state.setNow(110);
    state.coordinator.queueTimeline([{ id: 'coalesced', type: 'reasoning' }]);
    assert.equal(state.takeFrame(), null, 'ordinary streaming updates should remain throttled');

    const boundary = [{ id: 'tool-1', type: 'tool-call', state: 'streaming', status: 'running' }];
    state.coordinator.queueTimelineBoundary(boundary);
    const boundaryPaint = state.takeFrame();
    assert.equal(typeof boundaryPaint, 'function', 'a reasoning/tool phase boundary must bypass the 50 ms throttle');
    boundaryPaint();
    assert.deepEqual(state.calls.timeline.at(-1), boundary);
});

test('generation UI reasserts the activity spinner idempotently throughout an active generation', () => {
    const state = fixture();
    state.coordinator.mount();
    assert.equal(state.calls.add, 1);
    assert.match(state.contentDiv.innerHTML, /typing-indicator/u);

    state.coordinator.ensureTypingVisible();
    assert.equal(state.calls.add, 1, 'an already-mounted spinner must not be recreated');

    state.contentDiv.innerHTML = '';
    state.coordinator.ensureTypingVisible();
    assert.match(state.contentDiv.innerHTML, /typing-indicator/u, 'prefill feedback must be recoverable if the indicator DOM is cleared');

    state.session.responseText = 'model output';
    state.contentDiv.innerHTML = '<formatted>model output</formatted>';
    state.coordinator.ensureTypingVisible();
    assert.match(state.contentDiv.innerHTML, /^<formatted>model output<\/formatted>.*typing-indicator/u, 'active generation feedback must remain after generated answer content');
});

test('generation UI keeps the spinner across tab restore and answer streaming until generation retirement', () => {
    const state = fixture();
    state.coordinator.mount();
    assert.match(state.contentDiv.innerHTML, /typing-indicator/u);

    state.setActive(false);
    state.detach();
    state.session.responseText = '\n   ';
    state.setActive(true);
    state.coordinator.mount();
    assert.match(state.contentDiv.innerHTML, /typing-indicator/u, 'tab restoration must treat whitespace-only streamed answer state as still waiting');

    state.coordinator.queueAnswer();
    const whitespacePaint = state.takeFrame();
    assert.equal(typeof whitespacePaint, 'function');
    whitespacePaint();
    assert.match(state.contentDiv.innerHTML, /typing-indicator/u, 'a delayed whitespace-only answer paint must not erase the restored spinner');

    state.setNow(200);
    state.session.responseText = 'visible answer';
    state.coordinator.queueAnswer();
    const answerPaint = state.takeFrame();
    assert.equal(typeof answerPaint, 'function');
    answerPaint();
    assert.match(state.contentDiv.innerHTML, /^<formatted>visible answer<\/formatted>.*typing-indicator/u, 'real visible answer content must stream while the active-generation spinner remains present');
});

test('generation UI keeps the spinner on an existing assistant message during continuation', () => {
    const state = fixture({ continuingFinalMessage: true });
    state.session.responseText = 'existing answer';
    state.session.continuationBaseText = 'existing answer';
    state.coordinator.mount();
    assert.match(state.contentDiv.innerHTML, /^<formatted>existing answer<\/formatted>.*typing-indicator/u, 'continuation work must retain the existing answer and append the live activity spinner');
});

test('generation UI drops queued DOM work after a tab switch and closes idempotently', () => {
    const state = fixture();
    state.coordinator.mount();
    state.session.responseText = 'detached';
    state.coordinator.queueAnswer();
    state.coordinator.queueTimeline([{ id: 't1' }]);
    state.coordinator.queueTokenCounter();
    const paint = state.takeFrame();
    state.setActive(false);
    paint();

    assert.match(state.contentDiv.innerHTML, /typing-indicator/u, 'inactive tabs must not mutate their detached chat tree');
    assert.equal(state.calls.timeline.length, 0);
    assert.equal(state.calls.tokens, 0);
    assert.equal(state.calls.scrolls, 0);

    state.coordinator.close();
    state.coordinator.close();
    state.coordinator.queueAnswer();
    assert.equal(state.takeFrame(), null, 'closed coordinators must not schedule new paints');
});

test('generation UI refuses stale generations before mounting', () => {
    const state = fixture();
    state.setCurrent(false);
    assert.equal(state.coordinator.mount(), null);
    assert.equal(state.calls.add, 0);
});
});

