// TEST MODULE: backend/Dev/tests/generation-ui-responsiveness-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/generation-ui-responsiveness-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const projectRoot = path.resolve(__dirname, '..', '..', '..');
const sendSource = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'send.js'), 'utf8');
const generationStreamSource = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'generation-stream-surface.js'), 'utf8');
const generationUiSource = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'generation-ui.js'), 'utf8');
const servicesSource = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'nodes', 'services.js'), 'utf8');
const chatSource = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'chat.js'), 'utf8');
const effectsSource = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'effects.js'), 'utf8');
const stylesSource = fs.readFileSync(path.join(projectRoot, 'backend', 'shell', 'styles.css'), 'utf8');

function sourceBetween(source, startMarker, endMarker) {
    const start = source.indexOf(startMarker);
    const end = source.indexOf(endMarker, start + startMarker.length);
    assert.notEqual(start, -1, `Missing source marker: ${startMarker}`);
    assert.notEqual(end, -1, `Missing source marker: ${endMarker}`);
    return source.slice(start, end);
}

test('streamed answer tokens delegate bounded UI painting instead of reparsing the DOM per token', () => {
    const onToken = sourceBetween(sendSource, 'onToken: function(token, fullResponse) {', 'onReasoningToken: function(token, fullReasoning) {');
    assert.match(onToken, /generationUi\.queueAnswer\(\)/);
    assert.doesNotMatch(onToken, /formatMessage\(/);
    assert.doesNotMatch(onToken, /innerHTML\s*=/);
    assert.doesNotMatch(onToken, /smartScrollToBottom\(/);
});

test('streaming answer, reasoning timeline, and token counter share one frame-coalesced coordinator', () => {
    assert.match(generationUiSource, /STREAM_UI_MIN_INTERVAL_MS\s*=\s*50/);
    assert.match(generationUiSource, /paintTimer/);
    assert.match(generationUiSource, /paintFrame/);
    assert.match(generationUiSource, /requestAnimationFrame\(\(\) => this\.flushPaint\(\)\)/);
    assert.match(generationUiSource, /this\.streamController\.paint\(\)/);
    assert.match(generationStreamSource, /surface\.appendChild\(root\.document\.createTextNode\(delta\)\)/);
    assert.match(generationStreamSource, /STREAM_PREFIX_GUARD_CHARS\s*=\s*64/);
    assert.match(generationStreamSource, /live\.slice\(renderedStreamLength\)/);
    assert.doesNotMatch(generationStreamSource, /startsWith\(renderedStreamText\)|renderedStreamText\s*=\s*live/u,
        'streaming must not compare or retain the entire accumulated response on every paint');
    assert.match(generationUiSource, /this\.updateMessageAgentTimeline\(this\.assistantDiv, this\.timelineForDisplay\(this\.pendingTimeline\)\)/);
    assert.match(generationUiSource, /pendingTokenCounter/);
    assert.match(sendSource, /generationUi\.queueTimeline\(session\.agentTimeline\)/);
    assert.match(sendSource, /payload\.activity \|\| payload\.preparation[\s\S]*session\.phase = 'tool'/u, 'every concrete tool lifecycle event must move presentation out of the model/reasoning phase');
    assert.match(sendSource, /imagePhaseChanged[\s\S]*generationUi\.queueTimelineBoundary\(session\.agentTimeline\)/u, 'image runtime phase changes must paint as semantic UI boundaries');
    assert.match(sendSource, /generationUi\.queueTokenCounter\(\)/);
    assert.match(sendSource, /contentDiv\.innerHTML = formatMessage\(fullResponse\)/, 'terminal finalization must retain exact Markdown rendering');
});

test('live answer streaming appends only new text and never reparses the accumulated response', () => {
    class Element {
        constructor(tag) { this.tagName = tag; this.children = []; this.parent = null; this.className = ''; this.attributes = {}; this._text = ''; this.isConnected = true; }
        appendChild(child) { child.parent = this; this.children.push(child); return child; }
        insertBefore(child, before) { child.parent = this; const index = this.children.indexOf(before); this.children.splice(index < 0 ? this.children.length : index, 0, child); return child; }
        querySelector(selector) { const className = selector.startsWith('.') ? selector.slice(1) : ''; return this.children.find((child) => child.className === className) || null; }
        setAttribute(name, value) { this.attributes[name] = String(value); }
        remove() { if (this.parent) this.parent.children = this.parent.children.filter((child) => child !== this); this.isConnected = false; }
        set textContent(value) { this._text = String(value); this.children = []; }
        get textContent() { return this._text + this.children.map((child) => child.textContent || child.data || '').join(''); }
    }
    const createdText = [];
    const sandbox = {
        Darkstar: {}, performance: { now() { return 1; } }, setTimeout,
        document: {
            createElement(tag) { return new Element(tag); },
            createTextNode(value) { const node = { data: String(value), textContent: String(value), parent: null }; createdText.push(node.data); return node; },
        },
    };
    sandbox.globalThis = sandbox;
    vm.runInNewContext(generationStreamSource, sandbox, { filename: 'generation-stream-surface.js' });
    const session = { responseText: '' };
    let formatCalls = 0;
    const controller = sandbox.Darkstar.generationStreamSurface.create({ session, formatMessage(value) { formatCalls += 1; return '<p>' + value + '</p>'; } });
    const content = new Element('div');
    controller.attach(content);
    controller.showTyping();
    session.responseText = 'hello'; controller.paint();
    session.responseText = 'hello world'; controller.paint();
    const surface = content.querySelector('.generation-stream-text');
    assert.ok(surface);
    assert.equal(surface.textContent, 'hello world');
    assert.deepEqual(createdText, ['hello', ' world'], 'only the newly arrived suffix should allocate text nodes');

    // A rewritten prefix is rare but must still fall back to exact replacement,
    // after which normal suffix-only streaming resumes from the new cursor.
    session.responseText = 'jello world'; controller.paint();
    assert.equal(surface.textContent, 'jello world');
    session.responseText = 'jello world!'; controller.paint();
    assert.equal(surface.textContent, 'jello world!');
    assert.deepEqual(createdText, ['hello', ' world', '!']);
    assert.equal(formatCalls, 0, 'live streaming must not re-run Markdown formatting over accumulated output');
});

test('reasoning trace identity advances incrementally and remains byte-for-byte compatible with the legacy full hash', () => {
    const traceFunctions = sourceBetween(servicesSource, 'function traceTextKey(value) {', 'function imageSourceKey(source) {');
    const sandbox = {};
    vm.runInNewContext(traceFunctions + '\nthis.__trace = { traceTextKey, extendTraceTextKey };', sandbox, { filename: 'reasoning-trace-key.js' });
    const chunks = ['Reason ', 'over ', 'a long ', 'sequence ', 'without rescanning it.'];
    const state = { length: 0, hash: 2166136261 };
    let incremental = '';
    for (const chunk of chunks) incremental = sandbox.__trace.extendTraceTextKey(state, chunk);
    assert.equal(incremental, sandbox.__trace.traceTextKey(chunks.join('')),
        'incremental hashing must preserve the exact persisted/rendered trace key contract');
    assert.match(servicesSource, /extendTraceTextKey\(traceState, reasoning\)/u);
    assert.doesNotMatch(servicesSource, /traceTextKey\(ensured\.segment\.content\)/u,
        'the growing reasoning buffer must never be re-hashed from the beginning per token');
});

test('hidden tool preparation does not force an extra synchronous transcript layout per event', () => {
    const onToolEvent = sourceBetween(sendSource,
        'onToolEvent: function(payload, working, timeline, toolContext) {',
        'onAgentTimeline: function(timeline) {');
    const smartScroll = sourceBetween(chatSource, 'function smartScrollToBottom() {', 'const ADD_MESSAGE_OPTION_NAMES');
    assert.doesNotMatch(onToolEvent, /smartScrollToBottom\(/u,
        'tool preparation must use the coalesced timeline painter instead of scrolling immediately');
    assert.match(smartScroll, /container\.scrollTop\s*=\s*2147483647/u);
    assert.doesNotMatch(smartScroll, /container\.scrollTop\s*=\s*container\.scrollHeight/u,
        'follow-mode scrolling must not synchronously read scrollHeight every streamed paint');
});

test('prompt-processing context heartbeats keep the spinner visible while the token counter advances', () => {
    const onContextUsage = sourceBetween(sendSource, 'onContextUsage: function(usage) {', 'onTokenTiming: function(sample) {');
    assert.match(onContextUsage, /session\.phase === 'model'[\s\S]*generationUi\.ensureTypingVisible\(\)/u);
    assert.ok(
        onContextUsage.indexOf('generationUi.ensureTypingVisible()') < onContextUsage.indexOf('generationUi.queueTokenCounter()'),
        'prefill activity feedback must be asserted before the token-counter paint is queued'
    );
});

test('terminal generation spinner remains animated when Windows reports reduced motion', () => {
    const reducedMotionSpinner = stylesSource.match(/@media \(prefers-reduced-motion: reduce\) \{\s*\.typing-indicator::before \{([^}]*)\}/u);
    assert.ok(reducedMotionSpinner, 'the spinner must explicitly own its reduced-motion behavior');
    assert.match(reducedMotionSpinner[1], /animation:\s*terminalSpinner\s+640ms\s+steps\(1, end\)\s+infinite/u);
    assert.doesNotMatch(reducedMotionSpinner[1], /animation:\s*none/u);
    assert.doesNotMatch(reducedMotionSpinner[1], /content:\s*"\|"/u);
});

test('decorative proximity glow does no layout work while the primary mouse button is dragging', () => {
    const mouseMove = sourceBetween(effectsSource, "document.addEventListener('mousemove', function(e) {", '// Assign one independently selected landing-screen quote');
    const dragGuard = mouseMove.indexOf('(Number(e.buttons) & 1) !== 0');
    const layoutQuery = mouseMove.indexOf("document.querySelectorAll('.message-avatar .chevron-glow");
    assert.ok(dragGuard >= 0, 'expected an active-drag guard');
    assert.ok(layoutQuery >= 0, 'expected the proximity-glow layout query');
    assert.ok(dragGuard < layoutQuery, 'drag guard must run before proximity-glow layout work');
    assert.match(mouseMove.slice(dragGuard, layoutQuery), /return;/);
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/hidden-browser-viewport-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/hidden-browser-viewport-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const test = require('node:test');
const { EventEmitter } = require('node:events');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const { OfflineBrowserService, DEFAULT_CAPTURE_VIEWPORT } = require('../../browser/offline-browser-service');

class FakeSession extends EventEmitter {
    constructor() {
        super();
        this.webRequest = { onBeforeRequest() {} };
    }
    setPermissionCheckHandler() {}
    setPermissionRequestHandler() {}
}

class FakeDebugger extends EventEmitter {
    constructor() {
        super();
        this.attached = false;
        this.commands = [];
    }
    isAttached() { return this.attached; }
    attach() { this.attached = true; }
    detach() { this.attached = false; this.emit('detach'); }
    async sendCommand(name, params) {
        this.commands.push({ name, params: params ? structuredClone(params) : undefined });
        if (name === 'Page.captureScreenshot') {
            return { data: Buffer.from('synthetic-hidden-browser-frame').toString('base64') };
        }
        return {};
    }
}

class FakeWebContents extends EventEmitter {
    constructor() {
        super();
        this.session = new FakeSession();
        this.debugger = new FakeDebugger();
    }
    setAudioMuted() {}
    setZoomFactor() {}
    setWindowOpenHandler() {}
    canGoBack() { return false; }
    canGoForward() { return false; }
    isDestroyed() { return false; }
    async capturePage() {
        return {
            toPNG: () => Buffer.alloc(0),
            getSize: () => ({ width: 0, height: 0 }),
        };
    }
}

class FakeBrowserView {
    constructor() {
        this.webContents = new FakeWebContents();
        this.bounds = { x: 0, y: 0, width: 0, height: 0 };
    }
    setAutoResize() {}
    setBounds(bounds) { this.bounds = { ...bounds }; }
    getBounds() { return { ...this.bounds }; }
}

class FakeWindow extends EventEmitter {
    constructor() {
        super();
        this.webContents = { send() {}, focus() {} };
        this.contentBounds = { x: 0, y: 0, width: 1200, height: 800 };
    }
    isDestroyed() { return false; }
    getContentBounds() { return { ...this.contentBounds }; }
    setBrowserView(view) { this.view = view; }
    removeBrowserView(view) { if (this.view === view) this.view = null; }
}

function fixture(options = {}) {
    const service = new OfflineBrowserService({ BrowserView: FakeBrowserView, baseDir: path.resolve(__dirname, '..', '..', '..'), ...options });
    service.attachWindow(new FakeWindow());
    return { service, view: service.view };
}

test('hidden browser keeps a nonzero viewport through native BrowserView bounds without DevTools device emulation', () => {
    const { service, view } = fixture();
    assert.equal(service.visible, false);

    const actual = service._syncHiddenViewportBounds();

    assert.ok(actual.x > 1200, 'hidden native surface must be parked beyond the visible content width');
    assert.equal(actual.y, DEFAULT_CAPTURE_VIEWPORT.y);
    assert.equal(actual.width, DEFAULT_CAPTURE_VIEWPORT.width);
    assert.equal(actual.height, DEFAULT_CAPTURE_VIEWPORT.height);
    assert.deepEqual(view.getBounds(), actual);
    assert.equal(view.webContents.debugger.commands.some((entry) => entry.name.startsWith('Emulation.')), false);
    return service.destroy();
});

test('hidden viewport setup does not attach the debugger or enter Chromium Emulation', async () => {
    const { service, view } = fixture({ browserProbeTimeoutMs: 25 });
    const originalSend = view.webContents.debugger.sendCommand.bind(view.webContents.debugger);
    view.webContents.debugger.sendCommand = async (name, params) => {
        if (name === 'Page.enable') return new Promise(() => {});
        return originalSend(name, params);
    };

    const started = Date.now();
    service._syncHiddenViewportBounds();
    const elapsed = Date.now() - started;

    assert.ok(elapsed < 50, `native viewport setup should be synchronous and cheap (elapsed ${elapsed} ms)`);
    assert.equal(view.webContents.debugger.isAttached(), false);
    assert.equal(view.webContents.debugger.commands.length, 0);
    await service.destroy();
});

test('browser_control open succeeds even when Page.enable would hang before navigation', async () => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-browser-open-'));
    const htmlPath = path.join(root, 'Flappy.html');
    fs.writeFileSync(htmlPath, '<!doctype html><title>Flappy</title>');
    const workspace = {
        getRoot: () => root,
        rootPath: root,
        resolvePath: async (relative) => path.resolve(root, relative),
    };
    const { service, view } = fixture({ browserProbeTimeoutMs: 25, browserSettleTimeoutMs: 50, browserTotalTimeoutMs: 250 });
    const originalSend = view.webContents.debugger.sendCommand.bind(view.webContents.debugger);
    view.webContents.debugger.sendCommand = async (name, params) => {
        if (name === 'Page.enable') return new Promise(() => {});
        return originalSend(name, params);
    };
    view.webContents.loadFile = async () => {
        queueMicrotask(() => view.webContents.emit('dom-ready'));
    };
    view.webContents.executeJavaScript = async (source) => {
        if (String(source).includes('document.fonts')) return undefined;
        return {
            title: 'Flappy',
            viewport: { width: DEFAULT_CAPTURE_VIEWPORT.width, height: DEFAULT_CAPTURE_VIEWPORT.height },
            scroll: { x: 0, y: 0 },
            activeRef: '',
            elements: [],
            truncated: false,
        };
    };

    try {
        const started = Date.now();
        const result = await service.controlBrowser(
            { action: 'open', path: 'Flappy.html' },
            { workspace, workspaceId: 'default', interactionId: 'open-regression' },
        );
        const elapsed = Date.now() - started;
        assert.equal(result.success, true);
        assert.equal(result.action, 'open');
        assert.ok(elapsed < 200, `open should not wait on Page.enable (elapsed ${elapsed} ms)`);
        assert.equal(view.webContents.debugger.commands.some((entry) => entry.name === 'Page.enable'), false);
        assert.equal(view.webContents.debugger.commands.some((entry) => entry.name.startsWith('Emulation.')), false);
        assert.ok(view.getBounds().width >= DEFAULT_CAPTURE_VIEWPORT.width);
        assert.ok(view.getBounds().height >= DEFAULT_CAPTURE_VIEWPORT.height);
    } finally {
        await service.destroy();
        fs.rmSync(root, { recursive: true, force: true });
    }
});

test('browser_control has an internal action deadline and releases a wedged queue', async () => {
    const { service } = fixture({ browserTotalTimeoutMs: 50 });
    const originalRun = service._runBrowserControl.bind(service);
    service._runBrowserControl = async () => new Promise(() => {});

    const started = Date.now();
    await assert.rejects(
        service.controlBrowser({ action: 'open' }, { interactionId: 'deadline-test' }),
        (error) => error?.code === 'BROWSER_CAPTURE_TIMEOUT' && /browser_control action "open"/u.test(error.message),
    );
    const elapsed = Date.now() - started;
    assert.ok(elapsed < 500, `internal deadline should beat the outer 61-second watchdog (elapsed ${elapsed} ms)`);
    assert.equal(service.view, null, 'timed-out native browser surface must be discarded');

    service._runBrowserControl = async () => ({ success: true, action: 'status' });
    const next = await service.controlBrowser({ action: 'status' }, { interactionId: 'deadline-test' });
    assert.deepEqual(next, { success: true, action: 'status' }, 'serialized browser queue must recover after the timed-out action');
    service._runBrowserControl = originalRun;
    await service.destroy();
});

test('showing the browser never enters or clears Chromium device-metrics emulation', async () => {
    const { service, view } = fixture();
    service._syncHiddenViewportBounds();
    service.setBounds({ x: 300, y: 80, width: 640, height: 480 });
    service.setVisible(true);
    await new Promise((resolve) => setImmediate(resolve));

    assert.deepEqual(view.getBounds(), { x: 300, y: 80, width: 640, height: 480 });
    assert.equal(view.webContents.debugger.commands.some((entry) => entry.name.startsWith('Emulation.')), false);
    await service.destroy();
});

test('empty native hidden capture falls back to DevTools capture instead of returning an empty screenshot', async () => {
    const { service, view } = fixture();
    const captured = await service._capturePng(view.webContents, service._captureViewport(), {});

    assert.equal(captured.mode, 'devtools');
    assert.equal(captured.png.toString(), 'synthetic-hidden-browser-frame');
    assert.equal(view.webContents.debugger.commands.some((entry) => entry.name.startsWith('Emulation.')), false);
    assert.equal(view.webContents.debugger.commands.some((entry) => entry.name === 'Page.captureScreenshot'), true);
    await service.destroy();
});

test('offline BrowserView code never re-enters Chromium device-metrics emulation', () => {
    const source = fs.readFileSync(path.join(__dirname, '..', '..', 'browser', 'offline-browser-service.js'), 'utf8');
    assert.doesNotMatch(source, /Emulation\.(?:setDeviceMetricsOverride|clearDeviceMetricsOverride)/u,
        'device-metrics override is a native browser-process crash path for the bundled Electron/Chromium runtime');
});

test('foreground detachment preserves a real hidden viewport and hidden capture without device emulation', async () => {
    const { service, view } = fixture();
    service.setBounds({ x: 280, y: 60, width: 720, height: 520 });
    service.setVisible(true);
    assert.equal(service.viewAttached, true);

    service.setOverlayBlocked(true);
    assert.equal(service.viewAttached, false, 'foreground renderer must still own native z-order');
    const hiddenBounds = view.getBounds();
    assert.ok(hiddenBounds.width >= 1 && hiddenBounds.height >= 1, 'detached browser must retain a real nonzero native viewport');

    const captured = await service._capturePng(view.webContents, service._captureViewport(), {});
    assert.equal(captured.mode, 'devtools');
    assert.equal(view.webContents.debugger.commands.some((entry) => entry.name.startsWith('Emulation.')), false);
    assert.equal(view.webContents.debugger.commands.some((entry) => entry.name === 'Page.captureScreenshot'), true);

    service.setOverlayBlocked(false);
    assert.equal(service.viewAttached, true, 'same live BrowserView must reattach after foreground ownership is released');
    assert.deepEqual(view.getBounds(), { x: 280, y: 60, width: 720, height: 520 });
    await service.destroy();
});
});

