// TEST MODULE: backend/Dev/tests/image-data-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/image-data-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const source = fs.readFileSync(path.resolve(__dirname, '..', '..', 'renderer', 'image-data.js'), 'utf8');
const imageSource = fs.readFileSync(path.resolve(__dirname, '..', '..', 'renderer', 'image.js'), 'utf8');

function utilities() {
    const context = {};
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(source, context, { filename: 'backend/renderer/image-data.js' });
    return context.Darkstar.imageData;
}

test('renderer image data accepts canonical image MIME/Base64 and normalizes whitespace', () => {
    const imageData = utilities();
    const normalized = imageData.normalizeSource({ base64: 'aG Vs\nbG8=', mimeType: 'IMAGE/PNG' });
    assert.equal(normalized.base64, 'aGVsbG8=');
    assert.equal(normalized.mimeType, 'image/png');
    assert.equal(normalized.dataUrl, 'data:image/png;base64,aGVsbG8=');
});

test('renderer image data rejects attribute/markup injection and non-base64 data URLs', () => {
    const imageData = utilities();
    assert.equal(imageData.safeDataUrl({ base64: 'abc"><style>body{display:none}</style>', mimeType: 'image/png' }), '');
    assert.equal(imageData.safeDataUrl({ dataUrl: 'data:image/svg+xml,<svg></svg>' }), '');
    assert.equal(imageData.safeDataUrl({ dataUrl: 'data:text/html;base64,PGgxPkJvb208L2gxPg==' }), '');
    assert.equal(imageData.safeDataUrl({ base64: 'A', mimeType: 'image/png' }), '', 'invalid Base64 lengths are rejected');
});

test('renderer image data can recover canonical image bytes from a validated data URL', () => {
    const imageData = utilities();
    const normalized = imageData.normalizeSource({ dataUrl: 'data:image/jpeg;base64,aGVsbG8=' });
    assert.equal(normalized.base64, 'aGVsbG8=');
    assert.equal(normalized.mimeType, 'image/jpeg');
});


test('initial composer image preview uses the same validated canonical image-data boundary', () => {
    const preview = { src: '' };
    const name = { textContent: '' };
    const size = { textContent: '' };
    const container = { classList: { add() {} } };
    const context = {
        document: {
            getElementById(id) {
                return { imagePreview: preview, imageName: name, imageSize: size, imagePreviewContainer: container }[id] || null;
            },
        },
        formatFileSize() { return '5 B'; },
        pendingImage: null,
    };
    context.globalThis = context;
    context.window = context;
    vm.createContext(context);
    vm.runInContext(source, context, { filename: 'backend/renderer/image-data.js' });
    vm.runInContext(imageSource, context, { filename: 'backend/renderer/image.js' });

    const file = { name: 'safe.png', type: 'image/png', size: 5 };
    assert.equal(context.showPendingImage(file, 'data:image/png;base64,aGVsbG8=', '', ''), true);
    assert.equal(preview.src, 'data:image/png;base64,aGVsbG8=');
    assert.equal(context.pendingImage.base64, 'aGVsbG8=');
    assert.equal(context.showPendingImage(file, 'data:image/png;base64,abc"><style>x</style>', '', ''), false);
    assert.equal(preview.src, 'data:image/png;base64,aGVsbG8=', 'rejected data must not replace the existing preview');
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/large-text-transfer-contract-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/large-text-transfer-contract-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const test = require('node:test');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const PROVIDER = path.join(ROOT, 'agent_assets', 'tools', 'replace_file.py');
const RUNNER = path.join(ROOT, 'backend', 'agent', 'python-tool-runner.py');
const { PythonToolHost, inspectPythonProvider } = require('../../agent/python-tool-host');
const {
    REPLACE_FILE_INLINE_TRANSFER_CHARS,
    TRANSFER_DIRECTORY_PREFIX,
    executeToolHandler,
} = require('../../agent/tool-runtime');

async function createReplaceHarness(t) {
    const inspection = await inspectPythonProvider(PROVIDER, {
        runnerPath: RUNNER,
        cwd: path.dirname(PROVIDER),
    });
    const definition = inspection.description.tools.find((entry) => entry?.function?.name === 'replace_file');
    assert.ok(definition, 'replace_file provider must describe the replace_file tool');

    const workspace = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-replace-contract-'));
    const host = new PythonToolHost({
        executable: inspection.executable,
        scriptPath: PROVIDER,
        runnerPath: RUNNER,
        cwd: path.dirname(PROVIDER),
    });
    await host.start();
    t.after(async () => {
        await host.shutdown().catch(() => undefined);
        fs.rmSync(workspace, { recursive: true, force: true });
    });
    return { handler: { definition, host }, workspace };
}

test('large replace_file payloads use the canonical Darkstar file-backed transfer contract end to end', async (t) => {
    const { handler, workspace } = await createReplaceHarness(t);
    const content = `header\n${'x'.repeat(REPLACE_FILE_INLINE_TRANSFER_CHARS + 1)}\nfooter`;

    const rawResult = await executeToolHandler(
        handler,
        'replace_file',
        { path: 'large.txt', new_content: content, mode: 'replace' },
        { workspace },
    );
    const result = JSON.parse(rawResult);

    assert.equal(result.success, true);
    assert.equal(result.transport, 'file-backed');
    assert.equal(fs.readFileSync(path.join(workspace, 'large.txt'), 'utf8'), content);
});

test('large-text transfer prefix and provider contract stay aligned', () => {
    assert.equal(TRANSFER_DIRECTORY_PREFIX, 'darkstar-replace-');
    const source = fs.readFileSync(PROVIDER, 'utf8');
    assert.match(source, /__darkstar_content_file/u);
    assert.match(source, /__darkstar_content_sha256/u);
    assert.match(source, /darkstar-replace-/u);
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/light-theme-node-readout-contrast-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/light-theme-node-readout-contrast-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const styles = fs.readFileSync(path.join(ROOT, 'backend', 'shell', 'styles.css'), 'utf8');
const nodeEditorStyles = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'node-editor.css'), 'utf8');
const renderers = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'nodes', 'control-renderers.js'), 'utf8');
const editorControls = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'nodes', 'editor', 'controls.js'), 'utf8');

function themeBodies(themeId) {
    const escaped = themeId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`html\\[data-theme='${escaped}'\\]\\s*\\{([\\s\\S]*?)\\n\\}`, 'gm');
    return [...styles.matchAll(regex)].map((match) => match[1]);
}

function finalThemeToken(themeId, token) {
    const bodies = themeBodies(themeId);
    assert.ok(bodies.length > 0, `${themeId} theme must exist`);
    let value = '';
    for (const body of bodies) {
        const match = body.match(new RegExp(`${token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*:\\s*([^;]+);`, 'i'));
        if (match) value = match[1].trim();
    }
    assert.ok(value, `${themeId} must define ${token}`);
    return value;
}

function hexRgb(hex) {
    const raw = hex.replace('#', '');
    assert.match(raw, /^[0-9a-f]{6}$/i, `expected six-digit hex color, got ${hex}`);
    return [0, 2, 4].map((offset) => parseInt(raw.slice(offset, offset + 2), 16) / 255);
}

function luminance(hex) {
    const rgb = hexRgb(hex).map((channel) => channel <= 0.04045
        ? channel / 12.92
        : Math.pow((channel + 0.055) / 1.055, 2.4));
    return (0.2126 * rgb[0]) + (0.7152 * rgb[1]) + (0.0722 * rgb[2]);
}

function contrastRatio(a, b) {
    const first = luminance(a);
    const second = luminance(b);
    return (Math.max(first, second) + 0.05) / (Math.min(first, second) + 0.05);
}

test('light theme gives node parameter readouts an explicit semantic dark text color', () => {
    assert.match(styles,
        /html\[data-theme='light'\]\s+\.node-param-value\s*\{\s*color:\s*var\(--theme-text-soft,\s*rgba\(0,\s*0,\s*0,\s*0\.64\)\);\s*\}/m,
        'light theme must explicitly override the dark-default .node-param-value color');

    const lightReadoutRules = [...styles.matchAll(/html\[data-theme='light'\][^{]*\.node-param-value[^{}]*\{([^}]*)\}/g)];
    assert.ok(lightReadoutRules.length > 0, 'expected at least one light-theme node readout rule');
    for (const match of lightReadoutRules) {
        assert.doesNotMatch(match[1], /color\s*:\s*(?:rgba?\(\s*255\s*,\s*255\s*,\s*255|#fff(?:fff)?\b|transparent)/i,
            'light-theme node parameter values must never regress to white/transparent text');
    }
});

test('light-theme node readout token maintains readable contrast across the node panel gradient', () => {
    const foreground = finalThemeToken('light', '--theme-text-soft');
    assert.match(foreground, /^#[0-9a-f]{6}$/i, '--theme-text-soft must remain a concrete auditable light-theme color');

    const panel = finalThemeToken('light', '--theme-panel');
    const panelColors = [...panel.matchAll(/#[0-9a-f]{6}\b/gi)].map((match) => match[0]);
    assert.ok(panelColors.length >= 2, 'light node panel gradient must expose auditable endpoint colors');

    for (const background of panelColors) {
        const ratio = contrastRatio(foreground, background);
        assert.ok(ratio >= 4.5,
            `light node readout contrast must remain >= 4.5:1; ${foreground} on ${background} was ${ratio.toFixed(2)}:1`);
    }
});

test('light-theme label foreground and status background declarations remain separated', () => {
    assert.match(styles,
        /html\[data-theme='light'\]\s+\.socket-label,\s*\nhtml\[data-theme='light'\]\s+\.node-param-label,\s*\nhtml\[data-theme='light'\]\s+\.node-status-text\s*\{\s*color:/m,
        'light node labels must explicitly own a foreground color');
    assert.match(styles,
        /html\[data-theme='light'\]\s+\.node-status\s*\{\s*background:/m,
        'node status container must own the light background separately');
    assert.doesNotMatch(styles,
        /html\[data-theme='light'\]\s+\.socket-label,[\s\S]{0,220}\.node-status\s*\{\s*background:/m,
        'label selectors must never be accidentally grouped into the node-status background rule again');
});

test('sampler sliders continue rendering and updating the guarded node-param-value readout', () => {
    assert.match(renderers,
        /class="node-param-value"[^>]*>['"]?\s*\+\s*escapeHtml\(displayValue\)/,
        'slider renderer must keep its visible numeric readout in .node-param-value');
    assert.match(editorControls,
        /querySelector\('\.node-param-value'\)/,
        'slider updates must continue resolving the existing .node-param-value span');
    assert.match(editorControls,
        /valueSpan\.textContent\s*=/,
        'slider updates must modify text only and must not inject an inline color');
    assert.doesNotMatch(editorControls, /valueSpan\.style\.(?:color|opacity)|setAttribute\(['"]style['"]/,
        'runtime slider updates must not bypass theme contrast with inline styling');
});

test('node-editor supplemental stylesheet cannot override the light readout back to a dark-theme literal', () => {
    const rules = [...nodeEditorStyles.matchAll(/([^{}]*\.node-param-value[^{}]*)\{([^}]*)\}/g)];
    for (const [, selector, body] of rules) {
        assert.doesNotMatch(body, /color\s*:\s*(?:rgba?\(\s*255\s*,\s*255\s*,\s*255|#fff(?:fff)?\b|transparent)/i,
            `supplemental node stylesheet must not hide readouts in light mode: ${selector.trim()}`);
    }
});
});

