// TEST MODULE: backend/Dev/tests/live-context-usage-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/live-context-usage-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const {
    acquireSlotLease,
    exactSlotContextUsage,
    startSlotMonitor,
} = require('../../runtime/native-context-usage');
const { performChatCompletion } = require('../../runtime/chat-completion');
const ROOT = path.resolve(__dirname, '..', '..', '..');

function jsonResponse(payload, status = 200) {
    return {
        ok: status >= 200 && status < 300,
        status,
        async json() { return structuredClone(payload); },
        async text() { return JSON.stringify(payload); },
    };
}

function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

test('slot usage is exactly llama.cpp n_prompt_tokens with no inferred shift arithmetic', () => {
    const usage = exactSlotContextUsage({
        id: 3,
        id_task: 91,
        n_ctx: 60000,
        n_prompt_tokens: 37467,
        is_processing: true,
    });
    assert.deepEqual(usage, {
        activeContextTokens: 37467,
        totalTokens: 37467,
        contextSize: 60000,
        contextSizeSource: 'llama.cpp-slots',
        slotId: 3,
        slotTaskId: 91,
        slotProcessing: true,
        exact: true,
        available: true,
        current: true,
        source: 'llama.cpp-slots',
    });
});

test('slot monitor publishes factual rises and native-shift drops exactly as /slots reports them', async () => {
    const samples = [21955, 21961, 21974, 15003, 15012, 15012];
    let index = 0;
    const emitted = [];
    const monitor = startSlotMonitor({
        host: '127.0.0.1', port: 8080, model: 'm', slotId: 0, pollIntervalMs: 4,
        fetchImpl: async () => jsonResponse([{
            id: 0,
            id_task: 7,
            n_ctx: 60000,
            n_prompt_tokens: samples[Math.min(index++, samples.length - 1)],
            is_processing: true,
        }]),
        onUsage(usage) { emitted.push(usage.activeContextTokens); },
    });
    for (let attempt = 0; attempt < 100 && !emitted.includes(15003); attempt += 1) await sleep(4);
    await monitor.stop();
    assert.ok(emitted.includes(21955));
    assert.ok(emitted.includes(21974));
    assert.ok(emitted.includes(15003), 'a real llama.cpp context shift must appear as the exact reported drop');
    assert.equal(emitted.every((value) => samples.includes(value)), true, 'monitor must never synthesize an intermediate token count');
});

test('slot lease selects an exact idle slot and prevents local Darkstar requests from claiming it twice', async () => {
    const fetchImpl = async () => jsonResponse([
        { id: 0, is_processing: false, n_prompt_tokens: 100, n_ctx: 60000 },
        { id: 1, is_processing: false, n_prompt_tokens: 200, n_ctx: 60000 },
    ]);
    const first = await acquireSlotLease({ fetchImpl, host: '127.0.0.1', port: 8081, model: 'm', pollIntervalMs: 2 });
    const second = await acquireSlotLease({ fetchImpl, host: '127.0.0.1', port: 8081, model: 'm', pollIntervalMs: 2 });
    try {
        assert.equal(first.slotId, 0);
        assert.equal(second.slotId, 1);
    } finally {
        first.release();
        second.release();
    }
});

test('chat completion pins the request to the leased slot and updates context while generation is active', async () => {
    let slotCall = 0;
    let postedBody = null;
    const usageEvents = [];
    const slotStates = [
        { id: 0, id_task: null, n_ctx: 60000, n_prompt_tokens: 21955, is_processing: false },
        { id: 0, id_task: 44, n_ctx: 60000, n_prompt_tokens: 21955, is_processing: true },
        { id: 0, id_task: 44, n_ctx: 60000, n_prompt_tokens: 21964, is_processing: true },
        { id: 0, id_task: 44, n_ctx: 60000, n_prompt_tokens: 21978, is_processing: true },
        { id: 0, id_task: 44, n_ctx: 60000, n_prompt_tokens: 16004, is_processing: true },
        { id: 0, id_task: 44, n_ctx: 60000, n_prompt_tokens: 16010, is_processing: false },
    ];
    const fetchImpl = async (url, options = {}) => {
        if (String(url).includes('/slots')) {
            const state = slotStates[Math.min(slotCall++, slotStates.length - 1)];
            return jsonResponse([state]);
        }
        if (String(url).includes('/input_tokens')) return jsonResponse({ input_tokens: 21955 });
        if (String(url).includes('/v1/chat/completions')) {
            postedBody = JSON.parse(options.body);
            return { ok: true, status: 200 };
        }
        throw new Error(`unexpected URL ${url}`);
    };

    const result = await performChatCompletion({
        body: { model: 'm', messages: [{ role: 'user', content: 'hello' }] },
        fetchImpl,
        host: '127.0.0.1',
        port: 8082,
        signal: new AbortController().signal,
        handlers: { onContextUsage(usage) { usageEvents.push(structuredClone(usage)); } },
        async consumeChatCompletionStream() {
            await sleep(1050);
            return { text: 'done', reasoning: '', toolCalls: [], finishReason: 'stop', contextUsage: null };
        },
    });

    assert.equal(postedBody.id_slot, 0);
    assert.equal(postedBody.verbose, true);
    const live = usageEvents.filter((usage) => usage.source === 'llama.cpp-slots').map((usage) => usage.activeContextTokens);
    assert.ok(live.includes(21964), 'live counter must advance during the active generation');
    assert.ok(live.includes(16004), 'live counter must report actual native-shift drops');
    assert.equal(result.contextUsage.source, 'llama.cpp-slots');
    assert.equal(result.contextUsage.activeContextTokens, 16010);
});

test('when /slots telemetry is unavailable Darkstar marks live context unavailable instead of freezing a stale prompt count', async () => {
    const usageEvents = [];
    const fetchImpl = async (url) => {
        if (String(url).includes('/slots')) return jsonResponse({ error: 'not supported' }, 404);
        if (String(url).includes('/input_tokens')) return jsonResponse({ input_tokens: 21955 });
        if (String(url).includes('/v1/chat/completions')) return { ok: true, status: 200 };
        throw new Error(`unexpected URL ${url}`);
    };
    await performChatCompletion({
        body: { model: 'm', messages: [{ role: 'user', content: 'hello' }] },
        fetchImpl,
        host: '127.0.0.1', port: 8083,
        signal: new AbortController().signal,
        handlers: { onContextUsage(usage) { usageEvents.push(structuredClone(usage)); } },
        async consumeChatCompletionStream() {
            return { text: 'done', reasoning: '', toolCalls: [], finishReason: 'stop', contextUsage: null };
        },
    });
    assert.ok(usageEvents.some((usage) => usage.source === 'input_tokens' && usage.totalTokens === 21955));
    assert.ok(usageEvents.some((usage) => usage.source === 'llama.cpp-slots-unavailable' && usage.available === false));
});


test('existing parallel-slot ownership is preserved exactly and telemetry does not reassign it', async () => {
    let postedBody = null;
    let slotReads = 0;
    const fetchImpl = async (url, options = {}) => {
        if (String(url).includes('/slots')) {
            slotReads += 1;
            return jsonResponse([
                { id: 0, n_ctx: 60000, n_prompt_tokens: 100, is_processing: false },
                { id: 1, id_task: 55, n_ctx: 60000, n_prompt_tokens: 22000, is_processing: true },
            ]);
        }
        if (String(url).includes('/input_tokens')) return jsonResponse({ input_tokens: 22000 });
        if (String(url).includes('/v1/chat/completions')) {
            postedBody = JSON.parse(options.body);
            return { ok: true, status: 200 };
        }
        throw new Error(`unexpected URL ${url}`);
    };
    await performChatCompletion({
        body: { model: 'm', id_slot: 1, messages: [{ role: 'user', content: 'hello' }] },
        fetchImpl, host: '127.0.0.1', port: 8084,
        signal: new AbortController().signal,
        handlers: { onContextUsage() {} },
        async consumeChatCompletionStream() {
            await sleep(10);
            return { text: 'done', reasoning: '', toolCalls: [], finishReason: 'stop', contextUsage: null };
        },
    });
    assert.equal(postedBody.id_slot, 1, 'the parallel-stream reservation is authoritative');
    assert.ok(slotReads >= 1, 'the assigned slot is monitored without selecting a replacement slot');
});


test('live slot usage retains the exact runtime context limit when /slots omits n_ctx', () => {
    const usage = exactSlotContextUsage({
        id: 0,
        id_task: 7,
        n_prompt_tokens: 15317,
        is_processing: true,
    }, {
        contextSize: 17000,
        contextSizeSource: 'props-manual',
    });
    assert.equal(usage.activeContextTokens, 15317);
    assert.equal(usage.contextSize, 17000);
    assert.equal(usage.contextSizeSource, 'props-manual');
    assert.equal(usage.exact, true);
    assert.equal(usage.current, true);
});

test('chat completion supplies the authoritative runtime context limit to live slot telemetry when slot payloads omit n_ctx', async () => {
    const usageEvents = [];
    let slotRead = 0;
    const fetchImpl = async (url, options = {}) => {
        if (String(url).includes('/slots')) {
            slotRead += 1;
            return jsonResponse([{ id: 0, id_task: slotRead > 1 ? 9 : null, n_prompt_tokens: slotRead > 1 ? 15340 : 12000, is_processing: slotRead > 1 }]);
        }
        if (String(url).includes('/input_tokens')) return jsonResponse({ input_tokens: 12000 });
        if (String(url).includes('/v1/chat/completions')) return { ok: true, status: 200 };
        throw new Error(`unexpected URL ${url}`);
    };
    await performChatCompletion({
        body: { model: 'm', messages: [{ role: 'user', content: 'hello' }] },
        contextSize: 17000,
        contextSizeSource: 'props',
        fetchImpl, host: '127.0.0.1', port: 8085,
        signal: new AbortController().signal,
        handlers: { onContextUsage(usage) { usageEvents.push(structuredClone(usage)); } },
        async consumeChatCompletionStream() {
            await sleep(20);
            return { text: 'done', reasoning: '', toolCalls: [], finishReason: 'stop', contextUsage: null };
        },
    });
    const live = usageEvents.find((usage) => usage.source === 'llama.cpp-slots' && usage.activeContextTokens >= 15300);
    assert.ok(live, 'the live sample must remain usable for the 90% threshold even when /slots omits n_ctx');
    assert.equal(live.contextSize, 17000);
    assert.equal(live.contextSizeSource, 'props');
});


test('LlamaRuntime propagates its measured per-slot context limit into every monitored completion', () => {
    const source = fs.readFileSync(path.join(ROOT, 'backend', 'llama-runtime.js'), 'utf8');
    const method = source.slice(source.indexOf('performChatCompletion(body, signal, handlers = {})'), source.indexOf('async tokenizeText', source.indexOf('performChatCompletion(body, signal, handlers = {})')));
    assert.match(method, /contextSizePerSlot: contextSize[\s\S]*contextMeasurementSource: contextSizeSource[\s\S]*this\.getStatus\(\)/u);
    assert.match(method, /body, contextSize, contextSizeSource/u);
});
});

