// TEST MODULE: backend/Dev/tests/message-action-geometry-hover-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/message-action-geometry-hover-regression.test.js", function(module, exports, require, __filename, __dirname) {
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const read = rel => fs.readFileSync(path.join(ROOT, rel), 'utf8');

test('message avatar is centered only against bubble row, never the action gutter', () => {
    const chat = read('backend/renderer/chat.js');
    const css = read('backend/shell/styles.css');

    assert.match(chat,
        /<div class="message-avatar">' \+ avatarContent \+ '<\/div>' \+\s*'<div class="message-stack"><div class="message-content">' \+ messageBody \+ '<\/div><\/div>' \+ actionsHtml/u,
        'action gutter must be a direct message child outside message-stack');
    assert.doesNotMatch(chat,
        /<div class="message-stack">[\s\S]*?actionsHtml \+ '<\/div>'/u,
        'message-stack must contain message content only');

    assert.match(css, /\.message \{[\s\S]*?display: grid;[\s\S]*?grid-template-rows: auto auto;/u);
    assert.match(css, /\.message-stack \{[\s\S]*?grid-row: 1;/u,
        'message bubble must occupy grid row 1');
    assert.match(css, /\.message\.user \.message-avatar,\s*\n\.message\.assistant \.message-avatar \{[\s\S]*?grid-row: 1;[\s\S]*?align-self: center;/u,
        'chevron/avatar must be centered only in bubble row 1');
    assert.match(css, /\.message-actions \{[\s\S]*?grid-row: 2;/u,
        'actions must occupy an independent row 2');
});

test('message bubble is the primary reveal target and controls remain stable outside it', () => {
    const css = read('backend/shell/styles.css');
    const actions = css.match(/\.message-actions \{([\s\S]*?)\n\}/u);
    assert.ok(actions, 'message action rule must exist');
    assert.match(actions[1], /align-items: center;/u);
    assert.match(actions[1], /width: max-content;/u,
        'invisible action hover target must not span the whole message');
    assert.match(actions[1], /height: 30px;/u);
    assert.match(actions[1], /min-height: 30px;/u);
    assert.match(actions[1], /overflow: visible;/u);
    assert.match(actions[1], /opacity: 0;/u,
        'idle actions must be visually absent by default');
    assert.match(actions[1], /visibility: visible;/u,
        'idle invisible actions must remain hoverable');
    assert.match(actions[1], /pointer-events: auto;/u);
    assert.match(actions[1], /transition: opacity 0\.15s ease, transform 0\.15s ease;/u);

    assert.match(css, /\.message-stack:hover \+ \.message-actions,\s*\n\.message-stack:focus-within \+ \.message-actions,\s*\n\.message-actions:hover,\s*\n\.message-actions:focus-within \{[\s\S]*?opacity: 1;/u,
        'hovering/focusing the main message bubble must reveal its controls');
    assert.doesNotMatch(css, /\.message:hover \.message-actions/u,
        'the entire message row must not become an oversized hover target');
    assert.match(css, /\.message-stack::after \{[\s\S]*?bottom: -8px;[\s\S]*?height: 9px;/u,
        'bubble must provide a narrow hover bridge into the external action row');

    assert.match(css, /\.message-actions-user \{ justify-content: flex-end; justify-self: end; \}/u);
    assert.match(css, /\.message-actions-assistant \{ justify-content: flex-start; justify-self: start; \}/u);

    const button = css.match(/\.btn-action \{([\s\S]*?)\n\}/u);
    assert.ok(button, 'button geometry rule must exist');
    assert.match(button[1], /box-sizing: border-box;/u);
    assert.match(button[1], /align-items: center;/u);
    assert.match(button[1], /justify-content: center;/u);
    assert.match(button[1], /width: 28px;/u);
    assert.match(button[1], /height: 28px;/u);
    assert.match(button[1], /min-width: 28px;/u);
    assert.match(button[1], /min-height: 28px;/u);
    assert.match(button[1], /padding: 0;/u);
    assert.match(button[1], /line-height: 1;/u,
        'icon controls must not inherit text line-height that can clip below the gutter');
    assert.match(button[1], /border-radius: 8px;/u);
    assert.match(button[1], /border: 1px solid transparent;/u);
    assert.match(button[1], /-webkit-user-select: none;/u);
    assert.match(button[1], /user-select: none;/u,
        'message action controls must never become part of copied/selected chat text');
    assert.match(css, /\.btn-action svg \{ width: 16px; height: 16px;/u,
        'vector action glyphs must share the enlarged compact optical size');
});

test('generation hides only assistant-like actions; user Edit/Retry remains hoverable while the model is loading', () => {
    const css = read('backend/shell/styles.css');
    const hidden = css.match(/\.message\.assistant\.generating \.message-actions,\s*\n\.message\.adversary\.generating \.message-actions \{([\s\S]*?)\n\}/u);
    assert.ok(hidden);
    assert.match(hidden[1], /visibility: hidden;/u);
    assert.match(hidden[1], /opacity: 0;/u);
    assert.match(hidden[1], /pointer-events: none;/u);
    assert.doesNotMatch(hidden[1], /display:\s*none/u,
        'reserved action row must survive generation');
    assert.doesNotMatch(css, /\.message\.generating \.message-actions/u,
        'a generic generating selector must never suppress a user message action row');
    assert.match(css, /\.message-stack:hover \+ \.message-actions,[\s\S]*?opacity: 1;/u,
        'hovering the user text must reveal Edit/Retry even while another message is generating');
    assert.doesNotMatch(css, /\.message-actions\.message-actions-suppressed[\s,]*\{/u,
        'global generation suppression must not hide finished user Edit/Retry actions');
});
});

