test('every rendered chat message role gets the same minus delete action below the message', () => {
    const context = actionContext();
    context.getActiveTab = () => ({ history: [] });
    context.assistantMessageCanContinue = () => false;
    for (const role of ['user', 'assistant', 'adversary', 'system', 'compact', 'custom']) {
        const html = context.messageActionsHtml(role, 3, 'message-3');
        assert.match(html, /data-ui-action="delete-message"/u, `${role} is missing delete`);
        assert.match(html, /data-message-id="message-3"/u);
        assert.match(html, /aria-label="Delete message"/u);
        assert.match(html, /<svg[\s\S]*?<path d="M7 12h10"\/><\/svg>/u);
        assert.doesNotMatch(html, /[↻−]/u, 'message action icons must not expose selectable text glyphs');
    }
    assert.match(context.messageActionsHtml('user', 3, 'message-3'), /data-ui-action="edit-message"/u);
    assert.match(context.messageActionsHtml('assistant', 3, 'message-3'), /data-ui-action="copy-message"/u);
    assert.doesNotMatch(context.messageActionsHtml('system', 3, 'message-3'), /edit-message|copy-message|retry-message/u);
    assert.doesNotMatch(context.messageActionsHtml('compact', 3, 'message-3'), /edit-message|copy-message|retry-message/u);
});

test('message deletion resolves by stable id, removes canonical history, cancels stale generation state, rebuilds context snapshots, and persists immediately', async () => {
    const context = actionContext();
    const system = { id: 'sys', role: 'system', content: 'system' };
    const compact = { id: 'compact', role: 'system', content: 'summary', compactedContext: true };
    const adversary = { id: 'adv', role: 'user', content: 'critique', adversary: true };
    const assistant = {
        id: 'assistant', role: 'assistant', content: 'done',
        toolContext: [
            { role: 'assistant', tool_calls: [{ id: 'call-1', type: 'function', function: { name: 'Write', arguments: '{"path":"x"}' } }] },
            { role: 'tool', tool_call_id: 'call-1', name: 'Write', content: 'ok' },
        ],
    };
    const user = { id: 'user', role: 'user', content: 'latest' };
    const tab = {
        id: 7,
        history: [system, compact, adversary, assistant, user],
        tokens: 21955,
        tokensExact: true,
        tokensPerSecond: 25,
        generationQueued: true,
    };
    context.tabs = [tab];
    context.getActiveTab = () => tab;
    context.nodeEditorState = {
        nodes: [
            { type: 'context', history: tab.history.slice() },
            { type: 'contextManager', history: tab.history.slice() },
            { type: 'sampler' },
        ],
    };
    const session = { id: 1, tabId: 7, cancelled: false, donePromise: Promise.resolve() };
    let activeSession = session;
    context.generationSessionForTab = () => activeSession;
    context.cancelGenerationSession = (actual, reason, options) => {
        actual.cancelled = true;
        context.calls.push(['cancel', actual, reason, options]);
        return true;
    };
    // message-deletion.js deliberately delegates the race-sensitive ownership
    // handoff to state.js. Model that owner contract here instead of bypassing
    // it with the obsolete direct-cancel behavior this regression used to test.
    context.retireGenerationBeforeConversationMutation = async (actualTab, reason, options) => {
        context.calls.push(['retire', actualTab, reason, options]);
        if (activeSession && activeSession.cancelled !== true) {
            context.cancelGenerationSession(activeSession, reason, { clearUi: true, updateButtons: false });
        }
        if (activeSession && activeSession.donePromise) await activeSession.donePromise;
        activeSession = null;
        return session;
    };
    context.editModalIsActive = () => false;
    context.generationLaunchQueue = [
        { id: 'new-generation', tabId: 7, regenerateFromIndex: -1, queuedUserMessageId: 'other-user' },
        { id: 'stale-retry', tabId: 7, regenerateFromIndex: 4, queuedUserMessageId: '' },
        { id: 'other-tab', tabId: 8, regenerateFromIndex: 2, queuedUserMessageId: '' },
    ];
    context.generationLaunchQueueStore = () => context.generationLaunchQueue;
    context.queuedGenerationForTab = (tabId) => context.generationLaunchQueue.some((entry) => Number(entry.tabId) === Number(tabId));
    for (const name of ['renderChat', 'renderQueue', 'renderTabs', 'updateTokenCounter', 'updateButtonStates']) {
        context[name] = () => { context.calls.push([name]); };
    }
    context.activeTabOwnsGeneration = () => false;
    context.scheduleChatSessionSave = (delay) => { context.calls.push(['scheduleSave', delay]); };
    context.saveChatSessionNow = async (options) => { context.calls.push(['saveNow', options]); return true; };

    assert.equal(context.deleteChatMessage(0, 'compact'), true, 'stable id must win over stale index');
    await new Promise((resolve) => setImmediate(resolve));

    assert.deepEqual(tab.history.map((message) => message.id), ['sys', 'adv', 'assistant', 'user']);
    assert.equal(tab.tokens, 0);
    assert.equal(tab.tokensExact, false);
    assert.equal(tab.tokensPerSecond, 0);
    const retireCall = context.calls.find((call) => call[0] === 'retire');
    assert.ok(retireCall, 'deletion must join the generation owner before mutating history');
    assert.equal(retireCall[1], tab);
    assert.equal(retireCall[2], 'message-deleted');
    assert.equal(retireCall[3] && retireCall[3].discardQueued, false);
    assert.equal(context.calls.filter((call) => call[0] === 'cancel').length, 1);
    assert.equal(context.calls.find((call) => call[0] === 'cancel')[2], 'message-deleted');
    assert.deepEqual(context.generationLaunchQueue.map((entry) => entry.id), ['new-generation', 'other-tab'], 'stale retry is cancelled but unrelated queued work survives');
    assert.deepEqual(context.nodeEditorState.nodes[0].history.map((message) => message.id), ['sys', 'adv', 'assistant', 'user']);
    assert.deepEqual(context.nodeEditorState.nodes[1].history.map((message) => message.id), ['sys', 'adv', 'assistant', 'user']);
    assert.ok(context.calls.some((call) => call[0] === 'renderChat'));
    assert.ok(context.calls.some((call) => call[0] === 'updateTokenCounter'));
    assert.ok(context.calls.some((call) => call[0] === 'scheduleSave' && call[1] === 0));
    assert.ok(context.calls.some((call) => call[0] === 'saveNow' && call[1].force === true));
});

test('deleting an assistant message removes its complete tool transaction with the canonical record', () => {
    const context = actionContext();
    const tab = {
        id: 7,
        history: [
            { id: 'u1', role: 'user', content: 'write it' },
            {
                id: 'a1', role: 'assistant', content: 'done',
                toolContext: [
                    { role: 'assistant', tool_calls: [{ id: 'c1', type: 'function', function: { name: 'Write', arguments: '{}' } }] },
                    { role: 'tool', tool_call_id: 'c1', content: 'ok' },
                ],
            },
            { id: 'u2', role: 'user', content: 'next' },
        ],
        tokens: 10,
        tokensExact: true,
        tokensPerSecond: 0,
    };
    context.getActiveTab = () => tab;
    context.generationSessionForTab = () => null;
    context.generationLaunchQueueStore = () => [];
    context.queuedGenerationForTab = () => false;
    context.renderChat = () => undefined;
    context.renderQueue = () => undefined;
    context.renderTabs = () => undefined;
    context.updateTokenCounter = () => undefined;
    context.updateButtonStates = () => undefined;
    context.activeTabOwnsGeneration = () => false;

    const removed = tab.history[1];
    assert.equal(context.deleteChatMessage(1, 'a1'), true);
    assert.deepEqual(tab.history.map((message) => message.id), ['u1', 'u2']);
    assert.equal(tab.history.includes(removed), false);
    assert.equal(removed.toolContext.length, 2, 'the removed record owned the entire tool protocol; no orphan tool messages remain in history');
});

