// TEST MODULE: backend/Dev/tests/monolith-sandboxed-preload-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/monolith-sandboxed-preload-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const ROOT = path.resolve(__dirname, '..', '..', '..');

test('structured monolith boots the Electron sandboxed preload without unrestricted Node requires', () => {
    const source = fs.readFileSync(path.join(ROOT, 'backend', 'Darkstar_Core.js'), 'utf8');
    const required = [];
    let exposed = null;

    function restrictedRequire(id) {
        required.push(id);
        if (id !== 'electron') throw new Error(`sandbox require denied: ${id}`);
        return {
            contextBridge: {
                exposeInMainWorld(name, value) { exposed = { name, value }; },
            },
            ipcRenderer: {
                invoke() { return Promise.resolve({}); },
                on() {},
                removeListener() {},
                sendSync() { return {}; },
            },
            webUtils: { getPathForFile() { return ''; } },
        };
    }
    restrictedRequire.resolve = (id) => id;
    restrictedRequire.cache = {};
    restrictedRequire.main = {};

    // Match Electron's real sandbox contract: restricted require/process are
    // guaranteed, but Node's CommonJS wrapper globals are not. If the monolith
    // touches module/__dirname/__filename here, the actual preload can die before
    // contextBridge exposes workspace/chat/model IPC.
    const context = {
        console,
        require: restrictedRequire,
        process: { type: 'renderer', platform: 'win32', argv: [] },
        Map,
        Set,
        Object,
        Array,
        String,
        Number,
        Boolean,
        RegExp,
        Date,
        Promise,
        Error,
        TypeError,
        JSON,
        Math,
        URL,
    };
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(source, context, { filename: 'Darkstar_Core.js' });

    assert.deepEqual(required, ['electron'], 'sandboxed preload must not require node:path or other unrestricted Node modules');
    assert.equal(exposed?.name, 'darkstar');
    assert.equal(typeof exposed?.value?.workspace?.chooseFolder, 'function', 'workspace bridge must be installed');
    assert.equal(typeof exposed?.value?.chatSession?.load, 'function', 'persisted chat/workspace state must remain loadable');
    assert.equal(typeof exposed?.value?.nodes?.startChat, 'function', 'model bridge must remain installed');
});
});

