test('zoom anchor math preserves the graph point under the mouse exactly', () => {
    const state = { panX: 120, panY: -35, zoom: 1.25 };
    const canvas = { getBoundingClientRect: () => ({ left: 40, top: 25 }) };
    const sandbox = {
        nodeEditorState: state,
        document: {
            addEventListener() {},
            getElementById(id) { return id === 'gridCanvas' ? canvas : null; },
        },
        renderConnections() {},
    };
    sandbox.globalThis = sandbox;
    vm.runInNewContext(read('backend/renderer/nodes/editor/interactions.js'), vm.createContext(sandbox), { filename: 'backend/renderer/nodes/editor/interactions.js' });

    const mouse = { x: 690, y: 430 };
    const graphBefore = {
        x: (mouse.x - 40 - state.panX) / state.zoom,
        y: (mouse.y - 25 - state.panY) / state.zoom,
    };
    assert.equal(sandbox.zoomNodeEditorAtScreenPoint(mouse.x, mouse.y, 1.75), true);
    const graphAfter = {
        x: (mouse.x - 40 - state.panX) / state.zoom,
        y: (mouse.y - 25 - state.panY) / state.zoom,
    };
    assert.ok(Math.abs(graphBefore.x - graphAfter.x) < 1e-9);
    assert.ok(Math.abs(graphBefore.y - graphAfter.y) < 1e-9);
    assert.equal(state.zoom, 1.75);
});

test('tab bar tracks its own launch-time width changes instead of waiting for a window resize', () => {
    const callbacks = [];
    const frames = [];
    const timers = [];
    const tabBar = {
        clientWidth: 1000,
        dataset: {},
        getBoundingClientRect() { return { width: this.clientWidth }; },
    };
    let observerCallback = null;
    class ResizeObserverMock {
        constructor(callback) { observerCallback = callback; }
        observe(target) { this.target = target; }
    }
    const sandbox = {
        tabs: [], activeTabId: 0,
        document: { getElementById(id) { return id === 'tabBar' ? tabBar : null; } },
        window: { requestAnimationFrame(fn) { frames.push(fn); return frames.length; } },
        ResizeObserver: ResizeObserverMock,
        setTimeout(fn, ms) { timers.push({ fn, ms }); return timers.length; },
        clearTimeout() {},
    };
    sandbox.globalThis = sandbox;
    vm.runInNewContext(read('backend/renderer/tabs.js'), vm.createContext(sandbox), { filename: 'backend/renderer/tabs.js' });

    assert.equal(sandbox.initializeTabLayoutTracking(), true);
    assert.equal(tabBar.dataset.layoutTracking, 'true');
    assert.equal(typeof observerCallback, 'function');
    const framesBeforeResize = frames.length;
    observerCallback([{ contentRect: { width: 1175 } }]);
    assert.ok(frames.length > framesBeforeResize, 'tab-bar ResizeObserver should schedule a re-render');
    assert.ok(timers.some((entry) => entry.ms === 260), 'startup should include a post-layout remeasure');
});

