    assert.match(noModelMtp.rationale, /does not advertise/u);

    assert.throws(() => resolveMtpConfig({ mode: 'on' }, {
        model: { id: 'plain', mtp: null }, capabilities: capabilities(), gpuSelection: {}, cpuCount: 16,
    }), /does not declare an embedded NextN\/MTP head/u);

