test('server lifecycle binds active MTP to the selected model instance while ordinary Auto models stay on router mode', async () => {
    const { startServer } = require('../../runtime/server-process');
    const gpuSelection = {
        mode: 'manual',
        deviceIds: [0],
        devices: [{ index: 0, name: 'Test GPU', memoryFreeMiB: 12_000 }],
        label: 'GPU 0',
    };
    const runtimeCapabilities = {
        router: true,
        splitMode: true,
        splitModeTensor: true,
        tensorSplit: true,
        mtp: detectMtpRuntimeCapabilities(HELP),
    };
    const normalizedBase = {
        port: 18080,
        contextSize: 8192,
        modelContextLength: 131072,
        modelId: 'model.gguf',
        parallel: 1,
        threads: 8,
        threadsBatch: 8,
        batchSize: 512,
        ubatchSize: 512,
        gpuLayers: 'auto',
        gpuMode: 'manual',
        gpuDeviceIds: [0],
        multiGpuMode: 'sequential',
        kvCacheLocation: 'gpu',
        cacheTypeK: 'f16',
        cacheTypeV: 'f16',
        flashAttention: true,
        fit: true,
        mtp: normalizeMtpRequest({ mtpMode: 'auto' }),
    };
    function makeRuntime(model) {
        const launches = [];
        const runtime = {
            process: null,
            processMode: null,
            server: null,
            loadedModelId: null,
            async normalizeServerConfig() { return structuredClone(normalizedBase); },
            async detectCapabilities() { return runtimeCapabilities; },
            async resolveModelSelectionAsync() { return { local: structuredClone(model) }; },
            buildRouterArgs() { return ['--models-dir', 'models']; },
            async spawnAndWait(args, config, mode, readinessPath, timeoutMs, options) {
                launches.push({ args, config: structuredClone(config), mode, readinessPath, timeoutMs, options });
                this.processMode = mode;
                this.server = { host: '127.0.0.1', port: config.port, config, requestedConfig: options.requestedConfig };
            },
            getStatus() {
                return {
                    running: Boolean(this.server && this.processMode === 'router'),
                    processMode: this.processMode,
                    port: this.server?.port || null,
                    mtp: this.server?.config?.mtp || null,
                };
            },
        };
        return { runtime, launches };
    }
    const dependencies = {
        defaultHost: '127.0.0.1',
        startTimeoutMs: 1000,
        async listCudaDevices() { return { available: true, devices: gpuSelection.devices }; },
        resolveCudaSelection() { return gpuSelection; },
    };

    const mtpRuntime = makeRuntime(mtpModel());
    const mtpResult = await startServer(mtpRuntime.runtime, {}, dependencies);
    assert.equal(mtpResult.legacyDeferredStart, true);
    assert.equal(mtpRuntime.runtime.processMode, 'legacy');
    assert.equal(mtpRuntime.launches.length, 0, 'MTP must not start the shared router with model-specific speculative flags');
    assert.equal(mtpRuntime.runtime.server.config.mtp.enabled, true);
    assert.equal(mtpRuntime.runtime.server.config.mtp.model.type, 'embedded-nextn');

    const plainRuntime = makeRuntime({ id: 'model.gguf', mtp: null });
    const plainResult = await startServer(plainRuntime.runtime, {}, dependencies);
    assert.equal(plainResult.legacyDeferredStart, undefined);
    assert.equal(plainRuntime.launches.length, 1);
    assert.equal(plainRuntime.launches[0].mode, 'router');
    assert.equal(plainRuntime.launches[0].config.mtp.enabled, false);
});

