test('Parallel low-memory retry de-weights the CUDA device that actually OOMed', () => {
    const selection = {
        mode: 'all',
        deviceIds: [0, 1],
        devices: [
            { index: 0, name: 'RTX 3060', memoryFreeMiB: 11264 },
            { index: 1, name: 'RTX 3090', memoryFreeMiB: 23552 },
        ],
    };
    const initial = deriveParallelTensorSplit(selection);
    const unpenalizedRetry = deriveParallelTensorSplit(selection, { headroomMiB: 2048 });
    const retry = deriveParallelTensorSplit(selection, { headroomMiB: 2048, penalizeLocalDeviceIndex: 0 });
    const [initialSmall, initialLarge] = initial.argument.split(',').map(Number);
    const [unpenalizedSmall, unpenalizedLarge] = unpenalizedRetry.argument.split(',').map(Number);
    const [retrySmall, retryLarge] = retry.argument.split(',').map(Number);
    assert.ok(retrySmall / retryLarge < initialSmall / initialLarge, 'retry must shift tensor weight away from failed CUDA0');
    assert.ok(retrySmall / retryLarge < unpenalizedSmall / unpenalizedLarge, 'failed-device penalty must contribute beyond extra headroom');
    assert.equal(failedCudaLocalDeviceIndex(
        new Error('allocating 4352.00 MiB on device 0: cudaMalloc failed: out of memory'),
        ['alloc_tensor_range: failed to allocate CUDA0 buffer of size 4563402752'],
    ), 0);
});

