test('llama-server capability discovery distinguishes layer-only and tensor-capable split-mode builds', async () => {
    const baseRuntime = () => ({
        capabilities: null,
        executable: 'llama-server',
    });
    const dependenciesFor = (help) => ({
        fs: { existsSync() { return true; } },
        async runProcessCapture() { return { stdout: help, stderr: '', status: 0 }; },
    });

    const modern = baseRuntime();
    await detectCapabilities(modern, dependenciesFor('--models-dir\n--split-mode {none,layer,row,tensor}\n--tensor-split N0,N1\n--fit [on|off]\n--flash-attn {on,off,auto}'));
    assert.equal(modern.capabilities.splitMode, true);
    assert.equal(modern.capabilities.splitModeTensor, true);
    assert.equal(modern.capabilities.tensorSplit, true);

    const older = baseRuntime();
    await detectCapabilities(older, dependenciesFor('--models-dir\n--split-mode {none,layer,row}\n--fit [on|off]\n--flash-attn'));
    assert.equal(older.capabilities.splitMode, true);
    assert.equal(older.capabilities.splitModeTensor, false);
    assert.equal(older.capabilities.tensorSplit, false);
});

