test('legacy Parallel OOM retry refreshes VRAM and launches with a more conservative tensor split', async () => {
    const { loadLegacyModel } = require('../../runtime/model-lifecycle');
    const requestedConfig = {
        port: 18080,
        contextSize: 8192,
        parallel: 1,
        multiGpuMode: 'parallel',
        flashAttention: true,
        fit: false,
        gpuLayers: 'auto',
        batchSize: 2048,
        ubatchSize: 512,
        gpuMode: 'all',
        gpuDeviceIds: [],
    };
    const initialSelection = {
        mode: 'all',
        deviceIds: [0, 1],
        visibleDevices: null,
        label: 'ALL (0, 1)',
        devices: [
            { index: 0, name: 'RTX 3060', memoryFreeMiB: 11264 },
            { index: 1, name: 'RTX 3090', memoryFreeMiB: 23552 },
        ],
    };
    const initialConfig = applyParallelTensorSplit(requestedConfig, initialSelection);
    const launched = [];
    const runtime = {
        server: { config: initialConfig, requestedConfig, gpuSelection: initialSelection },
        process: null,
        loadedModelId: null,
        loadedProjectorPath: null,
        modelsDir: 'models',
        activeStreams: new Map(),
        pendingStreams: new Map(),
        logLines: [],
        transport: {},
        async resolveModelSelectionAsync() { return { local: { id: 'model', path: 'model.gguf' } }; },
        async stopProcessOnly() {},
        async detectCapabilities() { return modernCapabilities; },
        buildLegacyArgs(config) { return ['--tensor-split', config.tensorSplit]; },
        async spawnAndWait(_args, config, _mode, _health, _timeout, options) {
            launched.push({ config: { ...config }, gpuSelection: options.gpuSelection });
            if (launched.length === 1) {
                this.logLines.push('allocating 4352.00 MiB on device 0: cudaMalloc failed: out of memory');
                throw new Error('llama-server exited before becoming ready: cudaMalloc failed: out of memory');
            }
            this.server = { port: 18080, config, requestedConfig: options.requestedConfig, gpuSelection: options.gpuSelection };
        },
        log() {},
    };
    const result = await loadLegacyModel(runtime, {
        modelId: 'model',
        projectorPath: null,
        validateProjectorPath: (value) => value,
        loadTimeoutMs: 1000,
    }, {
        async listCudaDevices() {
            return {
                available: true,
                devices: [
                    { index: 0, name: 'RTX 3060', memoryFreeMiB: 11100 },
                    { index: 1, name: 'RTX 3090', memoryFreeMiB: 23400 },
                ],
            };
        },
        resolveCudaSelection,
    });
    assert.equal(launched.length, 2);
    const [firstSmall, firstLarge] = launched[0].config.tensorSplit.split(',').map(Number);
    const [retrySmall, retryLarge] = launched[1].config.tensorSplit.split(',').map(Number);
    assert.ok(retrySmall / retryLarge < firstSmall / firstLarge, 'retry must shift load away from the OOMing 3060');
    assert.ok(launched[1].config.batchSize <= 256);
    assert.equal(launched[1].config.contextSize, requestedConfig.contextSize, 'retry must preserve requested context');
    assert.equal(result.memoryFallback.reason, 'device-memory');
    assert.ok(result.memoryFallback.changes.tensorSplit);
});

