// TEST MODULE: backend/Dev/tests/node-runtime-deferred-unload-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/node-runtime-deferred-unload-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const viewsSource = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'views.js'), 'utf8');
const controlsSource = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'nodes', 'editor', 'controls.js'), 'utf8');
const contextContractSource = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'context-contract.js'), 'utf8');

function runtimeContext() {
    const unloadCalls = [];
    let invalidations = 0;
    const loader = { id: 2, type: 'modelLoader', selectedModel: 'model.gguf', params: {}, status: 'active', statusMessage: 'loaded' };
    const context = {
        console,
        Promise,
        setTimeout() {},
        clearTimeout() {},
        document: {
            body: { classList: { toggle() {} } },
            getElementById() { return null; },
        },
        nodeEditorState: { nodes: [loader] },
        darkstar: {
            nodes: {
                async getStatus() { return { success: true, loadedModelId: 'actually-loaded.gguf' }; },
                async unloadModel(modelId) { unloadCalls.push(modelId); return { success: true, unloaded: true }; },
            },
        },
        invalidateContextContractForModelUnload() { invalidations += 1; },
        syncProjectComposerGate() {},
        syncComposerControls() {},
        rerenderNode() {},
        getNodeDef() { return null; },
        globalThis: null,
        window: null,
    };
    context.globalThis = context;
    context.window = context;
    vm.createContext(context);
    vm.runInContext(viewsSource, context, { filename: 'views.js' });
    vm.runInContext(controlsSource, context, { filename: 'controls.js' });
    return { context, unloadCalls, invalidations: () => invalidations };
}

test('runtime-owning node edits defer model unload until Nodes -> Chat, with GGUF Server context sizing runtime-affecting and L_Sampler request-time only', async () => {
    const { context, unloadCalls, invalidations } = runtimeContext();

    const control = { type: 'control', params: { nameConversations: true, autoCompact: false, modelIdleUnloadEnabled: false } };
    let before = context.nodeRuntimeUnloadRelevantSignature(control);
    control.params.nameConversations = false;
    assert.equal(context.noteNodeRuntimeConfigMutation(control, before), true, 'Control settings that affect inference behavior must still dirty the runtime');
    assert.equal(unloadCalls.length, 0, 'editing while still in Nodes must never unload immediately');

    context.nodeRuntimeUnloadPending = false;
    before = context.nodeRuntimeUnloadRelevantSignature(control);
        control.params.futureSetting = 'future-compatible';
    assert.equal(context.noteNodeRuntimeConfigMutation(control, before), false, 'unknown Control metadata must not silently acquire model-reload semantics');
    context.nodeRuntimeUnloadPending = true;

    await context.unloadModelForDeferredNodeChanges();
    assert.deepEqual(unloadCalls, ['actually-loaded.gguf'], 'deferred unload must target the model the runtime says is actually loaded');
    assert.equal(invalidations(), 1, 'successful model unload must invalidate and unblock the context contract');

    context.nodeRuntimeUnloadPending = false;
    const server = { type: 'loadServer', params: { parallel: 1, contextSize: '8192', contextPercent: 50, futureServerSetting: false } };
    before = context.nodeRuntimeUnloadRelevantSignature(server);
    server.params.parallel = 2;
    assert.equal(context.noteNodeRuntimeConfigMutation(server, before), true,
        'GGUF Server runtime settings must still defer unload because they change llama.cpp process configuration');

    context.nodeRuntimeUnloadPending = false;
    before = context.nodeRuntimeUnloadRelevantSignature(server);
    server.params.contextPercent = 100;
    server.params.contextSize = '16384';
    assert.equal(context.noteNodeRuntimeConfigMutation(server, before), true,
        'GGUF Server Context size changes must defer an unload because they change llama.cpp runtime allocation');

    context.nodeRuntimeUnloadPending = false;
    const localSampler = { type: 'localSampler', params: { reasoning: 'auto', temperature: 0.6, topP: 0.95 } };
    before = context.nodeRuntimeUnloadRelevantSignature(localSampler);
    localSampler.params.reasoning = 'on';
    localSampler.params.temperature = 0.9;
    assert.equal(context.noteNodeRuntimeConfigMutation(localSampler, before), false,
        'L_Sampler Reasoning Effort and request-time sampling changes must never unload or restart the loaded runtime');
    assert.equal(context.nodeRuntimeUnloadPending, false);

    context.nodeRuntimeUnloadPending = false;
    const contextNode = { type: 'context', params: { systemPrompt: '', includeHistory: true } };
    before = context.nodeRuntimeUnloadRelevantSignature(contextNode);
    contextNode.params.systemPrompt = 'changed';
    assert.equal(context.noteNodeRuntimeConfigMutation(contextNode, before), true, 'the whole Context params object is protected');

    context.nodeRuntimeUnloadPending = false;
    const sampler = { type: 'sampler', params: { stop: '' } };
    before = context.nodeRuntimeUnloadRelevantSignature(sampler);
    sampler.params.stop = 'END';
    assert.equal(context.noteNodeRuntimeConfigMutation(sampler, before), false, 'Orchestrator termination controls must not unload the model');
    assert.equal(context.nodeRuntimeUnloadPending, false);

    const loader = context.nodeEditorState.nodes[0];
    loader.params = { projectorPath: 'C:\\Models\\vision-a.mmproj', projectorSource: 'manual' };
    context.getNodeDef = () => null;
    context.nodeRuntimeUnloadPending = false;
    assert.equal(context.setNodeParamValue(loader.id, 'projectorPath', 'string', 'C:\\Models\\vision-b.mmproj'), true);
    assert.equal(context.nodeRuntimeUnloadPending, true, 'changing the selected projector must dirty the loaded runtime');
    context.nodeRuntimeUnloadPending = false;
    assert.equal(context.setNodeParamValue(loader.id, 'projectorPath', 'string', 'C:\\Models\\vision-b.mmproj'), true);
    assert.equal(context.nodeRuntimeUnloadPending, false, 're-selecting the same projector must not trigger a redundant unload');
    assert.equal(context.setNodeParamValue(loader.id, 'projectorPath', 'string', ''), true);
    assert.equal(context.nodeRuntimeUnloadPending, true, 'selecting No Projector must dirty a runtime that had a projector');

    const skills = { id: 7, type: 'tools', params: { providers: [], skills: [{ path: 'C:\\Skills\\alpha\\SKILL.md' }] }, status: 'active', statusMessage: '' };
    context.nodeEditorState.nodes.push(skills);
    context.getNodeDef = (type) => type === 'tools' ? {
        async onAction(node, action) {
            if (action === 'add-skill-file') node.params.skills.push({ path: 'C:\\Skills\\beta\\SKILL.md' });
            if (action === 'remove-skill-file:1') node.params.skills.splice(1, 1);
        },
        async onFilesDropped(node, paths) { node.params.skills.push({ path: paths[0] }); },
    } : null;
    context.nodeRuntimeUnloadPending = false;
    await context.runNodeAction(null, { disabled: false, dataset: { nodeId: '7', action: 'add-skill-file' } });
    assert.equal(context.nodeRuntimeUnloadPending, true, 'adding a skill through the normal node action must dirty the runtime');
    context.nodeRuntimeUnloadPending = false;
    await context.runNodeAction(null, { disabled: false, dataset: { nodeId: '7', action: 'remove-skill-file:1' } });
    assert.equal(context.nodeRuntimeUnloadPending, true, 'removing a skill must dirty the runtime');
    context.nodeRuntimeUnloadPending = false;
    await context.runNodeFileDrop({
        preventDefault() {}, stopPropagation() {}, dataTransfer: { files: [{ path: 'C:\\Skills\\gamma\\SKILL.md' }] },
    }, {
        dataset: { nodeId: '7' }, classList: { remove() {} }, setAttribute() {},
    });
    assert.equal(context.nodeRuntimeUnloadPending, true, 'adding a skill by drag-and-drop must use the same dirty-runtime policy');

    const settingsView = {
        classList: {
            active: true,
            contains(name) { return name === 'active' && this.active; },
            add() { this.active = true; },
            remove() { this.active = false; },
        },
    };
    context.document.getElementById = (id) => id === 'settingsView' ? settingsView : null;
    context.playUiSound = () => {};
    context.setNodeViewNativeOverlayBlocked = () => {};
    context.restoreComposerFocusAfterNodeView = () => {};
    context.scheduleTabLayoutRefresh = () => {};
    const callsBeforeReturn = unloadCalls.length;
    context.switchView('chat');
    if (context.nodeRuntimeUnloadInFlight) await context.nodeRuntimeUnloadInFlight;
    assert.equal(unloadCalls.length, callsBeforeReturn + 1, 'the pending unload must execute when Nodes returns to Chat');
    assert.equal(settingsView.classList.active, false, 'the normal Nodes -> Chat view transition must still complete');

    assert.match(viewsSource, /if \(wasInNodeView && nodeRuntimeUnloadPending\) unloadModelForDeferredNodeChanges\(\);/u,
        'the deferred unload must be consumed specifically on the Nodes -> Chat transition');
    assert.match(controlsSource, /runtimeSignatureBefore[\s\S]*noteNodeRuntimeConfigMutation\(node, runtimeSignatureBefore\)/u,
        'generic parameter/action plumbing must own mutation detection so future protected settings inherit the policy');
    assert.match(controlsSource, /runNodeFileDrop[\s\S]*runtimeSignatureBefore[\s\S]*noteNodeRuntimeConfigMutation\(node, runtimeSignatureBefore\)/u,
        'file-drop mutations must participate in the same deferred runtime invalidation path');
    assert.match(contextContractSource, /function invalidateContextContractForModelUnload\([\s\S]*setContextContractRuntimeContextReady\(false\)[\s\S]*clearComposerContextContract/u,
        'model unload must clear context authority and stale per-tab contract latches');
});
});

