TEST_FACTORIES.set("backend/Dev/tests/offline-browser-channel-compat-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const test = require('node:test');
const path = require('node:path');

const CHANNELS = require(path.resolve(__dirname, '../../protocol/channels.js'));

test('existing offline browser channel values remain unchanged', () => {
    assert.equal(CHANNELS.OFFLINE_BROWSER_OPEN, 'darkstar:offline-browser:open');
    assert.equal(CHANNELS.OFFLINE_BROWSER_OVERLAY_BLOCKED, 'darkstar:offline-browser:overlay-blocked');
    assert.equal(CHANNELS.OFFLINE_BROWSER_BOUNDS, 'darkstar:offline-browser:bounds');
    assert.equal(CHANNELS.OFFLINE_BROWSER_GET_STATUS, 'darkstar:offline-browser:get-status');
    assert.equal(CHANNELS.OFFLINE_BROWSER_INPUT, 'darkstar:offline-browser:input');
});

test('newer offline browser constants never resolve to undefined', () => {
    assert.equal(CHANNELS.OFFLINE_BROWSER_SCREENSHOT, 'darkstar:offline-browser:screenshot');
    assert.equal(CHANNELS.OFFLINE_BROWSER_CAPTURE_FRAME, 'darkstar:offline-browser:capture-frame');
    assert.equal(CHANNELS.OFFLINE_BROWSER_TAB_ACTIVATE, 'darkstar:offline-browser:tab-activate');
    assert.equal('OFFLINE_BROWSER_SCREENSHOT' in CHANNELS, true);
});

test('fallback is strictly scoped to the offline browser namespace', () => {
    assert.equal(CHANNELS.NOT_A_REAL_CHANNEL, undefined);
    assert.equal('NOT_A_REAL_CHANNEL' in CHANNELS, false);
});

test('derived browser channels remain unique during Electron handler registration', () => {
    const registered = new Set();
    const ipcMain = {
        handle(channel) {
            assert.equal(typeof channel, 'string');
            assert.ok(channel.length > 0);
            assert.equal(registered.has(channel), false, `duplicate handler channel: ${channel}`);
            registered.add(channel);
        },
    };
    for (const key of [
        'OFFLINE_BROWSER_OPEN',
        'OFFLINE_BROWSER_CHOOSE',
        'OFFLINE_BROWSER_SCREENSHOT',
        'OFFLINE_BROWSER_CAPTURE_FRAME',
        'OFFLINE_BROWSER_TAB_ACTIVATE',
    ]) {
        ipcMain.handle(CHANNELS[key], () => undefined);
    }
    assert.equal(registered.size, 5);
});


test('every offline-browser constant referenced by the installed IPC registrar resolves to a unique concrete channel', () => {
    const fs = require('node:fs');
    const registrarPath = path.resolve(__dirname, '../../ipc/register-offline-browser-ipc.js');
    const source = fs.readFileSync(registrarPath, 'utf8');
    const keys = [...source.matchAll(/CHANNELS\.(OFFLINE_BROWSER_[A-Z0-9_]+)/g)].map((match) => match[1]);
    assert.ok(keys.length > 0, 'expected offline-browser channel references in registrar');
    const uniqueKeys = [...new Set(keys)];
    const channels = uniqueKeys.map((key) => {
        const channel = CHANNELS[key];
        assert.equal(typeof channel, 'string', `${key} must resolve to a string`);
        assert.ok(channel.startsWith('darkstar:offline-browser:'), `${key} must stay in the offline-browser namespace`);
        assert.notEqual(channel, 'undefined');
        return channel;
    });
    assert.equal(new Set(channels).size, channels.length, 'offline-browser registrar channels must be unique');
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/online-browser-boundary-reset-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/online-browser-boundary-reset-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const test = require('node:test');

const { executeToolCalls, isOnlineBrowserResult } = require('../../runtime/agent-loop');

function toolCall(id, name, args) {
    return {
        id,
        type: 'function',
        function: { name, arguments: JSON.stringify(args || {}) },
    };
}

function fixture(browserRawResult) {
    const executed = [];
    const agentRuntime = {
        definitions: [
            { type: 'function', function: { name: 'browser_control', parameters: { type: 'object' } } },
            { type: 'function', function: { name: 'replace_file', parameters: { type: 'object' } } },
        ],
        handlers: new Map([['browser_control', {}], ['replace_file', {}]]),
        skills: [],
        catalog: '',
        toolChoice: 'auto',
    };
    const runtime = {
        toolService: {
            describeCall(call) {
                return {
                    name: call.function.name,
                    rawArguments: call.function.arguments,
                    arguments: JSON.parse(call.function.arguments || '{}'),
                    displayCommand: call.function.name,
                };
            },
            async execute(_executionRuntime, call) {
                executed.push(call.function.name);
                if (call.function.name === 'browser_control') {
                    return {
                        result: JSON.stringify(browserRawResult),
                        rawResult: structuredClone(browserRawResult),
                        contextMessages: [],
                        durationMs: 1,
                    };
                }
                return {
                    result: '{"success":true}',
                    rawResult: { success: true },
                    contextMessages: [],
                    durationMs: 1,
                };
            },
        },
    };
    return { runtime, agentRuntime, executed };
}

async function executePair(browserArgs, browserRawResult) {
    const { runtime, agentRuntime, executed } = fixture(browserRawResult);
    const workingMessages = [];
    const toolMessages = [];
    const result = await executeToolCalls(runtime, {
        agentRuntime,
        calls: [
            toolCall('browser', 'browser_control', browserArgs),
            toolCall('local', 'replace_file', { path: 'x.txt', content: 'ok' }),
        ],
        controller: new AbortController(),
        handlers: {},
        preparations: [],
        toolMessages,
        toolRound: 1,
        working: [],
        workingMessages,
        visionEnabled: false,
        interactionId: 'test',
    });
    return { result, executed, workingMessages, toolMessages };
}

test('browser reset is mode initialization, not observation of an untrusted online page', () => {
    const resetResult = {
        success: true,
        action: 'reset',
        mode: 'online',
        status: { mode: 'online', url: '' },
    };
    assert.equal(isOnlineBrowserResult('browser_control', resetResult, { action: 'reset' }), false);
});

test('reset does not remove local tools later in the same agent round', async () => {
    const state = await executePair(
        { action: 'reset' },
        { success: true, action: 'reset', mode: 'online', status: { mode: 'online', url: '' } },
    );

    assert.deepEqual(state.executed, ['browser_control', 'replace_file']);
    assert.equal(state.result.browserCompartmentActivated, false);
    assert.equal(state.result.completedCalls, 2);
    assert.equal(state.workingMessages.some((message) => /ONLINE_BROWSER_CAPABILITY_BOUNDARY/u.test(String(message.content || ''))), false);
});

test('actual HTTPS page observation still activates the browser-only boundary', async () => {
    const state = await executePair(
        { action: 'open', url: 'https://example.com/' },
        { success: true, action: 'open', mode: 'online', url: 'https://example.com/' },
    );

    assert.deepEqual(state.executed, ['browser_control'], 'local tool execution must remain blocked after real online-page observation');
    assert.equal(state.result.browserCompartmentActivated, true);
    assert.equal(state.result.completedCalls, 1);
    assert.match(String(state.workingMessages.at(-1)?.content || ''), /online page had already been observed/u);
});

test('offline and non-HTTPS opens never activate the online-page boundary', () => {
    assert.equal(isOnlineBrowserResult('browser_control', { success: true, action: 'open', mode: 'offline' }, { action: 'open', path: 'local.html' }), false);
    assert.equal(isOnlineBrowserResult('browser_control', { success: true, action: 'open', mode: 'online', url: '' }, { action: 'open' }), false);
});
});

