// TEST MODULE: backend/Dev/tests/online-browser-control-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/online-browser-control-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const test = require('node:test');

const { createOnlineBrowserControl } = require('../../browser/online-browser-control');

function fixture() {
    let pointer = { x: 10, y: 20, button: 'left', buttons: 1 };
    let activeGrid = { gridId: 'grid-1', rows: 4, columns: 4 };
    const status = { url: 'https://example.com/', title: 'Example' };
    const pressedKeys = new Map();
    const consoleMessages = [];
    const calls = { mouse: [], key: [], wait: [], execute: [], snapshots: 0 };
    const webContents = {
        navigationHistory: {
            canGoBack: () => true,
            canGoForward: () => true,
            goBack() { calls.back = (calls.back || 0) + 1; },
            goForward() { calls.forward = (calls.forward || 0) + 1; },
        },
        reloadIgnoringCache() { calls.reload = (calls.reload || 0) + 1; },
        async executeJavaScript(source) {
            calls.execute.push(String(source));
            return { ok: true, layoutId: 'layout-1', viewport: { width: 900, height: 700 }, elements: [] };
        },
        async capturePage() {
            return { toPNG: () => Buffer.from('png') };
        },
    };
    const context = {
        getWindow: () => ({ webContents }),
        getViewport: () => ({ width: 900, height: 700 }),
        getPointer: () => pointer,
        setPointer(value) { pointer = value; },
        getActiveGrid: () => activeGrid,
        setActiveGrid(value) { activeGrid = value; },
        async navigate(url) { status.url = String(url); return { url: status.url, title: 'Opened' }; },
        async reset() { status.url = ''; return { mode: 'online', url: '' }; },
        async snapshot() { calls.snapshots += 1; return { text: 'snapshot', data: { ok: true } }; },
        spatialMapText: () => 'map',
        async ensureActiveGrid() { return activeGrid ? { ok: true, ...activeGrid } : null; },
        async captureWithOverlay(args) { return { overlay: true, action: args.action }; },
        async captureRegionHash() { return 'hash'; },
        async resolvePoint(args, prefix = '') {
            return prefix === 'end' ? { x: 30, y: 40 } : { x: Number(args.x) || 5, y: Number(args.y) || 6 };
        },
        async dispatchMouse(type, point, args) {
            calls.mouse.push({ type, point: { ...point }, args: { ...args } });
            pointer.x = point.x;
            pointer.y = point.y;
            if (type === 'mousePressed') { pointer.button = args.button || 'left'; pointer.buttons = 1; }
            if (type === 'mouseReleased') { pointer.button = 'none'; pointer.buttons = 0; }
        },
        async dispatchKey(type, key, modifiers) { calls.key.push({ type, key, modifiers }); },
        async ensureDebugger() { return { async sendCommand(name, args) { calls.debug = { name, args }; } }; },
        async settle() { calls.settle = (calls.settle || 0) + 1; },
        async wait(ms) { calls.wait.push(ms); },
        status,
        pressedKeys,
        consoleMessages,
        maxWaitMs: 10_000,
        untrustedWarning: 'UNTRUSTED',
        sanitizeStatus(value) { return { ...value }; },
    };
    return {
        calls,
        context,
        control: createOnlineBrowserControl(context),
        getActiveGrid: () => activeGrid,
        getPointer: () => pointer,
        pressedKeys,
        status,
    };
}

test('online browser control routes open/status through explicit dependencies', async () => {
    const state = fixture();
    const opened = await state.control({ action: 'open', url: 'https://open.example/' });
    assert.equal(opened.url, 'https://open.example/');
    assert.equal(opened.snapshot, 'snapshot');
    assert.equal(state.calls.snapshots, 1);

    const status = await state.control({ action: 'status' });
    assert.equal(status.status.url, 'https://open.example/');
    assert.equal(status.pointer.x, 10);
});

test('online browser pointer actions preserve constrained mouse sequencing', async () => {
    const state = fixture();
    const result = await state.control({ action: 'click', x: 25, y: 35, snapshot_after: false, wait_ms: 0 });
    assert.deepEqual(state.calls.mouse.map((entry) => entry.type), ['mouseMoved', 'mousePressed', 'mouseReleased']);
    assert.deepEqual(result.point, { x: 25, y: 35 });
    assert.equal(result.snapshot, null);
});

test('shared browser input engine preserves online multi-click as one CDP press/release pair with clickCount', async () => {
    const state = fixture();
    const result = await state.control({ action: 'click', x: 25, y: 35, click_count: 3, snapshot_after: false, wait_ms: 0 });
    assert.deepEqual(state.calls.mouse.map((entry) => entry.type), ['mouseMoved', 'mousePressed', 'mouseReleased']);
    assert.equal(state.calls.mouse[1].args.clickCount, 3);
    assert.equal(state.calls.mouse[2].args.clickCount, 3);
    assert.equal(result.clickCount, 3);
});

test('online browser release_all clears held keys and pointer state', async () => {
    const state = fixture();
    state.pressedKeys.set('Shift', ['shift']);
    state.pressedKeys.set('Control', ['ctrl']);
    const result = await state.control({ action: 'release_all' });
    assert.deepEqual(state.calls.key.map((entry) => [entry.type, entry.key]), [['keyUp', 'Shift'], ['keyUp', 'Control']]);
    assert.equal(state.pressedKeys.size, 0);
    assert.deepEqual(state.getPointer(), { x: 10, y: 20, button: 'none', buttons: 0 });
    assert.deepEqual(result.pressedKeys, []);
});

test('online browser grid_clear resets the shared active-grid state', async () => {
    const state = fixture();
    const result = await state.control({ action: 'grid_clear' });
    assert.equal(result.gridActive, false);
    assert.equal(state.getActiveGrid(), null);
    assert.equal(state.calls.execute.length, 1);
});

test('online browser control rejects page actions before open and unknown actions explicitly', async () => {
    const state = fixture();
    state.status.url = '';
    await assert.rejects(() => state.control({ action: 'snapshot' }), /No online page is open/u);
    state.status.url = 'https://example.com/';
    await assert.rejects(() => state.control({ action: 'does-not-exist' }), /Unsupported browser_control action/u);
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/per-tab-browser-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/per-tab-browser-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const { EventEmitter } = require('node:events');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const { TabbedBrowserService } = require(path.join(ROOT, 'backend', 'browser', 'tabbed-browser-service.js'));
const { ToolService } = require(path.join(ROOT, 'backend', 'agent', 'tool-service.js'));
const { resolveToolResultAction } = require(path.join(ROOT, 'backend', 'agent', 'tool-runtime.js'));

class FakeSession extends EventEmitter {
    constructor() {
        super();
        this.webRequest = { onBeforeRequest() {} };
    }
    setPermissionCheckHandler() {}
    setPermissionRequestHandler() {}
}

class FakeWebContents extends EventEmitter {
    constructor() {
        super();
        this.session = new FakeSession();
        this.debugger = new EventEmitter();
        this.debugger.isAttached = () => false;
        this.destroyed = false;
    }
    setAudioMuted() {}
    setZoomFactor() {}
    setWindowOpenHandler() {}
    canGoBack() { return false; }
    canGoForward() { return false; }
    isDestroyed() { return this.destroyed; }
    destroy() { this.destroyed = true; }
}

class FakeBrowserView {
    static instances = [];
    constructor() {
        this.webContents = new FakeWebContents();
        this.bounds = { x: 0, y: 0, width: 0, height: 0 };
        FakeBrowserView.instances.push(this);
    }
    setAutoResize() {}
    setBounds(bounds) { this.bounds = { ...bounds }; }
    getBounds() { return { ...this.bounds }; }
}

class FakeWindow extends EventEmitter {
    constructor() {
        super();
        this.attached = null;
        this.webContents = { send() {}, focus() {}, isFocused() { return true; } };
    }
    isDestroyed() { return false; }
    isFocused() { return true; }
    blurWebView() {}
    getContentBounds() { return { x: 0, y: 0, width: 1400, height: 900 }; }
    setBrowserView(view) { this.attached = view; }
    removeBrowserView(view) { if (this.attached === view) this.attached = null; }
}

class FakeOnlineBrowser extends EventEmitter {
    constructor(browserId) {
        super();
        this.browserId = browserId;
        this.ready = false;
        this.child = null;
        this.destroyed = false;
    }
    setStreaming() { return Promise.resolve({}); }
    setViewport() { return Promise.resolve({}); }
    navigate(url) { this.url = url; return Promise.resolve({ url, path: url, title: url, loading: false }); }
    control() { return Promise.resolve({}); }
    getStatus() { return Promise.resolve({ url: this.url || '', loading: false }); }
    sendInput() { return Promise.resolve(true); }
    reset() { this.url = ''; return Promise.resolve({ url: '', loading: false }); }
    destroy() { this.destroyed = true; return Promise.resolve(); }
}

function fixture() {
    FakeBrowserView.instances.length = 0;
    const service = new TabbedBrowserService({
        baseDir: ROOT,
        BrowserView: FakeBrowserView,
        onlineFactory: (browserId) => new FakeOnlineBrowser(browserId),
    });
    const window = new FakeWindow();
    service.attachWindow(window);
    service.setBounds({ x: 900, y: 80, width: 500, height: 760 }, { browserId: '0' });
    return { service, window };
}

test('each chat tab owns a distinct live BrowserView and switching tabs restores the exact prior instance', async () => {
    const { service, window } = fixture();

    service.activate('11');
    service.setVisible(true, { browserId: '11' });
    const firstRecord = service.sessions.get('11');
    const firstView = firstRecord.service.offline.view;
    firstRecord.service.offline.currentRelativePath = 'first.html';
    firstRecord.service.offline.status.path = 'first.html';

    service.activate('22');
    service.setVisible(true, { browserId: '22' });
    const secondRecord = service.sessions.get('22');
    const secondView = secondRecord.service.offline.view;
    secondRecord.service.offline.currentRelativePath = 'second.html';
    secondRecord.service.offline.status.path = 'second.html';

    assert.notEqual(firstRecord.service, secondRecord.service, 'tabs must not share one HybridBrowserService');
    assert.notEqual(firstView, secondView, 'tabs must not share one native BrowserView');
    assert.notEqual(firstView.webContents, secondView.webContents, 'tabs must not share Chromium webContents/session state');
    assert.notEqual(firstRecord.service.online, secondRecord.service.online, 'tabs must not share the isolated online-browser host client');
    assert.equal(window.attached, secondView, 'the active tab owns the attached native browser surface');

    const firstStatus = service.activate('11');
    assert.equal(service.sessions.get('11').service, firstRecord.service, 'switching back must reuse the original tab browser service');
    assert.equal(firstRecord.service.offline.view, firstView, 'switching back must reuse the original native BrowserView');
    assert.equal(window.attached, firstView);
    assert.equal(firstStatus.path, 'first.html', 'tab A must recover its own navigation state');
    assert.equal(firstStatus.visible, true, 'tab A must recover its own browser-open state');
    assert.equal(firstView.webContents.destroyed, false);

    const secondStatus = service.activate('22');
    assert.equal(window.attached, secondView);
    assert.equal(secondStatus.path, 'second.html', 'tab B must retain independent navigation state');
    assert.equal(secondStatus.visible, true);
    assert.equal(secondView.webContents.destroyed, false);

    await service.destroy();
});

test('Internet Access off tears down online hosts and Core rejects model online navigation until re-enabled', async () => {
    const { service } = fixture();
    service.activate('11');
    const record = service.sessions.get('11');
    await service.controlBrowser({ action: 'open', url: 'https://example.com' }, { browserId: '11', workspaceId: 'workspace-11' });
    assert.equal(record.service.mode, 'online');

    const disabled = await service.setInternetAccess(false);
    assert.deepEqual(disabled, { enabled: false });
    assert.equal(record.service.mode, 'offline', 'disabling internet must immediately return every live tab to the offline browser');
    assert.equal(record.service.online.destroyed, true, 'disabling internet must terminate any isolated online-browser host');
    await assert.rejects(
        service.controlBrowser({ action: 'open', url: 'https://example.com' }, { browserId: '11', workspaceId: 'workspace-11' }),
        (error) => error && error.code === 'INTERNET_ACCESS_DISABLED'
    );

    await service.setInternetAccess(true);
    await service.controlBrowser({ action: 'open', url: 'https://example.org' }, { browserId: '11', workspaceId: 'workspace-11' });
    assert.equal(record.service.mode, 'online');
    await service.destroy();
});

test('browser work routed to an inactive tab stays in that tab and cannot replace the active tab browser', async () => {
    const { service, window } = fixture();

    service.activate('1');
    service.setVisible(true, { browserId: '1' });
    const activeRecord = service.sessions.get('1');
    const activeView = activeRecord.service.offline.view;

    const inactive = service._record('2', true);
    inactive.service.offline.currentRelativePath = 'background.html';
    inactive.service.offline.status.path = 'background.html';
    service.setVisible(true, { browserId: '2' });

    assert.equal(service.activeBrowserId, '1');
    assert.equal(window.attached, activeView, 'an inactive tab cannot attach its BrowserView over the active tab');
    assert.equal(service.getStatus({ browserId: '2' }).path, 'background.html');
    assert.equal(service.getStatus({ browserId: '2' }).visible, true, 'inactive tab remembers that its browser should be open');

    const status = service.activate('2');
    assert.equal(window.attached, inactive.service.offline.view);
    assert.equal(status.path, 'background.html');
    assert.equal(status.visible, true);

    await service.destroy();
});

test('first agent browser interaction opens once per chat tab and manual close remains respected', async () => {
    const { service, window } = fixture();

    service.activate('11');
    assert.equal(service.getStatus({ browserId: '11' }).visible, false);

    const firstUse = service.showOnFirstAgentBrowserInteraction({ browserId: '11' });
    assert.equal(firstUse.visible, true, 'the first model browser interaction should expose the browser for that chat tab');
    const firstView = service.sessions.get('11').service.offline.view;
    assert.equal(window.attached, firstView, 'the active tab browser should be attached immediately on first model browser use');

    service.setVisible(false, { browserId: '11' });
    assert.equal(service.getStatus({ browserId: '11' }).visible, false);
    const laterUse = service.showOnFirstAgentBrowserInteraction({ browserId: '11' });
    assert.equal(laterUse.visible, false, 'later model browser actions must not reopen a browser the user manually closed');

    service.activate('22');
    assert.equal(service.getStatus({ browserId: '22' }).visible, false, 'each chat tab starts with independent first-use state');
    assert.equal(service.showOnFirstAgentBrowserInteraction({ browserId: '22' }).visible, true, 'a different chat tab gets its own one-time auto-open');

    service.activate('23');
    service.setVisible(true, { browserId: '23' });
    const alreadyOpenFirstUse = service.showOnFirstAgentBrowserInteraction({ browserId: '23' });
    assert.equal(alreadyOpenFirstUse.visible, true, 'first use must not disturb a browser that is already open');
    service.setVisible(false, { browserId: '23' });
    assert.equal(service.showOnFirstAgentBrowserInteraction({ browserId: '23' }).visible, false, 'an already-open first use is still consumed exactly once');

    await service.destroy();
});

test('browser tool result actions trigger the per-tab first-use visibility hook before browser work', async () => {
    const calls = [];
    const browser = {
        showOnFirstAgentBrowserInteraction(options) { calls.push(['show', String(options.browserId)]); },
        controlBrowser(result, options) { calls.push(['control', String(options.browserId), result.action]); return Promise.resolve({ success: true }); },
        captureHtml(result, options) { calls.push(['capture', String(options.browserId), result.path]); return Promise.resolve({ success: true }); },
    };

    await resolveToolResultAction({ __darkstarAction: 'browser_control', action: 'reset' }, {
        offlineBrowser: browser, toolName: 'browser_control', browserId: '31', visionEnabled: false,
    });
    await resolveToolResultAction({ __darkstarAction: 'screenshot_html', path: 'page.html' }, {
        offlineBrowser: browser, toolName: 'screenshot_html', browserId: '32', visionEnabled: true,
    });

    assert.deepEqual(calls, [
        ['show', '31'], ['control', '31', 'reset'],
        ['show', '32'], ['capture', '32', 'page.html'],
    ]);
});

test('closing a tab releases only that tab browser and leaves sibling browser instances alive', async () => {
    const { service } = fixture();
    service.activate('3');
    service.setVisible(true, { browserId: '3' });
    const third = service.sessions.get('3');
    service.activate('4');
    service.setVisible(true, { browserId: '4' });
    const fourth = service.sessions.get('4');

    const released = await service.release('3');
    assert.equal(released, true);
    assert.equal(service.sessions.has('3'), false);
    assert.equal(third.service.offline.view, null, 'released tab destroys its native BrowserView');
    assert.ok(fourth.service.offline.view, 'sibling tab browser remains alive');
    assert.equal(fourth.service.offline.view.webContents.destroyed, false);

    await service.destroy();
});



test('agent interaction cleanup reaches the originating tab browser through the hybrid facade', async () => {
    const { service } = fixture();
    service.activate('11');
    const first = service.sessions.get('11');
    const second = service._record('22', true);
    const firstCalls = [];
    const secondCalls = [];
    first.service.offline.finishAgentInteraction = async (interactionId) => { firstCalls.push(interactionId); };
    second.service.offline.finishAgentInteraction = async (interactionId) => { secondCalls.push(interactionId); };

    await ToolService.prototype.finishInteraction.call({ offlineBrowser: service }, 'request-11', '11');
    assert.deepEqual(firstCalls, ['request-11'], 'cleanup must be delegated through HybridBrowserService to tab 11 offline browser state');
    assert.deepEqual(secondCalls, [], 'cleanup for one tab must not reset another tab browser');

    await ToolService.prototype.finishInteraction.call({ offlineBrowser: service }, 'request-22', '22');
    assert.deepEqual(firstCalls, ['request-11']);
    assert.deepEqual(secondCalls, ['request-22'], 'cleanup must route by browserId for background/inactive tabs too');

    const countBeforeMissing = service.sessions.size;
    await ToolService.prototype.finishInteraction.call({ offlineBrowser: service }, 'missing', '999');
    assert.equal(service.sessions.size, countBeforeMissing, 'cleanup for an already-released tab must not recreate a browser session');

    await service.destroy();
});

test('renderer and IPC route browser ownership by tab id on every switch and ignore stale tab browser updates', () => {
    const tabsSource = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'tabs.js'), 'utf8');
    const projectsSource = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'projects.js'), 'utf8');
    const browserSource = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'offline-browser.js'), 'utf8');
    const preloadSource = fs.readFileSync(path.join(ROOT, 'backend', 'shell', 'preload.js'), 'utf8');
    const toolSource = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'nodes', 'builtin', 'sampler.js'), 'utf8');

    assert.match(tabsSource, /activeTabId\s*=\s*tabId[\s\S]*?activateOfflineBrowserForTab\(tabId\)/u,
        'ordinary tab switches must activate that tab browser');
    assert.match(projectsSource, /activeTabId\s*=\s*selected\.id[\s\S]*?activateOfflineBrowserForTab\(activeTabId\)/u,
        'project switches must activate the selected tab browser');
    assert.match(preloadSource, /OFFLINE_BROWSER_ACTIVATE[\s\S]*?browserId/u,
        'preload must expose browser-session activation with an explicit tab/browser id');
    assert.ok(browserSource.includes("if (next.browserId !== undefined && String(next.browserId) !== currentBrowserId) return;"),
        'renderer must reject a status update from a browser belonging to a tab that is no longer active');
    assert.ok(browserSource.includes("if (frame.browserId !== undefined && String(frame.browserId) !== activeBrowserId()) return;"),
        'renderer must reject a stale online-browser frame from another tab');
    assert.match(toolSource, /browserId:\s*String\(context\.tabId/u,
        'background model/browser tools must be routed to the generation tab rather than whichever tab is currently visible');
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/persistence-primitives-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/persistence-primitives-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const test = require('node:test');

const {
    HEADER_BYTES,
    decodeBinaryEnvelope,
    encodeBinaryEnvelope,
    encodeBinaryEnvelopeAsync,
    hasEnvelopeMagic,
} = require('../../persistence/binary-envelope');
const { writeFileAtomic, writeFileAtomicSync } = require('../../persistence/atomic-file');

function envelopeOptions(overrides = {}) {
    return {
        magic: 'TESTDATA',
        maxEnvelopeBytes: String(1024 * 1024),
        maxSerializedBytes: String(1024 * 1024),
        invalidEnvelopeMessage: 'invalid envelope',
        envelopeLoadTooLargeMessage: 'envelope too large',
        serializedTooLargeMessage: 'serialized too large',
        envelopeTooLargeMessage: 'envelope too large',
        unsupportedVersionMessage: (version) => `unsupported version ${version}`,
        unsupportedEncodingMessage: 'unsupported encoding',
        invalidPayloadLengthMessage: 'invalid payload length',
        integrityFailureMessage: 'integrity failure',
        payloadTooLargeMessage: 'payload too large',
        ...overrides,
    };
}

test('binary persistence envelope normalizes validated option values before encoding', () => {
    const payload = Buffer.from('normalized-options-roundtrip', 'utf8');
    const options = envelopeOptions();
    const encoded = encodeBinaryEnvelope(payload, options);

    assert.equal(encoded.subarray(0, 8).toString('utf8'), 'TESTDATA');
    assert.equal(hasEnvelopeMagic(encoded, options), true);
    assert.deepEqual(decodeBinaryEnvelope(encoded, options), payload);
});

test('binary persistence envelope async encoding shares the exact sync wire format contract', async () => {
    const payload = Buffer.from('async-envelope', 'utf8');
    const options = envelopeOptions();
    const encoded = await encodeBinaryEnvelopeAsync(payload, options);

    assert.ok(encoded.length > HEADER_BYTES);
    assert.deepEqual(decodeBinaryEnvelope(encoded, options), payload);
});

test('binary persistence envelope rejects payload corruption before decompression', () => {
    const options = envelopeOptions();
    const encoded = encodeBinaryEnvelope(Buffer.from('integrity-sensitive', 'utf8'), options);
    const corrupted = Buffer.from(encoded);
    corrupted[corrupted.length - 1] ^= 0xff;

    assert.throws(() => decodeBinaryEnvelope(corrupted, options), /integrity failure/u);
});

test('atomic persistence replaces the destination without leaving sibling temporary files', (t) => {
    const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-atomic-file-'));
    t.after(() => fs.rmSync(directory, { recursive: true, force: true }));
    const destination = path.join(directory, 'session.bin');
    fs.writeFileSync(destination, 'old', 'utf8');

    const result = writeFileAtomicSync(destination, Buffer.from('new', 'utf8'));

    assert.equal(result, destination);
    assert.equal(fs.readFileSync(destination, 'utf8'), 'new');
    assert.deepEqual(fs.readdirSync(directory), ['session.bin']);
    if (process.platform !== 'win32') {
        assert.equal(fs.statSync(destination).mode & 0o777, 0o600);
    }
});

test('async atomic file replacement shares the crash-safe sibling-temp contract', async () => {
    const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-atomic-async-'));
    const destination = path.join(directory, 'state.bin');
    fs.writeFileSync(destination, 'old', 'utf8');

    const result = await writeFileAtomic(destination, Buffer.from('new-async', 'utf8'));

    assert.equal(result, path.resolve(destination));
    assert.equal(fs.readFileSync(destination, 'utf8'), 'new-async');
    assert.deepEqual(
        fs.readdirSync(directory).filter((name) => name.includes('.tmp-')),
        [],
        'atomic write must not leave sibling temporary files behind',
    );
});
});

