// TEST MODULE: backend/Dev/tests/power-management-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/power-management-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const { EventEmitter } = require('node:events');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const { createMainWindow } = require('../../app/main-window');
const { configureWindowsAppIdentity, createPowerProtection, focusExistingMainWindow } = require('../../app/run-main-app');

const ROOT = path.resolve(__dirname, '..', '..', '..');

class FakeWebContents extends EventEmitter {
    constructor() {
        super();
        this.session = {
            setPermissionCheckHandler() {},
            setPermissionRequestHandler() {},
        };
    }
    setZoomLevel() {}
    setWindowOpenHandler() {}
}

class FakeBrowserWindow extends EventEmitter {
    constructor(options) {
        super();
        FakeBrowserWindow.lastOptions = options;
        this.webContents = new FakeWebContents();
    }
    loadFile() {}
    setMenuBarVisibility() {}
}

test('main renderer explicitly disables Chromium background throttling', () => {
    const window = createMainWindow(FakeBrowserWindow, ROOT, null);
    assert.equal(FakeBrowserWindow.lastOptions.webPreferences.backgroundThrottling, false,
        'Darkstar main renderer must remain unthrottled when Windows locks/occludes the window');
    assert.equal(window.webContents.listenerCount('preload-error'), 1,
        'sandboxed preload failures must be surfaced to the launching terminal');
});

test('Windows process identity uses Darkstar app ID instead of Electron identity', () => {
    const ids = [];
    const app = { setAppUserModelId(id) { ids.push(id); } };
    assert.equal(configureWindowsAppIdentity(app, 'win32'), true);
    assert.deepEqual(ids, ['com.darkstar.chat']);
    assert.equal(configureWindowsAppIdentity(app, 'linux'), false);
    assert.deepEqual(ids, ['com.darkstar.chat'], 'non-Windows platforms must not receive Windows shell identity calls');
});

test('single-instance window handoff restores, shows, and focuses the existing Darkstar window', () => {
    const calls = [];
    const window = {
        isDestroyed: () => false,
        isMinimized: () => true,
        restore: () => calls.push('restore'),
        isVisible: () => false,
        show: () => calls.push('show'),
        focus: () => calls.push('focus'),
    };
    assert.equal(focusExistingMainWindow(window), true);
    assert.deepEqual(calls, ['restore', 'show', 'focus']);
    assert.equal(focusExistingMainWindow({ isDestroyed: () => true }), false,
        'destroyed windows must never be targeted by a second-instance handoff');
});

test('main app acquires Electron single-instance lock before lazy runtime services and focuses the primary on relaunch', () => {
    const source = fs.readFileSync(path.join(ROOT, 'backend', 'app', 'run-main-app.js'), 'utf8');
    const identity = source.indexOf('configureWindowsAppIdentity(app);');
    const lock = source.indexOf('app.requestSingleInstanceLock()');
    const serviceOwner = source.indexOf('const ensureRuntimeServices = () =>');
    const serviceCreation = source.indexOf('services = createRuntimeServices', serviceOwner);
    assert.ok(identity >= 0 && lock > identity && serviceOwner > lock && serviceCreation > serviceOwner,
        'Windows app identity and single-instance ownership must be established before Darkstar can lazily initialize runtime services');
    assert.match(source, /if \(typeof app\.requestSingleInstanceLock === 'function' && !app\.requestSingleInstanceLock\(\)\) \{[\s\S]*?app\.quit\(\);[\s\S]*?return null;/u,
        'secondary launches must quit before constructing another Darkstar app instance');
    assert.match(source, /app\.on\('second-instance', \(\) => \{ focusPrimaryWindow\(\); \}\);/u,
        'a second launch must hand focus back to the primary Darkstar window');
});

test('application power guard requests prevent-app-suspension exactly once and releases it on shutdown', () => {
    const starts = [];
    const stops = [];
    const active = new Set();
    let nextId = 40;
    const blocker = {
        start(type) {
            starts.push(type);
            const id = ++nextId;
            active.add(id);
            return id;
        },
        isStarted(id) { return active.has(id); },
        stop(id) {
            stops.push(id);
            active.delete(id);
        },
    };
    const guard = createPowerProtection(blocker, { log() {}, warn() {} });

    assert.equal(guard.start(), 41);
    assert.equal(guard.start(), 41, 'repeated startup must not create duplicate OS power requests');
    assert.deepEqual(starts, ['prevent-app-suspension']);
    assert.equal(guard.id, 41);

    guard.stop();
    guard.stop();
    assert.deepEqual(stops, [41], 'shutdown must release the blocker exactly once');
    assert.equal(guard.id, null);
});

test('power protection starts with the main application handoff and stops on quit without preventing display sleep', () => {
    const source = fs.readFileSync(path.join(ROOT, 'backend', 'app', 'run-main-app.js'), 'utf8');
    const startOwner = source.indexOf('const startMainApplication = () => {');
    const start = source.indexOf('powerProtection.start();', startOwner);
    const register = source.indexOf('registerIpc();', startOwner);
    const windowOpen = source.indexOf('openMainWindow();', startOwner);
    assert.ok(startOwner >= 0 && start > startOwner && register > start && windowOpen > register,
        'power protection must activate before IPC/runtime startup and main-window work');
    assert.match(source, /app\.on\('will-quit', \(\) => powerProtection\.stop\(\)\)/u);
    assert.doesNotMatch(source, /prevent-display-sleep/u,
        'Darkstar should not keep the monitor awake; only application suspension should be blocked');
});
});

