// TEST MODULE: backend/Dev/tests/process-utils-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/process-utils-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const { EventEmitter } = require('node:events');
const { PassThrough } = require('node:stream');
const test = require('node:test');
const { runProcessCapture } = require('../../runtime/process-utils');

function fakeChild(onInput) {
    const child = new EventEmitter();
    child.stdout = new PassThrough();
    child.stderr = new PassThrough();
    child.stdin = new PassThrough();
    child.killCalls = [];
    child.kill = (signal) => { child.killCalls.push(signal); };
    let input = '';
    child.stdin.setEncoding('utf8');
    child.stdin.on('data', (chunk) => { input += chunk; });
    child.stdin.on('finish', () => onInput?.(input));
    return child;
}

test('runProcessCapture owns injected spawn, stdin, and captured output in one process contract', async () => {
    let spawnCall = null;
    let receivedInput = null;
    const child = fakeChild((input) => { receivedInput = input; });
    const promise = runProcessCapture('helper.exe', ['--json'], {
        spawn(executable, args, options) {
            spawnCall = { executable, args, options };
            return child;
        },
        input: '{"ok":true}',
        env: { DARKSTAR_TEST: '1' },
        timeoutMs: 1000,
    });
    child.stdout.write('answer');
    child.stderr.write('detail');
    child.stdout.end();
    child.stderr.end();
    child.emit('close', 0, null);
    const result = await promise;
    await new Promise((resolve) => setImmediate(resolve));

    assert.equal(spawnCall.executable, 'helper.exe');
    assert.deepEqual(spawnCall.args, ['--json']);
    assert.deepEqual(spawnCall.options.stdio, ['pipe', 'pipe', 'pipe']);
    assert.equal(spawnCall.options.shell, false);
    assert.equal(receivedInput, '{"ok":true}');
    assert.deepEqual(result, { status: 0, signal: null, stdout: 'answer', stderr: 'detail' });
});

test('runProcessCapture returns a typed timeout and terminates exactly once', async () => {
    const child = fakeChild();
    const keepAlive = setTimeout(() => {}, 50);
    try {
        await assert.rejects(
            runProcessCapture('slow.exe', [], {
                spawn: () => child,
                timeoutMs: 5,
                timeoutMessage: 'custom timeout',
                killSignal: null,
            }),
            (error) => error?.code === 'ETIMEDOUT' && error.message === 'custom timeout',
        );
    } finally {
        clearTimeout(keepAlive);
    }
    assert.deepEqual(child.killCalls, [undefined]);
});


test('runProcessCapture bounds combined stdout and stderr memory', async () => {
    const child = fakeChild();
    const promise = runProcessCapture('noisy.exe', [], {
        spawn: () => child,
        maxOutputBytes: 5,
        killSignal: null,
    });
    child.stdout.write('1234');
    child.stderr.write('56');
    await assert.rejects(promise, (error) => error?.code === 'EOUTPUTLIMIT');
    assert.deepEqual(child.killCalls, [undefined]);
});
});

