test('project rename reaches the real workspace service and physically renames the attached directory', async (t) => {
    const parent = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-project-honest-rename-'));
    t.after(() => fs.rmSync(parent, { recursive: true, force: true }));
    const originalRoot = path.join(parent, 'Qwen3.8Bench');
    fs.mkdirSync(originalRoot);
    fs.writeFileSync(path.join(originalRoot, 'proof.txt'), 'workspace contents survive project rename', 'utf8');

    const registry = new WorkspaceRegistry();
    t.after(() => registry.close());
    const initialRoot = await registry.setRoot('project-0', originalRoot);
    const { context } = createContext();
    context.darkstar = { workspace: {
        renameEntry: async (workspaceId, relativePath, newName) => {
            try {
                const entry = await registry.renameEntry(workspaceId, relativePath, newName);
                return { success: true, workspaceId, entry, root: registry.describeRoot(workspaceId) };
            } catch (error) {
                return { success: false, error: error.message };
            }
        },
        listDirectory: async (workspaceId, relativePath) => {
            try {
                const entries = await registry.listDirectory(workspaceId, relativePath);
                return { success: true, workspaceId, entries, root: registry.describeRoot(workspaceId) };
            } catch (error) {
                return { success: false, error: error.message, entries: [] };
            }
        }
    } };
    evaluate(context, `
        projects[0].title = 'Qwen3.8Bench';
        workspaceStateForProject(0).root = ${JSON.stringify(initialRoot)};
        workspaceStateForProject(0).expandedDirectories.add('');
        scheduleChatSessionSave = function() {};
    `);

    assert.equal(await evaluate(context, `renameProject(0, 'Benchmark')`), true);

    const renamedRoot = path.join(parent, 'Benchmark');
    assert.equal(fs.existsSync(originalRoot), false, 'the old physical workspace directory must no longer exist');
    assert.equal(fs.existsSync(renamedRoot), true, 'the renamed physical workspace directory must exist');
    assert.equal(fs.readFileSync(path.join(renamedRoot, 'proof.txt'), 'utf8'), 'workspace contents survive project rename');
    assert.equal(registry.getRoot('project-0'), fs.realpathSync(renamedRoot));
    assert.equal(evaluate(context, 'projects[0].title'), 'Benchmark');
    assert.equal(evaluate(context, 'getProjectWorkspaceName(0)'), 'Benchmark');
    assert.equal(evaluate(context, 'getProjectWorkspaceRoot(0)'), fs.realpathSync(renamedRoot));
});

