// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/python-environment-sanitization-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const test = require('node:test');

const { sanitizedEnvironment, sanitizedPythonEnvironment } = require('../../agent/safe-environment');
const { providerEnvironment } = require('../../agent/python-command');

test('Python environment sanitization has one canonical owner for secrets and interpreter overrides', () => {
    const source = {
        PATH: '/bin',
        PYTHONHOME: '/unsafe/home',
        pythonpath: '/unsafe/path',
        OPENAI_API_KEY: 'secret',
        SAFE_VALUE: 42,
    };

    assert.deepEqual(sanitizedEnvironment(source), {
        PATH: '/bin',
        PYTHONHOME: '/unsafe/home',
        pythonpath: '/unsafe/path',
        SAFE_VALUE: '42',
    });
    assert.deepEqual(sanitizedPythonEnvironment(source), {
        PATH: '/bin',
        SAFE_VALUE: '42',
    });
});

test('Python provider environment cannot reintroduce PYTHONHOME or PYTHONPATH through overrides', () => {
    const environment = providerEnvironment({
        PYTHONHOME: '/override/home',
        PyThOnPaTh: '/override/path',
        DARKSTAR_TEST_VALUE: 'present',
        GITHUB_TOKEN: 'must-not-leak',
    });

    assert.equal(environment.PYTHONHOME, undefined);
    assert.equal(environment.PyThOnPaTh, undefined);
    assert.equal(environment.DARKSTAR_TEST_VALUE, 'present');
    assert.equal(environment.GITHUB_TOKEN, undefined);
    assert.equal(environment.PYTHONUNBUFFERED, '1');
    assert.equal(environment.PYTHONDONTWRITEBYTECODE, '1');
});
});

