// TEST MODULE: backend/Dev/tests/quantum-reset-graph-button-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/quantum-reset-graph-button-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const styles = fs.readFileSync(path.resolve(__dirname, '..', '..', 'shell', 'styles.css'), 'utf8');

function ruleBody(selector) {
    const escaped = selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = styles.match(new RegExp(escaped + '\\s*\\{([^}]*)\\}', 'u'));
    assert.ok(match, 'missing CSS rule: ' + selector);
    return match[1];
}

test('Quantum Reset Graph toolbar button uses an opaque panel background', () => {
    const base = ruleBody("html[data-theme='quantum'] .toolbar-btn");
    const hover = ruleBody("html[data-theme='quantum'] .toolbar-btn:hover");
    assert.match(base, /background:\s*var\(--theme-panel-soft\)/u);
    assert.match(base, /border-color:\s*var\(--theme-border\)/u);
    assert.match(hover, /background:\s*var\(--theme-panel-hover\)/u);
    assert.equal(base.includes('rgba(255,255,255,0.04)'), false, 'Quantum must not use the transparent legacy toolbar surface');
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/reasoning-context-continuity.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/reasoning-context-continuity.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const { normalizeChatRequest, normalizeMessage } = require('../../runtime/chat-request');
const { streamAgent } = require('../../runtime/agent-loop');
const { performChatCompletion } = require('../../runtime/chat-completion');

const ROOT = path.resolve(__dirname, '..', '..', '..');

function fakeToolCall() {
    return {
        id: 'call_reasoning_continuity',
        type: 'function',
        function: { name: 'continuity_tool', arguments: '{"value":1}' },
    };
}

function fakeAgentRuntime(turns, capturedBodies) {
    let completionIndex = 0;
    return {
        server: { config: { contextSize: 32768 } },
        normalizeChatRequest(request) {
            return normalizeChatRequest(request, 'test-model');
        },
        async performChatCompletion(body) {
            capturedBodies.push(structuredClone(body));
            const next = turns[completionIndex++];
            if (!next) throw new Error('Unexpected extra model round.');
            return structuredClone(next);
        },
        toolService: {
            async buildRuntime() {
                return {
                    definitions: [{
                        type: 'function',
                        function: {
                            name: 'continuity_tool',
                            description: 'Return a small deterministic result.',
                            parameters: {
                                type: 'object',
                                properties: { value: { type: 'integer' } },
                                required: ['value'],
                            },
                        },
                    }],
                    handlers: new Map([['continuity_tool', {}]]),
                    skills: [],
                    catalog: '',
                    toolChoice: 'auto',
                    maxRounds: 4,
                };
            },
            describeCall(call) {
                return {
                    name: String(call?.function?.name || ''),
                    rawArguments: String(call?.function?.arguments || ''),
                    arguments: { value: 1 },
                    displayCommand: 'continuity_tool({"value":1})',
                };
            },
            async execute() {
                return {
                    result: '{"success":true,"value":1}',
                    rawResult: { success: true, value: 1 },
                    contextMessages: [],
                    durationMs: 1,
                };
            },
        },
    };
}

test('chat request normalization preserves assistant reasoning_content without moving it into visible content', () => {
    const normalized = normalizeMessage({
        role: 'assistant',
        content: 'visible answer',
        reasoning_content: 'private structured reasoning',
        tool_calls: [fakeToolCall()],
    });

    assert.equal(normalized.content, 'visible answer');
    assert.equal(normalized.reasoning_content, 'private structured reasoning');
    assert.equal(normalized.tool_calls.length, 1);
    assert.doesNotMatch(normalized.content, /private structured reasoning/u);
});

test('legacy reasoning aliases are canonicalized to llama.cpp reasoning_content only for assistant messages', () => {
    assert.equal(normalizeMessage({ role: 'assistant', content: '', reasoning: 'legacy reasoning' }).reasoning_content, 'legacy reasoning');
    assert.equal(normalizeMessage({ role: 'assistant', content: '', thinking: 'legacy thinking' }).reasoning_content, 'legacy thinking');
    assert.equal(normalizeMessage({ role: 'assistant', content: '', analysis: 'legacy analysis' }).reasoning_content, 'legacy analysis');
    assert.equal(Object.hasOwn(normalizeMessage({ role: 'assistant', content: 'plain' }), 'reasoning_content'), false);
    assert.equal(Object.hasOwn(normalizeMessage({ role: 'user', content: 'user', reasoning_content: 'must not propagate' }), 'reasoning_content'), false);
});

test('reasoning_content survives the final chat transport body sent to llama.cpp', async () => {
    let postedBody = null;
    await performChatCompletion({
        body: {
            model: 'test-model',
            messages: [{
                role: 'assistant',
                content: null,
                reasoning_content: 'transport-preserved reasoning',
                tool_calls: [fakeToolCall()],
            }],
            stream: true,
        },
        fetchImpl: async (_url, options) => {
            postedBody = JSON.parse(options.body);
            return { ok: true };
        },
        host: '127.0.0.1',
        port: 8080,
        signal: new AbortController().signal,
        handlers: {},
        consumeChatCompletionStream: async () => ({ text: '', reasoning: '', toolCalls: [] }),
    });

    assert.equal(postedBody.messages[0].reasoning_content, 'transport-preserved reasoning');
    assert.equal(postedBody.messages[0].content, null);
    assert.equal(postedBody.messages[0].tool_calls[0].id, 'call_reasoning_continuity');
});

test('agent tool round carries exact prior reasoning into the next model request and persisted tool context', async () => {
    const firstReasoning = 'Plan A. Keep the exact implementation decisions already made before calling the tool.\nSecond line.';
    const secondReasoning = 'Continue from Plan A using the returned tool value.';
    const capturedBodies = [];
    const toolContextEvents = [];
    const runtime = fakeAgentRuntime([
        {
            text: '',
            reasoning: firstReasoning,
            toolCalls: [fakeToolCall()],
            usage: null,
            contextUsage: null,
            finishReason: 'tool_calls',
        },
        {
            text: 'Finished without replanning.',
            reasoning: secondReasoning,
            toolCalls: [],
            usage: null,
            contextUsage: null,
            finishReason: 'stop',
        },
    ], capturedBodies);

    const result = await streamAgent(runtime, {
        model: 'test-model',
        messages: [{ role: 'user', content: 'Do the task.' }],
        tools: { providers: ['test'], toolChoice: 'auto' },
        control: { reasoning: 'auto' },
    }, new AbortController(), {
        onToolContext(payload) {
            if (payload?.type === 'tool-context') toolContextEvents.push(...payload.messages);
        },
    }, 'reasoning-continuity-test');

    assert.equal(capturedBodies.length, 2, 'one tool round must produce exactly two model requests');

    const secondAssistant = capturedBodies[1].messages.find((message) => message?.role === 'assistant' && Array.isArray(message.tool_calls));
    assert.ok(secondAssistant, 'second model request must contain the assistant tool-call turn');
    assert.equal(secondAssistant.reasoning_content, firstReasoning);
    assert.equal(secondAssistant.content, null);
    assert.equal(secondAssistant.tool_calls[0].id, 'call_reasoning_continuity');

    const toolResultIndex = capturedBodies[1].messages.findIndex((message) => message?.role === 'tool' && message.tool_call_id === 'call_reasoning_continuity');
    const assistantIndex = capturedBodies[1].messages.indexOf(secondAssistant);
    assert.ok(assistantIndex >= 0 && toolResultIndex > assistantIndex, 'reasoning-bearing assistant turn must remain immediately before its tool result in protocol order');

    const persistedAssistant = toolContextEvents.find((message) => message?.role === 'assistant' && Array.isArray(message.tool_calls));
    assert.ok(persistedAssistant, 'tool context must persist the assistant tool-call turn');
    assert.equal(persistedAssistant.reasoning_content, firstReasoning);

    assert.equal(result.text, 'Finished without replanning.');
    assert.equal(result.reasoning, firstReasoning + secondReasoning);
    assert.equal(result.toolRounds, 1);
});

test('agent tool round does not add a reasoning field when the model emitted none', async () => {
    const capturedBodies = [];
    const runtime = fakeAgentRuntime([
        {
            text: 'Calling tool.',
            reasoning: '',
            toolCalls: [fakeToolCall()],
            usage: null,
            contextUsage: null,
            finishReason: 'tool_calls',
        },
        {
            text: 'Done.',
            reasoning: '',
            toolCalls: [],
            usage: null,
            contextUsage: null,
            finishReason: 'stop',
        },
    ], capturedBodies);

    await streamAgent(runtime, {
        model: 'test-model',
        messages: [{ role: 'user', content: 'Do the task without reasoning.' }],
        tools: { providers: ['test'], toolChoice: 'auto' },
        control: { reasoning: 'off' },
    }, new AbortController(), {}, 'no-reasoning-continuity-test');

    const secondAssistant = capturedBodies[1].messages.find((message) => message?.role === 'assistant' && Array.isArray(message.tool_calls));
    assert.ok(secondAssistant);
    assert.equal(Object.hasOwn(secondAssistant, 'reasoning_content'), false);
});

function loadContextNodeDefinition() {
    const source = fs.readFileSync(path.join(ROOT, 'backend', 'renderer', 'nodes', 'builtin', 'context.js'), 'utf8');
    let registered = null;
    const sandbox = {
        console,
        Darkstar: {
            imageData: {
                safeDataUrl(image, fallbackMimeType) {
                    const mimeType = String(image && image.mimeType || fallbackMimeType || 'image/png');
                    const base64 = String(image && image.base64 || '');
                    return base64 ? `data:${mimeType};base64,${base64}` : '';
                },
            },
            nodes: {
                builtinCommon: { baseNode: () => ({}) },
                controls: { textarea: () => '', booleanSelect: () => '', status: () => '' },
                PORT_TYPES: { MODEL: 'model', TEXT: 'text', IMAGE: 'image' },
                registerNode(definition) { registered = definition; },
            },
        },
    };
    sandbox.globalThis = sandbox;
    vm.runInNewContext(source, sandbox, { filename: 'context.js' });
    assert.ok(registered, 'Context node must register itself');
    return registered;
}

test('Context node emits text and images together through one Context output', () => {
    const definition = loadContextNodeDefinition();
    const node = { params: { includeHistory: true, systemPrompt: '' }, status: '', statusMessage: '' };
    assert.equal(definition.inputs.length, 0);
    const result = definition.execute({}, node, {
        history: [{ role: 'user', content: 'Describe this image', images: [{ base64: 'QUJD', mimeType: 'image/png', name: 'sample.png' }] }],
    });
    assert.deepEqual(Object.keys(result), ['context']);
    assert.equal(result.context.length, 1);
    assert.equal(result.context[0].role, 'user');
    assert.equal(result.context[0].content[0].type, 'text');
    assert.equal(result.context[0].content[0].text, 'Describe this image');
    assert.equal(result.context[0].content[1].type, 'image_url');
    assert.equal(result.context[0].content[1].image_url.url, 'data:image/png;base64,QUJD');
});

test('Context node rehydrates every persisted reasoning round exactly once into future request history', () => {
    const definition = loadContextNodeDefinition();
    const toolReasoning = 'Reasoning persisted from the original tool-call round.';
    const finalReasoning = 'Final reasoning after the tool result.';
    const node = { params: { includeHistory: true, systemPrompt: '' }, status: '', statusMessage: '' };
    const result = definition.execute({ model: { multimodal: false } }, node, {
        history: [
            { id: 'u1', role: 'user', content: 'Original request' },
            {
                id: 'a1',
                role: 'assistant',
                content: 'Original final answer',
                reasoning: toolReasoning + finalReasoning,
                agentTimeline: [
                    { id: 'reasoning-1', type: 'reasoning', round: 1, content: toolReasoning },
                    { id: 'tool-call-1', type: 'tool-call', toolCallId: 'call_reasoning_continuity' },
                    { id: 'worked-1', type: 'worked', toolCallId: 'call_reasoning_continuity' },
                    { id: 'reasoning-2', type: 'reasoning', round: 2, content: finalReasoning },
                ],
                toolContext: [
                    {
                        role: 'assistant',
                        content: null,
                        reasoning_content: toolReasoning,
                        tool_calls: [fakeToolCall()],
                    },
                    {
                        role: 'tool',
                        tool_call_id: 'call_reasoning_continuity',
                        name: 'continuity_tool',
                        content: '{"success":true,"value":1}',
                    },
                ],
            },
            { id: 'u2', role: 'user', content: 'Continue.' },
        ],
    });

    const assistantToolTurn = result.context.find((message) => message?.role === 'assistant' && Array.isArray(message.tool_calls));
    assert.ok(assistantToolTurn);
    assert.equal(assistantToolTurn.reasoning_content, toolReasoning);
    assert.equal(assistantToolTurn.content, null);

    const visibleAssistant = result.context.find((message) => message?.role === 'assistant' && !Array.isArray(message.tool_calls));
    assert.ok(visibleAssistant);
    assert.equal(visibleAssistant.content, 'Original final answer');
    assert.equal(visibleAssistant.reasoning_content, finalReasoning,
        'the final non-tool reasoning tail must survive Retry/history reconstruction without duplicating tool-round reasoning');
});

test('Context node preserves ordinary historical reasoning as well as native continuation reasoning', () => {
    const definition = loadContextNodeDefinition();
    const node = { params: { includeHistory: true, systemPrompt: '' }, status: '', statusMessage: '' };
    const result = definition.execute({ model: { multimodal: false } }, node, {
        continueMessageId: 'a2',
        history: [
            { id: 'u1', role: 'user', content: 'Prompt' },
            { id: 'a1', role: 'assistant', content: 'Older answer', reasoning: 'older private reasoning' },
            { id: 'a2', role: 'assistant', content: '', reasoning: 'unfinished reasoning tail' },
        ],
    });
    const assistants = result.context.filter((message) => message.role === 'assistant');
    assert.equal(assistants.length, 2);
    assert.equal(assistants[0].reasoning_content, 'older private reasoning',
        'ordinary historical reasoning must remain model-facing instead of disappearing when Retry rebuilds context');
    assert.equal(assistants[1].reasoning_content, 'unfinished reasoning tail',
        'native continuation must reconstruct the exact interrupted assistant reasoning prefill');
});



test('deepseek reasoning boundary leakage is removed from final visible content without touching legitimate inline text', () => {
    const { reconcileReasoningBoundaryArtifact } = require(path.join(ROOT, 'backend/runtime/streaming.js'));
    const reasoning = 'structured private reasoning';
    const duplicated = 'I am ready to help.\n</think>\nI am ready to help.';
    assert.equal(reconcileReasoningBoundaryArtifact(duplicated, reasoning), 'I am ready to help.');
    assert.equal(
        reconcileReasoningBoundaryArtifact('final answer\n</think>', reasoning),
        'final answer',
        'if llama.cpp leaks only a terminal delimiter, preserve the visible answer and remove only the delimiter',
    );
    assert.equal(
        reconcileReasoningBoundaryArtifact('Use `</think>` literally in documentation.', reasoning),
        'Use `</think>` literally in documentation.',
        'inline/code-like occurrences are not reasoning-boundary artifacts',
    );
    assert.equal(
        reconcileReasoningBoundaryArtifact('visible\n</think>\nafter', ''),
        'visible\n</think>\nafter',
        'without a structured reasoning channel Darkstar must not reinterpret model content',
    );
});
});

