// TEST MODULE: backend/Dev/tests/reasoning-expanded-autoscroll-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/reasoning-expanded-autoscroll-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const projectRoot = path.resolve(__dirname, '..', '..', '..');
const chat = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'chat.js'), 'utf8');
const styles = fs.readFileSync(path.join(projectRoot, 'backend', 'shell', 'styles.css'), 'utf8');

function loadScrollHelpers() {
    const context = vm.createContext({
        console, URL, setTimeout, clearTimeout,
        getComputedStyle(element) { return { overflowY: String(element && element.overflowY || 'visible') }; },
    });
    vm.runInContext(chat + `\nthis.__reasoningScrollTest = {\n        isAtBottom,\n        nestedScrollableElement,\n        scrollReasoningContentToLatest,\n        shouldAutoFollowExpandedReasoning\n    };`, context, { filename: 'chat.js' });
    return context.__reasoningScrollTest;
}

test('expanded reasoning becomes its own scroll viewport after the height cap', () => {
    const match = styles.match(/\.thinking-block\.expanded \.thinking-content\s*\{([\s\S]*?)\}/m);
    assert.ok(match, 'expanded reasoning CSS block is missing');
    assert.match(match[1], /max-height\s*:\s*2000px\s*;/);
    assert.match(match[1], /overflow-y\s*:\s*auto\s*;/);
});

test('expanded live reasoning follows the bottom only while it was already following', () => {
    const { shouldAutoFollowExpandedReasoning, scrollReasoningContentToLatest } = loadScrollHelpers();
    const viewport = { scrollHeight: 2400, clientHeight: 2000, scrollTop: 400 };
    const block = { querySelector: (selector) => selector === '.thinking-content' ? viewport : null };

    assert.equal(shouldAutoFollowExpandedReasoning(block), true, 'bottom-follow should stay enabled at the bottom');

    viewport.scrollTop = 100;
    assert.equal(shouldAutoFollowExpandedReasoning(block), false, 'manual scroll-up must disable automatic following');

    viewport.scrollTop = 400;
    viewport.scrollHeight = 2600;
    scrollReasoningContentToLatest(block);
    assert.equal(viewport.scrollTop, 600, 'autoscroll must advance to the new bottom');
});

test('reasoning renderer preserves user scroll intent and scrolls immediately on live expansion', () => {
    const renderStart = chat.indexOf('function renderReasoningSegment');
    const renderEnd = chat.indexOf('\nfunction renderImageSegment', renderStart);
    assert.ok(renderStart >= 0 && renderEnd > renderStart, 'renderReasoningSegment not found');
    const renderFn = chat.slice(renderStart, renderEnd);
    assert.match(renderFn, /var followExpandedReasoning = shouldAutoFollowExpandedReasoning\(block\);/);
    assert.match(renderFn, /appendStreamingText\([\s\S]*?if \(followExpandedReasoning\) scrollReasoningContentToLatest\(block\);/);

    const timelineStart = chat.indexOf('function updateMessageAgentTimeline');
    const timelineEnd = chat.indexOf('\nfunction setMessageAgentTimelineState', timelineStart);
    assert.ok(timelineStart >= 0 && timelineEnd > timelineStart, 'updateMessageAgentTimeline not found');
    const timelineFn = chat.slice(timelineStart, timelineEnd);
    assert.match(timelineFn, /expanded === true && segment\.type === 'reasoning'/);
    assert.match(timelineFn, /scrollReasoningContentToLatest\(block\);/);
});

test('chat detaches only for real user-driven upward scrolling and nested trace scrollers retain wheel ownership', () => {
    const { nestedScrollableElement } = loadScrollHelpers();
    const container = { parentElement: null, scrollHeight: 3000, clientHeight: 800, scrollTop: 1200, overflowY: 'auto' };
    const nested = { parentElement: container, scrollHeight: 2000, clientHeight: 500, scrollTop: 300, overflowY: 'auto', nodeType: 1 };
    const child = { parentElement: nested, scrollHeight: 20, clientHeight: 20, scrollTop: 0, overflowY: 'visible', nodeType: 1 };
    assert.equal(nestedScrollableElement(container, child), nested, 'expanded reasoning/tool panes must keep native wheel scrolling');

    const init = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'init.js'), 'utf8');
    assert.match(init, /container\.addEventListener\('scroll'[\s\S]*chatScrollIntentActive\(\)/u);
    assert.match(init, /container\.addEventListener\('pointerdown'[\s\S]*markChatScrollIntent/u);
    assert.match(init, /document\.addEventListener\('keydown'[\s\S]*PageUp[\s\S]*Home/u);
    assert.match(init, /nestedScrollableElement\(this, e\.target\)[\s\S]*nestedCanScroll[\s\S]*e\.stopPropagation\(\); return;/u);
    assert.match(init, /nestedMax[\s\S]*scrollTop[\s\S]*deltaY/u, 'nested scrollers should yield wheel ownership to chat at their own edge');

    const wheelStart = init.indexOf("container.addEventListener('wheel'");
    const wheelEnd = init.indexOf('const queue = document.getElementById', wheelStart);
    assert.ok(wheelStart >= 0 && wheelEnd > wheelStart, 'chat wheel handler not found');
    const chatWheel = init.slice(wheelStart, wheelEnd);
    assert.doesNotMatch(chatWheel, /preventDefault\(/u, 'chat wheel input must remain on Chromium native scrolling');
    assert.doesNotMatch(chatWheel, /animate(?:Queue)?Scroll\(/u, 'chat wheel input must not be replayed through JavaScript easing');
    assert.match(chatWheel, /passive:\s*true/u, 'chat wheel observation should remain passive');
});

test('follow-mode chat autoscroll never reads scrollHeight on the streamed hot path', () => {
    let scrollHeightReads = 0;
    const container = {
        clientHeight: 500,
        scrollTop: 0,
        get scrollHeight() { scrollHeightReads += 1; return 1000; },
    };
    const context = vm.createContext({
        console, URL, setTimeout, clearTimeout,
        userScrolledUp: false,
        getActiveTab() { return { userScrolledUp: false }; },
        document: { getElementById(id) { return id === 'chatContainer' ? container : null; } },
    });
    vm.runInContext(chat + `\nthis.__smartScrollTest = { smartScrollToBottom };`, context, { filename: 'chat.js' });

    context.__smartScrollTest.smartScrollToBottom();
    assert.equal(scrollHeightReads, 0,
        'normal streamed follow mode must not synchronously measure the growing chat document');
    assert.ok(container.scrollTop >= 1000);
});

test('chat smart autoscroll clears stale restored detachment at the physical bottom but preserves real upward detachment', () => {
    const tab = { userScrolledUp: true };
    const container = { scrollHeight: 1000, scrollTop: 500, clientHeight: 500 };
    const context = vm.createContext({
        console, URL, setTimeout, clearTimeout,
        userScrolledUp: true,
        getActiveTab() { return tab; },
        document: { getElementById(id) { return id === 'chatContainer' ? container : null; } },
    });
    vm.runInContext(chat + `\nthis.__smartScrollTest = { smartScrollToBottom, setSmartChatAutoscrollDetached };`, context, { filename: 'chat.js' });

    context.__smartScrollTest.smartScrollToBottom();
    assert.equal(context.userScrolledUp, false);
    assert.equal(tab.userScrolledUp, false);
    assert.ok(container.scrollTop >= container.scrollHeight, 'follow mode must request a position at or beyond the physical bottom without a synchronous height read');

    container.scrollTop = 300;
    context.__smartScrollTest.setSmartChatAutoscrollDetached(true);
    context.__smartScrollTest.smartScrollToBottom();
    assert.equal(context.userScrolledUp, true, 'a genuinely scrolled-up viewport must stay detached');
    assert.equal(container.scrollTop, 300);

    const init = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'init.js'), 'utf8');
    assert.match(init, /container\.scrollTop = container\.scrollHeight;\s*if \(typeof resumeSmartChatAutoscroll === 'function'\) resumeSmartChatAutoscroll\(\);/u);
    assert.match(init, /container\.addEventListener\('scroll'[\s\S]*isAtBottom\(this\)[\s\S]*resumeSmartChatAutoscroll\(\)/u,
        'native chat scrolling must still resume smart autoscroll when the viewport reaches the physical bottom');
});
});

