// TEST MODULE: backend/Dev/tests/reasoning-expanded-whitespace-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/reasoning-expanded-whitespace-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const projectRoot = path.resolve(__dirname, '..', '..', '..');
const styles = fs.readFileSync(path.join(projectRoot, 'backend', 'shell', 'styles.css'), 'utf8');
const chat = fs.readFileSync(path.join(projectRoot, 'backend', 'renderer', 'chat.js'), 'utf8');

function cssBlock(selector) {
    const escaped = selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = styles.match(new RegExp(escaped + '\\s*\\{([\\s\\S]*?)\\}', 'm'));
    assert.ok(match, `missing CSS block: ${selector}`);
    return match[1];
}

test('live reasoning preview and expanded content preserve raw whitespace identically', () => {
    const preview = cssBlock('.thinking-preview');
    const expanded = cssBlock('.thinking-content-inner');
    assert.match(preview, /white-space\s*:\s*pre-wrap\s*;/);
    assert.match(expanded, /white-space\s*:\s*pre-wrap\s*;/);
});

test('active expanded reasoning remains a raw text stream, so CSS must preserve its newlines', () => {
    const start = chat.indexOf('function renderReasoningSegment');
    const end = chat.indexOf('\nfunction renderImageSegment', start);
    assert.ok(start >= 0 && end > start, 'renderReasoningSegment not found');
    const fn = chat.slice(start, end);
    assert.match(fn, /if \(active\)[\s\S]*appendStreamingText\(\s*content,\s*segment\.content/);
    assert.match(fn, /content\.innerHTML = formatMessage\(block\._latestReasoningContent \|\| ''\)/);
    assert.doesNotMatch(fn, /contextTruncation|truncationSpans/u);
});

test('fix leaves disclosure and streaming control flow unchanged', () => {
    assert.match(chat, /bindDisclosure\(block, 'thinking', scrollReasoningPreviewToLatest\)/);
    assert.match(chat, /setDisclosureState\(block, 'thinking', segment\.state, segment\.status\)/);
});
});

