// TEST MODULE: backend/Dev/tests/regression-inventory-completeness.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/regression-inventory-completeness.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const root = path.resolve(__dirname, '..', '..', '..');
const featureInventory = fs.readFileSync(path.join(__dirname, 'every-feature-regression.test.js'), 'utf8');
const staticInventory = fs.readFileSync(path.join(__dirname, 'every-static-button-regression.test.js'), 'utf8');
const dynamicInventory = fs.readFileSync(path.join(__dirname, 'every-dynamic-control-regression.test.js'), 'utf8');
const staticExecutionInventory = fs.readFileSync(path.join(__dirname, 'every-static-button-execution-regression.test.js'), 'utf8');
const delegatedExecutionInventory = fs.readFileSync(path.join(__dirname, 'delegated-static-button-execution-regression.test.js'), 'utf8');
const html = fs.readFileSync(path.join(root, 'backend', 'shell', 'index.html'), 'utf8');

function jsFiles(relativeDir, predicate = () => true) {
    const base = path.join(root, relativeDir);
    const out = [];
    function walk(directory) {
        for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
            const absolute = path.join(directory, entry.name);
            if (entry.isDirectory()) walk(absolute);
            else if (entry.isFile() && entry.name.endsWith('.js')) {
                const relative = path.relative(root, absolute).split(path.sep).join('/');
                if (predicate(relative)) out.push(relative);
            }
        }
    }
    walk(base);
    return out.sort();
}

function actionableRendererFiles() {
    const patterns = [
        /addEventListener\s*\(/u,
        /\.onclick\s*=/u,
        /createElement\(['"]button['"]\)/u,
        /<button\b/u,
        /role=['"]button['"]/u,
    ];
    return jsFiles('backend/renderer').filter((file) => {
        const source = fs.readFileSync(path.join(root, file), 'utf8');
        return patterns.some((pattern) => pattern.test(source));
    });
}

test('completeness: every renderer JavaScript module has an explicit feature regression contract', () => {
    const files = jsFiles('backend/renderer');
    assert.equal(files.length, 70, 'renderer source inventory changed; add regression coverage for the new/removed module');
    for (const file of files) {
        assert.ok(featureInventory.includes(`'${file}'`), `${file} has no explicit feature regression contract`);
    }
});

test('completeness: every first-party backend JavaScript module has an explicit feature regression contract', () => {
    const files = jsFiles('backend', (file) => !file.includes('/python_vendor/') && !file.startsWith('backend/renderer/') && !file.startsWith('backend/scripts/') && !file.startsWith('backend/vendor/') && !file.startsWith('backend/Dev/'));
    assert.equal(files.length, 128, 'backend source inventory changed; add regression coverage for the new/removed module');
    for (const file of files) {
        assert.ok(featureInventory.includes(`'${file}'`), `${file} has no explicit feature regression contract`);
    }
});

test('completeness: every built-in node module is explicitly represented in the feature inventory', () => {
    const files = jsFiles('backend/renderer/nodes/builtin');
    assert.equal(files.length, 9, 'built-in node inventory changed; its tests must change in the same edit');
    for (const file of files) {
        assert.ok(featureInventory.includes(`'${file}'`), `${file} is missing from the feature inventory`);
    }
});

test('completeness: every renderer module that creates or listens to actionable UI is covered', () => {
    const files = actionableRendererFiles();
    assert.equal(files.length, 35, 'actionable renderer file inventory changed; add direct control tests for the changed surface');
    const allControlTests = staticInventory + '\n' + dynamicInventory + '\n' + staticExecutionInventory + '\n' + delegatedExecutionInventory + '\n' + featureInventory;
    for (const file of files) {
        assert.ok(allControlTests.includes(`'${file}'`), `${file} exposes UI actions but is absent from the exhaustive regression layer`);
    }
});

test('completeness: static button count and external wiring are mechanically locked', () => {
    const buttons = html.match(/<button\b[^>]*>[\s\S]*?<\/button>/gu) || [];
    const inline = buttons.filter((button) => /\bonclick=/u.test((button.match(/^<button\b[^>]*>/u) || [''])[0]));
    assert.equal(buttons.length, 64);
    assert.equal(inline.length, 0);
    assert.ok(staticInventory.includes('all 64 current static buttons'));
    assert.ok(staticExecutionInventory.includes('static HTML contains no executable inline event attributes'));
    assert.ok(delegatedExecutionInventory.includes('workspace Choose Directory invokes chooser'));
    assert.ok(delegatedExecutionInventory.includes('UIP Connect application opens the picker'));
    assert.ok(delegatedExecutionInventory.includes('UIP picker Close hides the picker'));
});

test('completeness: dynamic actionable-family inventory is locked to the current 60 families', () => {
    assert.ok(dynamicInventory.includes('assert.equal(contracts.length, 60)'));
    const body = dynamicInventory.split('const contracts = [', 2)[1].split('\n];', 1)[0];
    const declared = body.split('\n').filter((line) => line.trimStart().startsWith("['")).length;
    assert.equal(declared, 60, 'dynamic control manifest changed without updating its completeness contract');
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/runtime-icon-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/runtime-icon-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const test = require('node:test');
const { EventEmitter } = require('node:events');
const {
    WINDOWS_ICON_SIZES,
    encodeIco,
    generateRuntimeIcon,
    runtimeIconPath,
    sourceIconPath,
} = require('../../app/runtime-icon');
const { DARKSTAR_APP_USER_MODEL_ID, createMainWindow } = require('../../app/main-window');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const PNG_SIGNATURE = Buffer.from('89504e470d0a1a0a', 'hex');

function fakePng(size) {
    const body = Buffer.alloc(8, size & 0xff);
    return Buffer.concat([PNG_SIGNATURE, body]);
}

function fakeNativeImage() {
    const resizeCalls = [];
    return {
        resizeCalls,
        createFromPath(filePath) {
            assert.equal(filePath, sourceIconPath(ROOT));
            return {
                isEmpty() { return false; },
                resize(options) {
                    resizeCalls.push({ ...options });
                    return { toPNG: () => fakePng(options.width) };
                },
            };
        },
    };
}

class FakeWebContents extends EventEmitter {
    constructor() {
        super();
        this.session = {
            setPermissionCheckHandler() {},
            setPermissionRequestHandler() {},
        };
    }
    setZoomLevel() {}
    setWindowOpenHandler() {}
}

class FakeBrowserWindow extends EventEmitter {
    constructor(options) {
        super();
        this.webContents = new FakeWebContents();
        FakeBrowserWindow.options = options;
        FakeBrowserWindow.appDetails = null;
    }
    loadFile() {}
    setMenuBarVisibility() {}
    setAppDetails(details) { FakeBrowserWindow.appDetails = { ...details }; }
}

test('runtime icon paths keep the PNG in backend and the generated ICO in app data', () => {
    assert.equal(sourceIconPath(ROOT), path.join(ROOT, 'backend', 'assets', 'icon.png'));
    assert.equal(runtimeIconPath(path.join(ROOT, 'user-data')), path.join(ROOT, 'user-data', 'runtime', 'darkstar.ico'));
    assert.equal(fs.existsSync(path.join(ROOT, 'icon.png')), false);
    assert.equal(fs.existsSync(path.join(ROOT, 'icon.ico')), false);
    assert.equal(fs.existsSync(sourceIconPath(ROOT)), true);
});

test('runtime icon generation renders the canonical seven Windows sizes and writes a valid ICO directory', () => {
    const temp = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-icon-test-'));
    try {
        const outputPath = path.join(temp, 'runtime', 'darkstar.ico');
        const nativeImage = fakeNativeImage();
        assert.equal(generateRuntimeIcon({ nativeImage, sourcePath: sourceIconPath(ROOT), outputPath }), outputPath);
        assert.deepEqual(nativeImage.resizeCalls, WINDOWS_ICON_SIZES.map((size) => ({ width: size, height: size, quality: 'best' })));

        const ico = fs.readFileSync(outputPath);
        assert.equal(ico.readUInt16LE(0), 0);
        assert.equal(ico.readUInt16LE(2), 1);
        assert.equal(ico.readUInt16LE(4), WINDOWS_ICON_SIZES.length);
        WINDOWS_ICON_SIZES.forEach((size, index) => {
            const offset = 6 + (index * 16);
            assert.equal(ico.readUInt8(offset), size === 256 ? 0 : size);
            assert.equal(ico.readUInt8(offset + 1), size === 256 ? 0 : size);
            assert.equal(ico.readUInt16LE(offset + 4), 1);
            assert.equal(ico.readUInt16LE(offset + 6), 32);
            const imageLength = ico.readUInt32LE(offset + 8);
            const imageOffset = ico.readUInt32LE(offset + 12);
            assert.deepEqual(ico.subarray(imageOffset, imageOffset + 8), PNG_SIGNATURE);
            assert.ok(imageLength >= PNG_SIGNATURE.length);
        });
    } finally {
        fs.rmSync(temp, { recursive: true, force: true });
    }
});

test('ICO encoder rejects malformed frames instead of emitting a corrupt runtime icon', () => {
    assert.throws(() => encodeIco([]), /at least one PNG/u);
    assert.throws(() => encodeIco([{ size: 32, png: Buffer.from('not-png') }]), /did not render as PNG/u);
    assert.throws(() => encodeIco([{ size: 257, png: fakePng(1) }]), /Invalid Windows icon size/u);
});

test('main BrowserWindow binds the generated ICO to the Windows taskbar identity explicitly', () => {
    const generated = path.join(ROOT, 'generated', 'darkstar.ico');
    createMainWindow(FakeBrowserWindow, ROOT, null, { iconPath: generated, platform: 'win32' });
    assert.equal(FakeBrowserWindow.options.icon, generated);
    assert.deepEqual(FakeBrowserWindow.appDetails, {
        appId: DARKSTAR_APP_USER_MODEL_ID,
        appIconPath: path.resolve(generated),
        appIconIndex: 0,
    });
});

test('package and renderer reference only the backend PNG source, never a repository ICO', () => {
    const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'backend', 'shell', 'package.json'), 'utf8'));
    const html = fs.readFileSync(path.join(ROOT, 'backend', 'shell', 'index.html'), 'utf8');
    assert.equal(pkg.build?.appId, DARKSTAR_APP_USER_MODEL_ID, 'packaged and runtime Windows identities must remain identical');
    assert.equal(pkg.build?.win?.icon, undefined);
    assert.equal(pkg.build.files.includes('icon.png'), false);
    assert.equal(pkg.build.files.includes('icon.ico'), false);
    assert.match(html, /href="\.\.\/assets\/icon\.png"/u);
    assert.doesNotMatch(html, /href="icon\.png"/u);
});
});

