// TEST MODULE: backend/Dev/tests/shared-boundary-utils-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/shared-boundary-utils-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const test = require('node:test');
const { pathToFileURL } = require('node:url');
const { isExistingPathWithinRootSync, isWithinRoot, portablePath } = require('../../filesystem/path-utils');
const { PluginManager } = require('../../plugins/plugin-manager');
const { OfflineBrowserService } = require('../../browser/offline-browser-service');
const { normalizedDocumentUrl } = require('../../protocol/document-url');

test('filesystem containment rejects sibling-prefix and parent escapes', () => {
    const root = path.resolve('/tmp/darkstar-workspace');
    assert.equal(isWithinRoot(root, root), true);
    assert.equal(isWithinRoot(root, path.join(root, 'nested', 'file.txt')), true);
    assert.equal(isWithinRoot(root, path.resolve(root, '..', 'darkstar-workspace-copy', 'file.txt')), false);
    assert.equal(isWithinRoot(root, path.resolve(root, '..', 'outside.txt')), false);
});


test('existing-path containment resolves symlinks before authorizing access', (t) => {
    const base = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-containment-'));
    t.after(() => fs.rmSync(base, { recursive: true, force: true }));
    const root = path.join(base, 'root');
    const outside = path.join(base, 'outside.txt');
    const link = path.join(root, 'linked.txt');
    fs.mkdirSync(root);
    fs.writeFileSync(outside, 'outside');
    try { fs.symlinkSync(outside, link, 'file'); } catch (error) {
        if (error && ['EPERM', 'EACCES', 'ENOTSUP'].includes(error.code)) return t.skip(`symlinks unavailable: ${error.code}`);
        throw error;
    }
    assert.equal(isWithinRoot(root, link), true, 'lexical containment alone sees the symlink path inside the root');
    assert.equal(isExistingPathWithinRootSync(root, link), false, 'realpath containment rejects the outside target');
});

test('plugin manifests cannot escape their directory through a renderer symlink', (t) => {
    const base = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-plugin-'));
    t.after(() => fs.rmSync(base, { recursive: true, force: true }));
    const pluginDir = path.join(base, 'plugin');
    const outside = path.join(base, 'outside.js');
    const link = path.join(pluginDir, 'renderer.js');
    fs.mkdirSync(pluginDir);
    fs.writeFileSync(outside, 'module.exports = {};\n');
    try { fs.symlinkSync(outside, link, 'file'); } catch (error) {
        if (error && ['EPERM', 'EACCES', 'ENOTSUP'].includes(error.code)) return t.skip(`symlinks unavailable: ${error.code}`);
        throw error;
    }
    const manager = new PluginManager({ baseDir: base, customNodesDirs: [base] });
    assert.throws(() => manager.validateManifest({
        id: 'test.plugin',
        name: 'Test Plugin',
        version: '1.0.0',
        apiVersion: 1,
        renderer: 'renderer.js',
    }, pluginDir), /resolves outside the plugin directory/u);
});


test('offline browser file authorization resolves symlinks before allowing navigation', (t) => {
    const base = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-browser-root-'));
    t.after(() => fs.rmSync(base, { recursive: true, force: true }));
    const root = path.join(base, 'workspace');
    const outside = path.join(base, 'outside.html');
    const inside = path.join(root, 'inside.html');
    const link = path.join(root, 'outside-link.html');
    fs.mkdirSync(root);
    fs.writeFileSync(inside, '<p>inside</p>');
    fs.writeFileSync(outside, '<p>outside</p>');
    try { fs.symlinkSync(outside, link, 'file'); } catch (error) {
        if (error && ['EPERM', 'EACCES', 'ENOTSUP'].includes(error.code)) return t.skip(`symlinks unavailable: ${error.code}`);
        throw error;
    }
    const service = new OfflineBrowserService({ baseDir: base, workspace: { rootPath: root } });
    assert.equal(service._isAllowedFileUrl(pathToFileURL(inside).href), true);
    assert.equal(service._isAllowedFileUrl(pathToFileURL(link).href), false);
});

test('portablePath normalizes platform separators without leaking non-string values', () => {
    assert.equal(portablePath(path.join('folder', 'nested', 'file.txt')), 'folder/nested/file.txt');
    assert.equal(portablePath(null), '');
});

test('trusted document URL normalization ignores query and fragment but preserves document identity', () => {
    assert.equal(
        normalizedDocumentUrl('file:///tmp/index.html?cache=1#section'),
        normalizedDocumentUrl('file:///tmp/index.html?cache=2#other'),
    );
    assert.notEqual(normalizedDocumentUrl('file:///tmp/index.html'), normalizedDocumentUrl('file:///tmp/other.html'));
    assert.equal(normalizedDocumentUrl('not a url'), '');
});

test('manifestless custom-node directories auto-discover visible JavaScript renderers and ignore underscore directories', (t) => {
    const base = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-auto-plugin-'));
    t.after(() => fs.rmSync(base, { recursive: true, force: true }));
    const visible = path.join(base, 'drop-ins');
    const disabled = path.join(base, '_disabled');
    fs.mkdirSync(visible);
    fs.mkdirSync(disabled);
    fs.writeFileSync(path.join(visible, 'hello.js'), '(function(){})();\n');
    fs.writeFileSync(path.join(visible, '_helper.js'), '(function(){})();\n');
    fs.writeFileSync(path.join(disabled, 'hidden.js'), '(function(){})();\n');

    const manager = new PluginManager({ baseDir: base, customNodesDirs: [base] });
    const result = manager.discover();
    assert.deepEqual(result.diagnostics, []);
    assert.equal(result.plugins.length, 1);
    assert.equal(result.plugins[0].id, 'auto.drop-ins.hello');
    assert.equal(result.plugins[0].autoDiscovered, true);
    assert.equal(result.plugins[0].rendererUrl, pathToFileURL(path.join(visible, 'hello.js')).href);
});

test('trusted plugin state survives backend module rediscovery so in-flight operations remain cancellable', async (t) => {
    const base = fs.mkdtempSync(path.join(os.tmpdir(), 'darkstar-plugin-state-'));
    t.after(() => fs.rmSync(base, { recursive: true, force: true }));
    const pluginDir = path.join(base, 'stateful');
    fs.mkdirSync(pluginDir);
    fs.writeFileSync(path.join(pluginDir, 'renderer.js'), '(function(){})();\n');
    fs.writeFileSync(path.join(pluginDir, 'backend.js'), [
        "'use strict';",
        'module.exports = { operations: {',
        '  remember(context, payload) { context.state.value = payload.value; return { value: context.state.value }; },',
        '  recall(context) { return { value: context.state.value || null }; }',
        '} };',
        '',
    ].join('\n'));
    fs.writeFileSync(path.join(pluginDir, 'node.json'), JSON.stringify({
        id: 'test.stateful', name: 'Stateful', version: '1.0.0', apiVersion: 1,
        renderer: 'renderer.js', backend: 'backend.js', permissions: ['backend:trusted'],
    }));

    const manager = new PluginManager({ baseDir: base, customNodesDirs: [base] });
    manager.discover();
    assert.deepEqual(await manager.invoke('test.stateful', 'remember', { value: 'kept' }), { value: 'kept' });
    manager.discover();
    assert.deepEqual(await manager.invoke('test.stateful', 'recall', {}), { value: 'kept' });
});
});

