// TEST MODULE: backend/Dev/tests/sidebar-hit-testing-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/sidebar-hit-testing-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const css = fs.readFileSync(path.resolve(__dirname, '..', '..', 'shell', 'styles.css'), 'utf8');

function rule(selector) {
    const escaped = selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = css.match(new RegExp(`${escaped}\\s*\\{([^}]*)\\}`));
    assert.ok(match, `Missing CSS rule for ${selector}`);
    return match[1];
}

test('Schema sidebar is permanently excluded from the Electron window drag region', () => {
    assert.doesNotMatch(rule('body'), /-webkit-app-region:\s*drag\s*;/);
    assert.match(rule('.title-bar'), /-webkit-app-region:\s*drag\s*;/);
    assert.match(rule('.workspace-sidebar'), /-webkit-app-region:\s*no-drag\s*;/);
});

test('project rows remain clickable even when their DOM element is not a native button', () => {
    assert.match(rule('.schema-project-item'), /-webkit-app-region:\s*no-drag\s*;/);
});
});

