test('/compact is shown immediately as a normal user message, then compacts prior context with a dedicated summary request', async () => {
    const { sandbox, tab, streamed, renderSnapshots } = loadCommands();
    const before = tab.history.length;
    const result = await sandbox.Darkstar.systemCommands.invoke('/compact', { tab, input: { value: '/compact', style: {}, focus() {}, setSelectionRange() {} } });
    assert.equal(result.handled, true);
    assert.equal(result.success, true);
    assert.equal(streamed.length, 1);
    assert.equal(streamed[0].control.reasoning, 'off');
    assert.equal(streamed[0].control.reasoningFormat, 'none');
    assert.equal(streamed[0].tools.providers.length, 0);
    assert.deepEqual(Array.from(streamed[0].messages, (message) => message.role), ['user']);
    assert.match(streamed[0].messages[0].content, /DARKSTAR INTERNAL COMPACTION TASK[\s\S]*COMPACT FILE PROMPT: produce a faithful handoff summary\.[\s\S]*<conversation_to_compact>[\s\S]*<\/conversation_to_compact>/u);
    const compact = compactMessages(tab)[0];
    assert.equal(compact.role, 'system');
    assert.equal(compact.compactRequestedPercentage, 90);
    assert.match(compact.content, /<darkstar_compaction_summary>[\s\S]*HANDOFF SUMMARY/u);
    assert.equal(tab.history[0].id, 'u1', 'the initial user anchor must remain before the summary');
    assert.equal(tab.history[1], compact, 'the summary must sit immediately after the initial user anchor');
    const compactCommand = tab.history.find((message) => message.role === 'user' && message.content === '/compact');
    assert.ok(compactCommand, 'the literal command must remain in visible chat history');
    assert.equal(compactCommand.systemCommand, 'compact');
    assert.equal(compactCommand.excludeFromContext, true, 'command UI evidence must not become model context');
    assert.ok(renderSnapshots.length >= 2, 'chat must render once before compaction and again after the summary lands');
    assert.ok(renderSnapshots[0].some((message) => message.role === 'user' && message.content === '/compact'), 'the command bubble must be rendered before compaction starts');
    assert.ok(tab.history.length <= before, 'compaction may keep its command bubble but must still replace old context');
});

test('compaction streams through a live activity patch and does not publish the COMPACT product until that patch finishes', async () => {
    let resolveStream;
    let streamContext;
    const fixture = loadCommands({
        streamChatImpl(_request, context) {
            streamContext = context;
            return new Promise((resolve) => { resolveStream = resolve; });
        },
    });
    const invocation = fixture.sandbox.Darkstar.systemCommands.invoke('/compact', {
        tab: fixture.tab,
        input: { value: '/compact', style: {}, focus() {}, setSelectionRange() {} },
    });
    await new Promise((resolve) => setImmediate(resolve));

    assert.equal(compactMessages(fixture.tab).length, 0, 'no COMPACT summary may be committed while generation is still streaming');
    assert.ok(fixture.compactionActivities.length === 1, 'a first-class compaction activity must own the visible stream');
    streamContext.onReasoningToken('reason ', 'reason about retained facts');
    streamContext.onToken('summary ', 'summary token one');
    assert.equal(compactMessages(fixture.tab).length, 0, 'streamed summary tokens are transient until completion');
    assert.ok(fixture.lifecycle.some((event) => event.type === 'activity-reasoning'), 'reasoning must be forwarded into the compaction patch');
    assert.ok(fixture.lifecycle.some((event) => event.type === 'activity-token'), 'summary tokens must be forwarded into the compaction patch');

    resolveStream({ text: 'FINAL HANDOFF', reasoning: 'reason about retained facts', usage: null });
    const result = await invocation;
    assert.equal(result.success, true);
    assert.equal(compactMessages(fixture.tab).length, 1);
    const visualFinishedIndex = fixture.lifecycle.findIndex((event) => event.type === 'activity-visual-finished');
    const productRenderIndex = fixture.lifecycle.findIndex((event) => event.type === 'render' && event.hasCompact === true);
    assert.ok(visualFinishedIndex >= 0 && productRenderIndex > visualFinishedIndex, 'the top COMPACT product must render only after the live patch has finished');
});

