test('repeated compaction keeps exactly one summary after the initial system/user anchor and derives the replacement from pre-compaction history', async () => {
    const seededTab = {
        id: 1,
        history: [
            { id: 's1', role: 'system', content: 'INITIAL SYSTEM' },
            { id: 'u1', role: 'user', content: 'INITIAL USER ' + 'x'.repeat(120) },
            { id: 'a1', role: 'assistant', content: 'FIRST ANSWER ' + 'y'.repeat(120) },
            { id: 'u2', role: 'user', content: 'SECOND USER ' + 'z'.repeat(120) },
            { id: 'a2', role: 'assistant', content: 'SECOND ANSWER ' + 'q'.repeat(120) },
        ],
        tokens: 0,
        tokensExact: false,
    };
    const first = loadCommands({ tab: seededTab });
    const firstResult = await first.sandbox.Darkstar.systemCommands.invoke('/compact', { tab: first.tab, input: first.input });
    assert.equal(firstResult.success, true);
    assert.equal(compactMessages(first.tab).length, 1);
    const oldSummary = compactMessages(first.tab)[0];
    assert.equal(first.tab.history[0].id, 's1');
    assert.equal(first.tab.history[1].id, 'u1');
    assert.equal(first.tab.history[2], oldSummary);

    first.tab.history.push({ id: 'u3', role: 'user', content: 'THIRD USER ' + 'r'.repeat(120) });
    first.tab.history.push({ id: 'a3', role: 'assistant', content: 'THIRD ANSWER ' + 't'.repeat(120) });
    const secondResult = await first.sandbox.Darkstar.systemCommands.invoke('/compact', { tab: first.tab, input: first.input });
    assert.equal(secondResult.success, true);
    assert.equal(first.streamed.length, 2);
    assert.match(first.streamed[1].messages[0].content, /HANDOFF SUMMARY/u, 'the old summary must still be visible to the compactioner before replacement');
    assert.equal(compactMessages(first.tab).length, 1, 'compaction history must be a singleton');
    const replacement = compactMessages(first.tab)[0];
    assert.notEqual(replacement, oldSummary);
    assert.equal(first.tab.history[0].id, 's1');
    assert.equal(first.tab.history[1].id, 'u1');
    assert.equal(first.tab.history[2], replacement, 'replacement summary must remain directly after the initial system/user anchor');
});

