test('scheduled dispatch reserves capacity before a generation session exists', async () => {
    const sendCalls = [];
    const resolvers = [];
    const sandbox = {
        console,
        Map, Set, Promise, Math, Number, String, Array, Object, RegExp,
        activeTabId: -1,
        tabs: [
            { id: 1, projectId: 0, scheduled: [{ id: 's1', text: '/compact 50%', image: null, order: 1, tabId: 1 }], generationQueued: false },
            { id: 2, projectId: 0, scheduled: [{ id: 's2', text: '/compact 50%', image: null, order: 2, tabId: 2 }], generationQueued: false },
        ],
        scheduledMessageSequence: 2,
        scheduledDispatchTimer: null,
        scheduledDispatchReservations: new Set(),
        getTabWorkspaceRoot() { return 'C:/SyntheticProject'; },
        generationSessionForTab() { return null; },
        activeGenerationCount() { return 0; },
        configuredParallelSlots() { return 1; },
        generationCapacityAvailable() { return true; },
        isRecognizedSlashCommand(value) { return /^\/(?:adversary|compact|continue)(?:\s|$)/u.test(String(value || '')); },
        scheduleChatSessionSave() {},
        renderQueue() {},
        collapseScheduledQueueUi() {},
        getActiveTab() { return null; },
        pendingQueueCountForTab() { return 0; },
        sendMessage(_regen, options) {
            sendCalls.push(options);
            return new Promise((resolve) => resolvers.push(resolve));
        },
        setTimeout, clearTimeout,
        Darkstar: { imageData: { normalizeSource() { return null; }, safeDataUrl() { return ''; } } },
    };
    sandbox.window = sandbox;
    sandbox.globalThis = sandbox;
    const context = vm.createContext(sandbox);
    vm.runInContext(read('backend/renderer/queue.js'), context, { filename: 'queue.js' });

    assert.equal(sandbox.dispatchNextScheduledMessage(0), true);
    await new Promise((resolve) => setTimeout(resolve, 15));
    assert.equal(sendCalls.length, 1, 'the second scheduled command must wait while the first command owns unresolved capacity');
    assert.equal(sandbox.tabs[1].scheduled.length, 1);
    assert.equal(sandbox.scheduledDispatchReservations.has(1), true);

    resolvers.shift()({ handled: true, success: true });
    await new Promise((resolve) => setTimeout(resolve, 15));
    assert.equal(sendCalls.length, 2, 'capacity release should dispatch the next scheduled command');
    assert.equal(sandbox.scheduledDispatchReservations.has(1), false);
    assert.equal(sandbox.scheduledDispatchReservations.has(2), true);

    resolvers.shift()({ handled: true, success: true });
    await new Promise((resolve) => setTimeout(resolve, 15));
    assert.equal(sandbox.scheduledDispatchReservations.size, 0);
});

test('compaction token cache is namespaced by loaded model identity', async () => {
    const { sandbox } = loadCommands({ exposeInternals: true });
    let modelId = 'model-a.gguf';
    let tokenizations = 0;
    sandbox.darkstar.nodes.getStatus = async () => ({ success: true, loadedModelId: modelId });
    sandbox.darkstar.nodes.tokenizeText = async () => {
        tokenizations += 1;
        const count = modelId === 'model-a.gguf' ? 3 : 7;
        return { success: true, tokens: new Array(count).fill({}) };
    };

    const internals = sandbox.__commandInternals;
    assert.equal(await internals.tokenCountForText('identical transcript'), 3);
    assert.equal(await internals.tokenCountForText('identical transcript'), 3);
    assert.equal(tokenizations, 1, 'same model/text should reuse its cached tokenization');

    modelId = 'model-b.gguf';
    assert.equal(await internals.tokenCountForText('identical transcript'), 7);
    assert.equal(tokenizations, 2, 'switching model must not reuse the previous model tokenizer result');

    sandbox.darkstar.nodes.getStatus = async () => { throw new Error('runtime unavailable'); };
    assert.equal(await internals.tokenCountForText('fallback transcript'), 7, 'status failure should retain approximate/tokenize fallback behavior');
    assert.equal(await internals.tokenCountForText('fallback transcript'), 7);
    assert.equal(tokenizations, 3, 'fallback identity should still memoize repeated text');
});

