test('repeated Auto-compact counts only history that replacement can actually remove', async () => {
    const tab = {
        id: 1,
        history: [
            { id: 'u0', role: 'user', content: 'ANCHOR '.repeat(120) },
            { id: 'c0', role: 'system', content: '<darkstar_compaction_summary>\nOLD HANDOFF '.repeat(80), systemCommand: 'compact', compactedContext: true },
            { id: 'u1', role: 'user', content: 'removable one '.repeat(120) },
            { id: 'a1', role: 'assistant', content: 'answer one '.repeat(120) },
            { id: 'u2', role: 'user', content: 'removable two '.repeat(120) },
            { id: 'a2', role: 'assistant', content: 'answer two '.repeat(120) },
            { id: 'u3', role: 'user', content: 'LATEST '.repeat(20) },
        ],
    };
    const fixture = loadCommands({ tab, autoCompact: true, countedTokens: 950, tokenLimit: 1000, exposeInternals: true });
    const plan = await fixture.sandbox.__commandInternals.compactionPlan(fixture.tab, 50, { protectLatestUser: true });
    assert.ok(plan);
    assert.ok(plan.endIndex > 2, 'the plan must advance into genuinely removable history');
    assert.match(plan.transcript, /OLD HANDOFF/u, 'the previous handoff remains source material for the new summary');
    assert.match(plan.transcript, /removable one/u);
    assert.match(plan.transcript, /ANCHOR/u, 'the preserved first-user anchor remains source material for summary derivation');
    await fixture.sandbox.compactConversation(fixture.tab, 50, { auto: true, protectLatestUser: true });
    assert.equal(fixture.tab.history[0].id, 'u0');
    assert.equal(compactMessages(fixture.tab).length, 1);
    assert.ok(!fixture.tab.history.some((message) => message && message.id === 'u1'), 'selected removable turns must actually leave canonical history');
});

