test('live Auto-compact stops at the first exact sample at or above 90%, for every context size and every overshoot', () => {
    const fixture = loadCommands({ autoCompact: true, tokenLimit: 999999 });
    [257, 1000, 17000, 32768, 65535].forEach((limit) => {
        const firstAtOrAbove = Math.ceil(limit * 0.90);
        assert.equal(fixture.sandbox.liveAutoCompactThresholdReached({ exact: true, current: true, activeContextTokens: firstAtOrAbove - 1, contextSize: limit }), false);
        [firstAtOrAbove, firstAtOrAbove + 1, firstAtOrAbove + 37, firstAtOrAbove + 100, limit, limit + 100].forEach((tokens) => {
            assert.equal(fixture.sandbox.liveAutoCompactThresholdReached({ exact: true, current: true, activeContextTokens: tokens, contextSize: limit }), true,
                `${tokens}/${limit} is at or above 90% and must stop immediately`);
        });
    });
    assert.equal(fixture.sandbox.liveAutoCompactThresholdReached({ exact: true, current: false, activeContextTokens: 999, contextSize: 1000 }), false);
    assert.equal(fixture.sandbox.liveAutoCompactThresholdReached({ exact: false, current: true, activeContextTokens: 999, contextSize: 1000 }), false);
});



