test('Send, Edit, and Retry route registered persisted system commands through one invocation API with no command-name branches', () => {
    const api = read('backend/renderer/system-command-api.js');
    const commands = read('backend/renderer/commands.js');
    const send = read('backend/renderer/send.js');
    const edit = read('backend/renderer/edit.js');
    assert.match(api, /function register\(definition\)/u);
    assert.match(api, /async function invoke\(value, options\)/u);
    assert.match(api, /definition\.persistCommand === true[\s\S]*persistCommandMessage/u);
    assert.match(api, /definition\.concurrency === 'exclusive'[\s\S]*queueInvocation/u);
    assert.match(commands, /systemCommands\.register\(\{[\s\S]*name: 'adversary'[\s\S]*persistCommand: true/u);
    assert.match(commands, /systemCommands\.register\(\{[\s\S]*name: 'compact'[\s\S]*persistCommand: true/u);
    assert.match(send, /Darkstar\.systemCommands\.invoke\(message, \{[\s\S]*origin: options\._fromGenerationQueue === true \? 'queue' : 'composer'/u);
    assert.doesNotMatch(send, /isCompactCommand|\/compact\(\?:\s\|\$\)/u);
    assert.match(edit, /persistedSystemCommandName\(nextContent\)[\s\S]*invokeSystemCommand\(nextContent/u);
    assert.match(edit, /retryableSystemCommand[\s\S]*invokeSystemCommand\(command/u);
    assert.doesNotMatch(edit, /\(compact\|adversary\)|priorCommand === 'compact'|priorCommand === 'adversary'/u);
    assert.match(send, /preflightAutoCompact\(request\)[\s\S]*maybeAutoCompactConversation\(tab, \{ request: request, abortSignal: session\.controller\.signal \}\)/u);
    assert.doesNotMatch(read('backend/renderer/nodes/builtin/sampler.js'), /!adversaryMode\s*&&\s*runtimeControl\.autoCompact/u,
        'adversary requests must use the same exact Auto-compact preflight as ordinary generation');
    assert.doesNotMatch(send, /!adversaryMode\s*&&\s*options\.skipAutoCompact/u,
        'adversary live slot samples must trigger the same >=90% pause as ordinary generation');
    assert.doesNotMatch(commands, /adversaryMode:\s*true,[\s\S]{0,180}skipAutoCompact:\s*true/u,
        'the adversary command must never opt out of Auto-compact');
    var liveThresholdBranch = send.slice(send.indexOf("typeof liveAutoCompactThresholdReached === 'function'"), send.indexOf("if (session.tabId === activeTabId) generationUi.queueTokenCounter()"));
    assert.match(liveThresholdBranch, /liveAutoCompactThresholdReached\(usage\)[\s\S]*session\.autoCompactRequested = true[\s\S]*session\.controller\.abort\(\)/u);
    var postThresholdBranch = send.slice(send.indexOf('if (!session.cancelled && session.autoCompactRequested === true'), send.indexOf('if (!session.cancelled && !session.autoCompactRequested'));
    assert.match(postThresholdBranch, /maybeAutoCompactConversation\(tab, \{[\s\S]*observedTokens: session\.autoCompactObservedTokens/u);
    assert.doesNotMatch(postThresholdBranch.split('maybeAutoCompactConversation')[0], /session\.stoppedMessage\s*&&/u,
        'materializing a stopped message may control resume, never whether >=90% triggers compaction');
    assert.match(postThresholdBranch, /pausedId[\s\S]*continueGeneration\(pausedIndex, \{ targetTabId: tab\.id, source: 'auto-compact' \}\)/u);
    assert.match(commands, /var modelId = await ensureCompactionModelLoaded\(options\)/u);
});

