test('Auto-compact can reclaim completed tool transactions from the protected latest user turn', async () => {
    const active = {
        id: 'active-assistant',
        role: 'assistant',
        content: '',
        interrupted: true,
        continuable: true,
        continuationMode: 'tool',
        partialToolCall: { id: 'partial', function: { name: 'Write', arguments: '{"path":"next"' } },
        toolContext: [
            { role: 'assistant', content: null, tool_calls: [{ id: 'c1', type: 'function', function: { name: 'Read', arguments: '{"path":"one"}' } }] },
            { role: 'tool', tool_call_id: 'c1', name: 'Read', content: 'ONE '.repeat(80) },
            { role: 'assistant', content: null, tool_calls: [{ id: 'c2', type: 'function', function: { name: 'Read', arguments: '{"path":"two"}' } }] },
            { role: 'tool', tool_call_id: 'c2', name: 'Read', content: 'TWO '.repeat(80) },
        ],
        agentTimeline: [{ id: 'visible-old-tool', type: 'tool-call', status: 'complete', content: 'visible timeline remains' }],
    };
    const tab = {
        id: 1,
        history: [
            { id: 'u0', role: 'user', content: 'INITIAL USER' },
            { id: 'old-summary', role: 'system', content: '<darkstar_compaction_summary>\nOLD HANDOFF', systemCommand: 'compact', compactedContext: true },
            { id: 'u1', role: 'user', content: 'CURRENT TASK' },
            active,
        ],
    };
    const fixture = loadCommands({ tab, autoCompact: true, countedTokens: 950, tokenLimit: 1000, exposeInternals: true });
    const plan = await fixture.sandbox.__commandInternals.compactionPlan(fixture.tab, 50, { protectLatestUser: true });
    assert.ok(plan, 'completed tool transactions in the current turn must be reclaimable');
    assert.equal(plan.eligibleTurnCount, 0, 'the latest user turn itself remains protected');
    assert.equal(plan.eligibleToolGroupCount, 2);
    assert.equal(plan.selectedToolGroupCount, 1, '50% of two equal eligible tool transactions should select the oldest one');
    assert.equal(plan.toolContextTrim.removeCount, 2);
    assert.match(plan.transcript, /OLD HANDOFF/u);
    assert.match(plan.transcript, /ONE/u);

    const result = await fixture.sandbox.compactConversation(fixture.tab, 50, { auto: true, protectLatestUser: true });
    assert.equal(result.compacted, true);
    const resumed = fixture.tab.history.find((message) => message && message.id === 'active-assistant');
    assert.ok(resumed, 'the resumable assistant shell must survive compaction');
    assert.equal(resumed.toolContext.length, 2, 'only the selected complete tool transaction leaves model-facing context');
    assert.equal(resumed.toolContext[0].tool_calls[0].id, 'c2');
    assert.equal(resumed.partialToolCall.id, 'partial', 'the exact interrupted tool continuation state must survive');
    assert.equal(resumed.agentTimeline[0].id, 'visible-old-tool', 'visible historical timeline is not erased by context reclamation');
    assert.equal(compactMessages(fixture.tab).length, 1);
});

