// TEST MODULE: backend/Dev/tests/status-view-toggle-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/status-view-toggle-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..', '..', '..');
const source = fs.readFileSync(path.join(root, 'backend', 'renderer', 'views.js'), 'utf8');

function contextFor(active) {
    const settingsView = {
        classList: {
            contains(name) { return name === 'active' && active; },
        },
    };
    const context = {
        document: {
            getElementById(id) { return id === 'settingsView' ? settingsView : null; },
        },
        globalThis: null,
        Promise,
        setTimeout() {},
        clearTimeout() {},
    };
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(source, context, { filename: 'views.js' });
    return context;
}

test('status view button enters Nodes from Chat through the external listener contract', () => {
    const context = contextFor(false);
    const calls = [];
    context.switchView = (view) => calls.push(view);
    context.toggleStatusView();
    assert.deepEqual(calls, ['settings']);
});

test('status view button returns to Chat from Nodes without runtime onclick mutation', () => {
    const context = contextFor(true);
    const calls = [];
    context.switchView = (view) => calls.push(view);
    context.toggleStatusView();
    assert.deepEqual(calls, ['chat']);
    assert.doesNotMatch(source, /setAttribute\(\s*['"]on[a-z]+['"]/iu);
});

test('view behavior is loaded before event listeners bind the Nodes toggle', () => {
    const html = fs.readFileSync(path.join(root, 'backend', 'shell', 'index.html'), 'utf8');
    const viewsIndex = html.indexOf('<script src="../renderer/views.js"></script>');
    const listenersIndex = html.indexOf('<script src="../renderer/event-listeners.js"></script>');
    assert.ok(viewsIndex >= 0 && listenersIndex >= 0);
    assert.ok(viewsIndex < listenersIndex,
        'event-listeners.js eagerly references toggleStatusView and must load after views.js');
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/system-command-api-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/system-command-api-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const read = (file) => fs.readFileSync(path.join(ROOT, file), 'utf8');

function harness(options = {}) {
    const history = [];
    const queued = [];
    const executed = [];
    const input = { value: '/compact', style: {}, focus() {} };
    const tab = { id: 1, history };
    const sandbox = {
        console, Map, Math, Number, String, Array, Object, Promise, RegExp,
        Darkstar: {}, activeTabId: 1,
        document: { getElementById(id) { return id === 'messageInput' ? input : null; } },
        getActiveTab() { return tab; },
        generationSessionForTab() { return options.active ? { tabId: 1, cancelled: false } : null; },
        enqueueScheduledMessage(target, text, image) { const entry = { tabId: target.id, text, image }; queued.push(entry); return entry; },
        ensureMessageIdentity(message) { message.id = message.id || `m${history.length + 1}`; return message.id; },
        appendHistoryMessage(target, message) { sandbox.ensureMessageIdentity(message); target.history.push(message); return message; },
        renderChat() {}, renderQueue() {}, updateTokenCounter() {}, updateScheduleButton() {}, scheduleChatSessionSave() {},
    };
    sandbox.globalThis = sandbox;
    vm.createContext(sandbox);
    vm.runInContext(read('backend/renderer/system-command-api.js'), sandbox, { filename: 'system-command-api.js' });
    const api = sandbox.Darkstar.systemCommands;
    api.register({
        name: 'compact', usage: '/compact [text]', persistCommand: true, concurrency: 'exclusive',
        parseArguments(text) { return { instruction: String(text || '') }; },
        async execute(context) { executed.push({ name: context.name, args: context.args, historyLength: context.tab.history.length }); return { success: true }; },
    });
    api.register({
        name: 'adversary', usage: '/adversary [text]', persistCommand: true, concurrency: 'exclusive',
        parseArguments(text) { return { instruction: String(text || '') }; },
        async execute(context) { executed.push({ name: context.name, args: context.args, historyLength: context.tab.history.length }); return { success: true }; },
    });
    return { sandbox, api, tab, input, history, queued, executed };
}

test('system-command API owns registration, parsing, persistence, and execution for compact and adversary', async () => {
    const fixture = harness();
    const compact = await fixture.api.invoke('/compact preserve flowers', { tab: fixture.tab, input: fixture.input, clearComposer: false });
    assert.equal(compact.success, true);
    assert.deepEqual(fixture.executed[0], { name: 'compact', args: { instruction: 'preserve flowers' }, historyLength: 1 });
    assert.equal(fixture.history[0].systemCommand, 'compact');
    assert.equal(fixture.history[0].excludeFromContext, true);

    const adversary = await fixture.api.invoke('/adversary inspect boundaries', { tab: fixture.tab, clearComposer: false });
    assert.equal(adversary.success, true);
    assert.deepEqual(fixture.executed[1], { name: 'adversary', args: { instruction: 'inspect boundaries' }, historyLength: 2 });
    assert.equal(fixture.history[1].systemCommand, 'adversary');
});

test('persisted command invocation never duplicates an edited or retried command bubble', async () => {
    const fixture = harness();
    fixture.history.push({ id: 'existing', role: 'user', content: '/compact', systemCommand: 'compact', excludeFromContext: true });
    const result = await fixture.api.invoke('/compact', { tab: fixture.tab, clearComposer: false, messageAlreadyPersisted: true, origin: 'retry' });
    assert.equal(result.success, true);
    assert.equal(fixture.history.length, 1);
    assert.equal(fixture.executed.length, 1);
});

test('exclusive registered commands queue through the API before persistence when their conversation is generating', async () => {
    const fixture = harness({ active: true });
    const result = await fixture.api.invoke('/adversary later', { tab: fixture.tab, input: fixture.input, clearComposer: false });
    assert.equal(result.scheduled, true);
    assert.equal(fixture.executed.length, 0);
    assert.equal(fixture.history.length, 0, 'queued command must not be persisted until it actually dispatches');
    assert.deepEqual(fixture.queued, [{ tabId: 1, text: '/adversary later', image: null }]);
});

test('unknown slash text is not commandeered by the system-command API', async () => {
    const fixture = harness();
    assert.equal(fixture.api.parse('/not-a-command'), null);
    const result = await fixture.api.invoke('/not-a-command', { tab: fixture.tab });
    assert.equal(result.handled, false);
    assert.equal(fixture.history.length, 0);
});

test('renderer callers use the command API rather than command-name-specific dispatch branches', () => {
    const send = read('backend/renderer/send.js');
    const edit = read('backend/renderer/edit.js');
    const commands = read('backend/renderer/commands.js');
    const html = read('backend/shell/index.html');
    assert.match(html, /system-command-api\.js[\s\S]*send\.js[\s\S]*commands\.js/u);
    assert.match(send, /Darkstar\.systemCommands\.invoke\(message/u);
    assert.doesNotMatch(send, /isCompactCommand|isAdversaryCommand/u);
    assert.match(edit, /persistedSystemCommandName/u);
    assert.doesNotMatch(edit, /\(compact\|adversary\)|priorCommand === 'compact'|priorCommand === 'adversary'/u);
    assert.match(commands, /name: 'compact'[\s\S]*name: 'adversary'|name: 'adversary'[\s\S]*name: 'compact'/u);
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/tab-selection-visual-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/tab-selection-visual-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const root = path.resolve(__dirname, '..', '..', '..');
const css = fs.readFileSync(path.join(root, 'backend', 'shell', 'styles.css'), 'utf8');

function rule(selector) {
    const escaped = selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = css.match(new RegExp(`${escaped}\\s*\\{([^}]*)\\}`));
    assert.ok(match, `Missing CSS rule for ${selector}`);
    return match[1];
}

test('chat tabs use a VS Code-style editor-tab hierarchy', () => {
    const bar = rule('.tab-bar');
    const tab = rule('.tab-item');
    const active = rule('.tab-item.active');
    const marker = rule('.tab-item.active::after');
    const delimiter = rule('.tab-delimiter');
    const closeHover = rule('.tab-item .tab-close:hover');
    const themedActive = rule("html[data-theme]:not([data-theme='quantum']) .tab-item.active");
    const themedMarker = rule("html[data-theme]:not([data-theme='quantum']) .tab-item.active::after");

    assert.match(bar, /background:\s*var\(--bg-secondary\)\s*;/u,
        'the tab strip must read as a distinct editor-tab surface');
    assert.match(tab, /height:\s*100%\s*;/u);
    assert.match(tab, /border-radius:\s*0\s*;/u,
        'editor tabs stay rectangular rather than becoming pills or cards');
    assert.match(tab, /background:\s*transparent\s*;/u,
        'inactive tabs inherit the strip surface');

    assert.match(active, /background:\s*var\(--bg-tertiary\)\s*;/u,
        'the active tab must use the raised editor-tab surface above the strip');
    assert.match(active, /box-shadow:\s*\n?\s*inset/u,
        'active tabs may use only inset edge definition');
    assert.doesNotMatch(active, /linear-gradient|\b0\s+\d+px\s+\d+px/u,
        'active tabs must not regain raised-card gradients or external shadows');

    assert.match(marker, /left:\s*0\s*;/u);
    assert.match(marker, /right:\s*0\s*;/u);
    assert.match(marker, /top:\s*0\s*;/u,
        'selection is indicated at the top edge like an editor tab, not by a bottom underline');
    assert.match(marker, /height:\s*2px\s*;/u);
    assert.match(marker, /theme-blue/u,
        'selection uses the theme editor accent while orange stays available for generation state');
    assert.doesNotMatch(marker, /bottom:\s*0/u);

    assert.match(delimiter, /height:\s*100%\s*;/u,
        'tab boundaries remain crisp full-height hairlines');
    assert.match(delimiter, /align-self:\s*stretch\s*;/u);

    assert.doesNotMatch(closeHover, /error|239\s*,\s*68\s*,\s*68|f3a3a3/iu,
        'closing affordances should use neutral editor chrome, not destructive-red hover styling');

    assert.match(themedActive, /background:\s*var\(--bg-tertiary\)\s*;/u,
        'theme overrides must preserve the raised editor-tab surface for the active tab');
    assert.match(themedMarker, /background:\s*var\(--theme-blue\)\s*;/u);
    assert.match(rule('.tab-item .tab-generation-state'), /background:\s*var\(--accent-secondary\)\s*;/u,
        'generation activity remains a separate orange/accent signal');
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/test-monolith-separation-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/test-monolith-separation-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const ROOT = path.resolve(__dirname, '..', '..', '..');

test('production JavaScript and regression tests remain physically separated monoliths', () => {
    const productionMonoliths = [path.join(ROOT, 'backend', 'Darkstar_Core.js'), path.join(ROOT, 'backend', 'Darkstar_Renderer.js')];
    const production = productionMonoliths.map((file) => fs.readFileSync(file, 'utf8')).join('\n');
    const packageJson = JSON.parse(fs.readFileSync(path.join(ROOT, 'backend', 'shell', 'package.json'), 'utf8'));
    assert.doesNotMatch(production, /<DARKSTAR_TEST_BEGIN/u, 'production monolith must never embed test bodies');
    assert.equal(production.includes("require('node:test')"), false, 'production monolith must not carry regression modules');
    assert.equal(packageJson.scripts.test, 'node --test ../Dev/Darkstar_Tests.js');
    assert.equal(Object.hasOwn(packageJson.scripts, 'pretest'), false, 'tests must consume the real split directly');
    assert.equal(Object.hasOwn(packageJson.scripts, 'posttest'), false, 'tests must not need legacy projection cleanup');
    assert.equal(fs.existsSync(path.join(ROOT, 'backend', 'Darkstar.js')), false, 'legacy combined production projection must not return');
    assert.doesNotMatch(production, /__darkstarInstallLogicalSourceOverlay|test-project|test-cleanup/u, 'production must not emulate the retired source layout for development tooling');
    assert.equal(fs.existsSync(path.join(ROOT, 'backend', 'Dev', 'monolith-test-bridge.cjs')), false, 'test bridge must be absorbed by the test monolith');
    assert.equal(fs.existsSync(path.join(ROOT, 'backend', 'Dev', 'tests')), false, 'individual physical test directory must not return');
});
});

// ============================================================================
// TEST MODULE: backend/Dev/tests/tool-call-recovery-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/tool-call-recovery-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const { streamAgent } = require('../../runtime/agent-loop');
const { classifyToolArgumentsJson } = require('../../runtime/tool-call-state');

const ROOT = path.resolve(__dirname, '..', '..', '..');

test('tool preparation tracks only the current live call and contains no interrupted-call resume seed', () => {
    const source = fs.readFileSync(path.join(ROOT, 'backend', 'runtime', 'tool-preparation-tracker.js'), 'utf8');
    assert.match(source, /function createPreparationTracker\(round, handlers\)/u);
    assert.doesNotMatch(source, /seedCall|resumed|nativePrefix|escapeDepth/u);
});

test('live tool streaming has one canonical full-call representation instead of summary plus partial mirrors', () => {
    const streaming = fs.readFileSync(path.join(ROOT, 'backend', 'runtime', 'streaming.js'), 'utf8');
    const streamState = fs.readFileSync(path.join(ROOT, 'backend', 'runtime', 'tool-call-stream.js'), 'utf8');
    const tracker = fs.readFileSync(path.join(ROOT, 'backend', 'runtime', 'tool-preparation-tracker.js'), 'utf8');
    const apiBackend = fs.readFileSync(path.join(ROOT, 'custom_nodes', 'api-model', 'backend.js'), 'utf8');
    assert.doesNotMatch(streaming, /partialCalls|summarizeToolCalls/u);
    assert.doesNotMatch(streamState, /summarizeToolCalls/u);
    assert.doesNotMatch(tracker, /payload\?\.partialCalls/u);
    assert.doesNotMatch(apiBackend, /toolCallSummary/u);
    assert.match(streaming, /onToolCallDelta\(\{ calls: toolCalls \}\)/u,
        'the synchronous preparation tracker should receive the canonical live Map');
    assert.doesNotMatch(streaming, /onToolCallDelta\(\{ calls: snapshotToolCalls\(toolCalls\) \}\)/u,
        'streaming tool arguments must not allocate a full snapshot wrapper on every delta');
    assert.match(tracker, /source instanceof Map/u, 'the preparation tracker must accept the canonical live Map');
});

test('tool preparation tracker consumes the live Map without changing emitted preparation semantics', () => {
    const { createPreparationTracker } = require('../../runtime/tool-preparation-tracker');
    const events = [];
    const tracker = createPreparationTracker(3, { onToolEvent(event) { events.push(event); } });
    tracker.update({ calls: new Map([[0, { index: 0, id: 'call-1', function: { name: 'replace_file', arguments: '{\"path\":\"game.js\"}' } }]]) });
    tracker.finish();
    const preparation = events.find((event) => event && event.type === 'preparing' && event.preparation);
    assert.ok(preparation, 'live Map update should emit normal preparation state');
    assert.equal(preparation.preparation.toolCallId, 'call-1');
    assert.equal(preparation.preparation.name, 'replace_file');
    assert.equal(preparation.preparation.argumentChars, '{\"path\":\"game.js\"}'.length);
});

function toolRuntime(overrides = {}) {
    let executed = 0;
    const runtime = {
        server: { port: 8080, config: { contextSize: 160000, parallel: 1 } },
        processMode: 'legacy',
        loadedModelId: 'model.gguf',
        normalizeChatRequest(request) {
            return {
                model: String(request.model || 'model.gguf'),
                messages: structuredClone(request.messages || []),
                stream: true,
                reasoning_format: 'auto',
            };
        },
        toolService: {
            hasApplicationInterfaceTargets() { return false; },
            async buildRuntime() {
                return {
                    definitions: [{ type: 'function', function: { name: 'replace_file', description: 'replace', parameters: { type: 'object' } } }],
                    handlers: new Map(), catalog: '', toolChoice: 'auto', maxRounds: null,
                };
            },
            describeCall(call) {
                return { name: call.function.name, rawArguments: call.function.arguments, arguments: JSON.parse(call.function.arguments), displayCommand: call.function.name };
            },
            async execute() { executed += 1; return { result: 'ok', rawResult: {}, contextMessages: [], durationMs: 1 }; },
        },
        async performChatCompletion() { return { text: 'done', reasoning: '', toolCalls: [], usage: null, contextUsage: null }; },
        ...overrides,
    };
    runtime.executedCount = () => executed;
    return runtime;
}

function request() {
    return {
        model: 'model.gguf', messages: [{ role: 'user', content: 'edit game.js' }],
        tools: { providers: [{ path: 'provider' }], toolChoice: 'auto' }, skills: { skills: [] }, control: {},
    };
}

test('tool argument state classification is template-independent JSON validation', () => {
    assert.equal(classifyToolArgumentsJson('{"path":"game.js"}'), 'complete');
    assert.equal(classifyToolArgumentsJson('{"path":"game.js"'), 'incomplete');
    assert.equal(classifyToolArgumentsJson('<parameter=path>game.js</parameter>'), 'invalid');
});

test('Stop during tool-argument streaming preserves partial state only for interruption cleanup', async () => {
    const exact = '{"path":"game.js","content":"const x = 1;';
    const runtime = toolRuntime({
        async performChatCompletion(_body, _signal, handlers) {
            handlers.onToolCallDelta?.({
                calls: [{ index: 0, id: 'call_same', type: 'function', function: { name: 'replace_file', arguments: exact } }],
            });
            const error = new Error('Generation stopped.'); error.name = 'AbortError'; throw error;
        },
    });

    await assert.rejects(() => streamAgent(runtime, request(), new AbortController(), {}), (error) => {
        assert.equal(error.name, 'AbortError');
        assert.equal(error.partialAgentState.partialToolCall.id, 'call_same');
        assert.equal(error.partialAgentState.partialToolCall.function.arguments, exact);
        return true;
    });
});

test('incomplete parsed tool calls are discarded and retried fresh without template reconstruction', async () => {
    const bodies = [];
    const toolEvents = [];
    const runtime = toolRuntime({
        async performChatCompletion(body) {
            bodies.push(structuredClone(body));
            if (bodies.length === 1) {
                return {
                    text: 'I will edit it.', reasoning: 'planning', usage: null, contextUsage: null,
                    toolCalls: [{ id: 'broken', type: 'function', function: { name: 'replace_file', arguments: '{"path":"game.js","content":"partial' } }],
                };
            }
            return { text: 'Recovered without replaying the malformed call.', reasoning: '', toolCalls: [], usage: null, contextUsage: null };
        },
    });

    const result = await streamAgent(runtime, request(), new AbortController(), { onToolEvent: (event) => toolEvents.push(event) });
    assert.equal(result.text, 'Recovered without replaying the malformed call.');
    assert.equal(runtime.executedCount(), 0, 'the incomplete tool must never execute');
    assert.equal(bodies.length, 2);
    assert.equal('generation_prompt' in bodies[1], false, 'fresh recovery must never depend on llama.cpp /apply-template prefill');
    assert.equal(bodies[1].messages.some((message) => Array.isArray(message.tool_calls) && message.tool_calls.some((call) => call.id === 'broken')), false,
        'the malformed tool call must not be replayed into the recovery request');
    assert.match(String(bodies[1].messages.at(-1).content || ''), /Start a fresh call/u);
    const retryEvent = toolEvents.find((event) => event.type === 'tool-call-fresh-retry');
    assert.ok(retryEvent);
    assert.equal(retryEvent.preparationId, 'tool-preparation-1-0', 'fresh retry must identify the obsolete preparation independently of model tool-call syntax');

    const servicesSource = fs.readFileSync(path.join(ROOT, 'backend/renderer/nodes/services.js'), 'utf8');
    const renderer = { console }; renderer.window = renderer; renderer.globalThis = renderer;
    vm.createContext(renderer); vm.runInContext(servicesSource, renderer, { filename: 'services.js' });
    const staleTimeline = [
        { id: 'reasoning', type: 'reasoning', content: 'planning', state: 'complete', status: 'complete' },
        { id: 'stale-tool', type: 'tool-call', preparationId: 'tool-preparation-1-0', toolCallId: 'broken', name: 'replace_file', phase: 'preparing', state: 'error', status: 'error' },
    ];
    assert.equal(renderer.Darkstar.nodes.services.discardFreshRetryPreparation(staleTimeline, retryEvent), true);
    assert.deepEqual(staleTimeline.map((segment) => segment.id), ['reasoning'], 'fresh retry must remove its failed preparation before the replacement attempt starts');
});

test('llama.cpp tool-parser errors use the same bounded fresh retry and never call /apply-template', async () => {
    const bodies = [];
    const runtime = toolRuntime({
        transport: {
            async requestJson() { throw new Error('/apply-template must not be called'); },
        },
        async performChatCompletion(body) {
            bodies.push(structuredClone(body));
            if (bodies.length === 1) {
                const error = new Error('The model produced an incomplete tool-call JSON payload.');
                error.code = 'INVALID_TOOL_ARGUMENTS_JSON';
                throw error;
            }
            return { text: 'fresh retry succeeded', reasoning: '', toolCalls: [], usage: null, contextUsage: null };
        },
    });

    const result = await streamAgent(runtime, request(), new AbortController(), {});
    assert.equal(result.text, 'fresh retry succeeded');
    assert.equal(bodies.length, 2);
    assert.equal('generation_prompt' in bodies[1], false);
    assert.match(String(bodies[1].messages.at(-1).content || ''), /Start a fresh call/u);
});
});

