// ============================================================================
// TEST MODULE: backend/Dev/tests/uip-chromium-security-boundary-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/uip-chromium-security-boundary-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const test = require('node:test');

const {
    executeToolCalls,
    untrustedBrowserToolName,
} = require('../../runtime/agent-loop');

const TOOL = 'UIP_Chromium_Interface_Element';

function toolCall(id, name, args) {
    return {
        id,
        type: 'function',
        function: { name, arguments: JSON.stringify(args || {}) },
    };
}

function fixture(chromiumRawResult) {
    const executed = [];
    const agentRuntime = {
        definitions: [
            { type: 'function', function: { name: TOOL, parameters: { type: 'object' } } },
            { type: 'function', function: { name: 'replace_file', parameters: { type: 'object' } } },
        ],
        handlers: new Map([[TOOL, {}], ['replace_file', {}]]),
        skills: [],
        catalog: '',
        toolChoice: 'auto',
    };
    const runtime = {
        toolService: {
            describeCall(call) {
                return {
                    name: call.function.name,
                    rawArguments: call.function.arguments,
                    arguments: JSON.parse(call.function.arguments || '{}'),
                    displayCommand: call.function.name,
                };
            },
            async execute(executionRuntime, call) {
                assert.equal(executionRuntime.handlers.has(call.function.name), true, `runtime must retain handler for ${call.function.name}`);
                executed.push(call.function.name);
                if (call.function.name === TOOL) {
                    return {
                        result: JSON.stringify(chromiumRawResult),
                        rawResult: structuredClone(chromiumRawResult),
                        contextMessages: [],
                        durationMs: 1,
                    };
                }
                return {
                    result: '{"success":true}',
                    rawResult: { success: true },
                    contextMessages: [],
                    durationMs: 1,
                };
            },
        },
    };
    return { runtime, agentRuntime, executed };
}

async function executePair(rawResult, secondName = 'replace_file') {
    const { runtime, agentRuntime, executed } = fixture(rawResult);
    const workingMessages = [];
    const toolMessages = [];
    const result = await executeToolCalls(runtime, {
        agentRuntime,
        calls: [
            toolCall('chromium', TOOL, { action: 'snapshot', target_id: 'uip-1' }),
            toolCall('second', secondName, secondName === TOOL
                ? { action: 'click', target_id: 'uip-1', ref: 'e1' }
                : { path: 'x.txt', content: 'blocked' }),
        ],
        controller: new AbortController(),
        handlers: {},
        preparations: [],
        toolMessages,
        toolRound: 1,
        working: [],
        workingMessages,
        visionEnabled: false,
        interactionId: 'test',
    });
    return { result, executed, workingMessages, toolMessages };
}

test('UIP Chromium Interface identifies HTTP/HTTPS renderer output as untrusted browser content', () => {
    assert.equal(untrustedBrowserToolName(TOOL, {
        success: true,
        action: 'snapshot',
        pageUrl: 'https://discord.com/channels/1/2',
    }, { action: 'snapshot' }), TOOL);

    assert.equal(untrustedBrowserToolName(TOOL, {
        success: true,
        action: 'snapshot',
        snapshotData: { url: 'http://example.test/' },
    }, { action: 'snapshot' }), TOOL);
});

test('UIP Chromium administrative target listing does not lock local tools by itself', () => {
    assert.equal(untrustedBrowserToolName(TOOL, {
        targets: [{ id: 'page-1', url: 'https://example.com/', title: 'Example' }],
    }, { action: 'list_targets' }), '');
});

test('UIP Chromium snapshot of an online renderer activates a tool-specific capability boundary', async () => {
    const state = await executePair({
        success: true,
        action: 'snapshot',
        targetId: 'uip-1',
        cdpTargetId: 'page-1',
        pageUrl: 'https://example.com/',
        snapshot: '[e1] button "Continue"',
    });

    assert.deepEqual(state.executed, [TOOL], 'a local tool must not run after external online renderer content is observed');
    assert.equal(state.result.browserCompartmentActivated, true);
    assert.equal(state.result.browserCompartmentToolName, TOOL);
    assert.equal(state.result.completedCalls, 1);
    assert.match(String(state.workingMessages.at(-1)?.content || ''), /ONLINE_BROWSER_CAPABILITY_BOUNDARY/u);
});

test('UIP Chromium boundary still allows further calls to the same renderer tool in the agent round', async () => {
    const state = await executePair({
        success: true,
        action: 'snapshot',
        targetId: 'uip-1',
        cdpTargetId: 'page-1',
        pageUrl: 'https://example.com/',
        snapshot: '[e1] button "Continue"',
    }, TOOL);

    assert.deepEqual(state.executed, [TOOL, TOOL]);
    assert.equal(state.result.completedCalls, 2);
    assert.equal(state.result.browserCompartmentToolName, TOOL);
});

test('non-web Electron renderer output does not unnecessarily activate the online-page boundary', async () => {
    const state = await executePair({
        success: true,
        action: 'snapshot',
        targetId: 'uip-electron',
        cdpTargetId: 'page-local',
        appType: 'electron',
        pageUrl: 'file:///C:/Program Files/App/resources/app/index.html',
        snapshot: '[e1] button "Open"',
    });

    assert.deepEqual(state.executed, [TOOL, 'replace_file']);
    assert.equal(state.result.browserCompartmentActivated, false);
    assert.equal(state.result.completedCalls, 2);
});

test('no-CDP Chromium accessibility/input fallback still activates the external-surface security boundary', async () => {
    const state = await executePair({
        success: true,
        action: 'snapshot',
        targetId: 'uip-1',
        appType: 'chromium',
        backend: 'accessibility-input',
        untrustedOnlineSurface: true,
        pageUrl: '',
        snapshot: '[e1] textbox "Message @ExampleUser"',
    });

    assert.deepEqual(state.executed, [TOOL]);
    assert.equal(state.result.browserCompartmentActivated, true);
    assert.equal(state.result.browserCompartmentToolName, TOOL);
});

test('Darkstar self-target no-CDP fallback is not misclassified as an online browser surface', async () => {
    const state = await executePair({
        success: true,
        action: 'snapshot',
        targetId: 'uip-self',
        appType: 'electron',
        backend: 'accessibility-input',
        selfTarget: true,
        surfaceTrust: 'local-self',
        untrustedOnlineSurface: false,
        pageUrl: '',
        snapshot: '[e1] textbox "Send a message..."',
    });

    assert.deepEqual(state.executed, [TOOL, 'replace_file']);
    assert.equal(state.result.browserCompartmentActivated, false);
    assert.equal(state.result.completedCalls, 2);
});
});

