// TEST MODULE: backend/Dev/tests/uip-connected-memory-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/uip-connected-memory-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { ConnectedApplicationMemoryController } = require('../../uip/memory-interface');
const { WindowsMemoryBridge } = require('../../uip/windows-memory-bridge');
const { createApplicationInterfaceCapability } = require('../../agent/builtin/uip-tools');
const { UIP_CONNECTED_APPLICATION_MEMORY_DEFINITION } = require('../../agent/builtin/uip-memory-tool');
const { encodeScalar, parseInteger } = require('../../uip/memory-codec');

const root = path.resolve(__dirname, '..', '..', '..');

function target(overrides = {}) {
    return {
        id: 'uip-1', scopeId: 'project-1', title: 'App', ownerPid: 900, primaryHwnd: '1001', appType: 'native', selfTarget: false,
        processes: [
            { pid: 900, name: 'app.exe', path: 'C:\\Apps\\app.exe' },
            { pid: 901, name: 'app-helper.exe', path: 'C:\\Apps\\app-helper.exe' },
        ],
        ...overrides,
    };
}

function createBridge() {
    let mutable = Buffer.alloc(8);
    mutable.writeInt32LE(42, 0);
    const calls = [];
    const bridge = {
        calls,
        setInt32(value) { mutable.writeInt32LE(value, 0); },
        async run(pid, operation, request = {}) {
            calls.push({ pid, operation, request });
            const process = { pid, creationTime: '123456', pointerSize: 8 };
            if (request.expectedCreationTime && request.expectedCreationTime !== process.creationTime) throw new Error('process identity changed');
            if (operation === 'memory_info') return process;
            if (operation === 'memory_modules') return { process, modules: [{ name: 'app.exe', path: 'C:\\Apps\\app.exe', baseAddress: '0x1000', size: 8192 }] };
            if (operation === 'memory_regions') return { process, regions: [{ baseAddress: '0x1000', size: 4096, readable: true, writable: true, executable: false }] };
            if (operation === 'memory_read') return { process, address: request.address, bytesBase64: mutable.subarray(0, request.length).toString('base64'), length: request.length };
            if (operation === 'memory_search') return {
                process, bytesScanned: 4096, truncated: false,
                matches: [
                    { address: '0x2000', bytesBase64: mutable.subarray(0, 4).toString('base64') },
                    { address: '0x3000', bytesBase64: mutable.subarray(0, 4).toString('base64') },
                ],
            };
            if (operation === 'memory_read_many') return {
                process,
                values: request.addresses.map((address) => ({ address, bytesBase64: mutable.subarray(0, request.length).toString('base64'), length: request.length })),
            };
            if (operation === 'memory_write') {
                const before = Buffer.from(mutable.subarray(0, Buffer.from(request.bytesBase64, 'base64').length));
                const next = Buffer.from(request.bytesBase64, 'base64');
                next.copy(mutable, 0);
                return { process, address: request.address, bytesWritten: next.length, beforeBase64: before.toString('base64'), afterBase64: next.toString('base64') };
            }
            if (operation === 'memory_pointer_chain') return { process, finalAddress: '0x5000', steps: [{ readAddress: request.baseAddress, pointerValue: '0x4000', offset: '4096', resultAddress: '0x5000' }] };
            throw new Error(`unexpected operation ${operation}`);
        },
    };
    return bridge;
}


test('memory scalar codec keeps 64-bit/sign semantics exact and rejects ambiguous booleans/non-finite floats', () => {
    assert.equal(parseInteger('-0x20'), -32n);
    assert.equal(parseInteger('+0x20'), 32n);
    assert.equal(encodeScalar('u64', '18446744073709551615').toString('hex'), 'ffffffffffffffff');
    assert.throws(() => encodeScalar('bool', 'yes'), /true, false, 1, or 0/u);
    assert.throws(() => encodeScalar('f64', 'Infinity'), /must be finite/u);
});

test('connected-application memory is a dedicated model tool with bounded introspection and guarded data writes', () => {
    const fn = UIP_CONNECTED_APPLICATION_MEMORY_DEFINITION.function;
    assert.equal(fn.name, 'UIP_Connected_Application_Memory');
    for (const action of ['status', 'list_processes', 'modules', 'regions', 'read', 'search', 'scan_start', 'scan_refine', 'scan_results', 'pointer_chain', 'snapshot', 'diff', 'write']) {
        assert.ok(fn.parameters.properties.action.enum.includes(action), `missing ${action}`);
    }
    assert.match(fn.description, /application already connected/u);
    assert.match(fn.description, /Prefer Chromium\/Electron controls or Windows UI Automation/u);
    assert.match(fn.description, /does not enable debug privilege/u);
    assert.match(fn.description, /write executable pages/u);
    assert.equal(fn.parameters.properties.max_scan_bytes.maximum, 134217728);
    assert.equal(fn.parameters.properties.expected_hex.maxLength, 8192);
});

test('Application Interface exposes memory beside UIA/Chromium only for targets that advertise the capability', () => {
    const service = {
        listTargets: () => [{ id: 'uip-1', appType: 'chromium', capabilities: { chromium: { available: true }, windowsUia: { available: true }, memory: { available: true } } }],
    };
    const capability = createApplicationInterfaceCapability(service, { scopeId: 'project-1' });
    assert.deepEqual(capability.tools.map((entry) => entry.definition.function.name), [
        'UIP_Chromium_Interface_Element', 'UIP_Windows_UI_Automation', 'UIP_Connected_Application_Memory',
    ]);
});


test('Application Interface sidebar renders memory as a third capability badge without changing connection controls', () => {
    const source = fs.readFileSync(path.join(root, 'backend/renderer/uip.js'), 'utf8');
    assert.match(source, /windows-process-memory/u);
    assert.match(source, /Connected Application Memory/u);
    assert.match(source, /\? 'MEM' : 'OFF'/u);
});

test('memory controller never accepts arbitrary PIDs outside the connected target family', async () => {
    const bridge = createBridge();
    const controller = new ConnectedApplicationMemoryController({ platform: 'win32', bridge });
    await assert.rejects(() => controller.control(target(), { action: 'status', process_pid: 999 }), /restricted to the connected application process family/u);
    assert.equal(bridge.calls.length, 0);
    const status = await controller.control(target(), { action: 'status', process_pid: 901 });
    assert.equal(status.pid, 901);
    assert.equal(status.policies.enableDebugPrivilege, false);
    assert.equal(status.policies.executableWrites, false);
});

test('typed reads and module-relative addressing preserve exact process identity', async () => {
    const bridge = createBridge();
    const controller = new ConnectedApplicationMemoryController({ platform: 'win32', bridge });
    const result = await controller.control(target(), { action: 'read', data_type: 'i32', module: 'app.exe', offset: '0x20' });
    assert.equal(result.address, '0x1020');
    assert.equal(result.value, 42);
    const moduleCall = bridge.calls.find((call) => call.operation === 'memory_modules');
    const readCall = bridge.calls.find((call) => call.operation === 'memory_read');
    assert.equal(moduleCall.pid, 900);
    assert.equal(readCall.request.address, '0x1020');
});

test('scalar scan sessions refine changed/equal values and keep model-friendly stable refs', async () => {
    const bridge = createBridge();
    const controller = new ConnectedApplicationMemoryController({ platform: 'win32', bridge });
    const started = await controller.control(target(), { action: 'scan_start', pattern_kind: 'scalar', data_type: 'i32', value: '42', max_scan_bytes: 4096 });
    assert.equal(started.scanId, 's1');
    assert.deepEqual(started.matches.map((entry) => entry.ref), ['m1', 'm2']);
    bridge.setInt32(43);
    const refined = await controller.control(target(), { action: 'scan_refine', scan_id: 's1', data_type: 'i32', compare: 'changed' });
    assert.equal(refined.matchCount, 2);
    assert.deepEqual(refined.matches.map((entry) => entry.value), [43, 43]);
    const results = await controller.control(target(), { action: 'scan_results', scan_id: 's1', result_limit: 1 });
    assert.equal(results.results[0].ref, 'm1');
    const readByRef = await controller.control(target(), { action: 'read', scan_id: 's1', ref: 'm2', data_type: 'i32' });
    assert.equal(readByRef.address, '0x3000');
    assert.equal(readByRef.value, 43);
    const refRead = bridge.calls.filter((call) => call.operation === 'memory_read').at(-1);
    assert.equal(refRead.request.expectedCreationTime, '123456');
});

test('snapshots produce bounded diffs without returning an unbounded raw memory dump', async () => {
    const bridge = createBridge();
    const controller = new ConnectedApplicationMemoryController({ platform: 'win32', bridge });
    const snap = await controller.control(target(), { action: 'snapshot', address: '0x2000', length: 4 });
    assert.equal(snap.snapshotId, 'p1');
    assert.equal(snap.hex, encodeScalar('i32', '42').toString('hex').toUpperCase());
    bridge.setInt32(99);
    const diff = await controller.control(target(), { action: 'diff', snapshot_id: 'p1' });
    assert.equal(diff.changed, true);
    assert.equal(diff.changes[0].address, '0x2000');
    assert.ok(diff.changes[0].length >= 1);
});

test('memory writes require deliberate guards, reject Darkstar self-writes by default, and pass fixed safety intent to the bridge', async () => {
    const bridge = createBridge();
    const controller = new ConnectedApplicationMemoryController({ platform: 'win32', bridge });
    await assert.rejects(() => controller.control(target({ selfTarget: true }), { action: 'write', address: '0x2000', pattern_kind: 'scalar', data_type: 'i32', value: '7', expected_hex: '2A000000' }), /allow_reentrant=true/u);
    await controller.control(target(), { action: 'write', address: '0x2000', pattern_kind: 'scalar', data_type: 'i32', value: '7', expected_hex: '2A000000' });
    const write = bridge.calls.find((call) => call.operation === 'memory_write');
    assert.equal(write.request.allowUnchecked, false);
    assert.equal(Buffer.from(write.request.expectedBase64, 'base64').toString('hex').toUpperCase(), '2A000000');
    assert.equal(Buffer.from(write.request.bytesBase64, 'base64').readInt32LE(0), 7);
});

test('memory bridge fixes PID/operation fields and native source excludes injection, protection changes, and debug privilege escalation', async () => {
    const calls = [];
    const bridge = new WindowsMemoryBridge({ platform: 'win32', runner: { run: async (payload) => { calls.push(payload); return {}; } } });
    await bridge.run(900, 'memory_read', { pid: 999, operation: 'evil', address: '0x1000', length: 4 });
    assert.equal(calls[0].pid, 900);
    assert.equal(calls[0].operation, 'memory_read');

    const source = fs.readFileSync(path.join(root, 'backend/uip/windows-memory.ps1'), 'utf8');
    assert.match(source, /ReadProcessMemory/u);
    assert.match(source, /WriteProcessMemory/u);
    assert.match(source, /VirtualQueryEx/u);
    assert.match(source, /IsWritableNonExecutable/u);
    assert.doesNotMatch(source, /VirtualProtectEx|CreateRemoteThread|NtCreateThreadEx|QueueUserAPC|DebugActiveProcess|SeDebugPrivilege|AdjustTokenPrivileges|WriteProcessMemory\s*\([^\n]*PAGE_EXECUTE/iu);
});
});

