TEST_FACTORIES.set("backend/Dev/tests/uip-legacy-chromium-removal-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { UniversalInterfaceService } = require('../../uip/uip-service');
const { ToolService } = require('../../agent/tool-service');

const root = path.resolve(__dirname, '..', '..', '..');

function minimalService() {
    const target = {
        id: 'uip-1', scopeId: 'project-1', title: 'Brave', ownerPid: 501, primaryHwnd: '7001', appType: 'chromium',
        processes: [{ pid: 501, parentPid: 1, name: 'brave.exe', path: 'C:\\Brave\\brave.exe', commandLine: 'brave.exe --remote-debugging-port=9222' }],
        windows: [{ hwnd: '7001', pid: 501, title: 'Brave', minimized: false, bounds: { x: 0, y: 0, width: 1000, height: 700 } }],
        cdp: { available: true, port: 9222, targets: [] },
    };
    const cdp = {
        probe: async () => ({ available: true, port: 9222, targets: [] }),
        targets: async () => [{ id: 'page-1', type: 'page', title: 'Brave', url: 'https://example.com/', webSocketDebuggerUrl: 'ws://127.0.0.1:9222/devtools/page/1' }],
        send: async (_url, method, params) => method === 'Page.navigate' ? { frameId: 'f1', loaderId: 'l1', url: params.url } : {},
    };
    const service = new UniversalInterfaceService({ platform: 'win32', cdp, bridge: { describeTarget: async () => ({ ownerPid: 501, processes: target.processes, windows: target.windows }) } });
    service.targets.set(target.id, target);
    service.ownerTargets.set('project-1:501', target.id);
    return service;
}

test('obsolete generic uip_control, memory, and native-capture model actions cannot accidentally return', async () => {
    const toolSource = fs.readFileSync(path.join(root, 'backend/agent/builtin/uip-tools.js'), 'utf8');
    const serviceSource = fs.readFileSync(path.join(root, 'backend/uip/uip-service.js'), 'utf8');
    for (const obsolete of ['uip_control', 'uia_inspect', 'uia_action', 'memory_read', 'memory_write', 'memory_scan', 'capture_window', 'chromium_action', 'chromium_targets']) {
        assert.doesNotMatch(toolSource, new RegExp(obsolete, 'u'), `${obsolete} must stay absent from the model tool contract`);
    }
    assert.doesNotMatch(serviceSource, /inspectUia|actUia|MemoryScanSessions|memoryScans|async memory\s*\(|async capture\s*\(/u);
    assert.equal(fs.existsSync(path.join(root, 'backend/uip/memory-sessions.js')), false);
    assert.equal(fs.existsSync(path.join(root, 'backend/uip/windows_native.py')), false);

    const service = minimalService();
    const toolService = new ToolService({ baseDir: root, uipService: service });
    const runtime = await toolService.buildRuntime({ workspaceId: 'project-1', uipScopeId: 'project-1', providers: [] });
    assert.deepEqual(runtime.definitions.map((tool) => tool.function.name), ['UIP_Chromium_Interface_Element']);
    await assert.rejects(
        () => toolService.execute(runtime, { id: 'old', function: { name: 'uip_control', arguments: '{"action":"list_targets"}' } }),
        /Tool is not available in this graph: uip_control/u,
    );
    await toolService.shutdown();
});

test('the Chromium UIP model tool still performs renderer navigation through CDP', async () => {
    const service = minimalService();
    const result = await service.chromiumInterfaceControl('uip-1', { scopeId: 'project-1', action: 'open', url: 'https://example.com/next', snapshot_after: false, wait_ms: 0 });
    assert.equal(result.action, 'open');
    assert.equal(result.url, 'https://example.com/next');
    assert.equal(result.cdpTargetId, 'page-1');
});
});

