test('UIP discovery is exclusive and ordered: Chromium/Electron, UIA, then memory-only processes', async () => {
    const processes = [
        { pid: 41, parentPid: 1, name: 'electron.exe', path: 'C:\\App\\electron.exe', commandLine: 'electron.exe --remote-debugging-port=9222' },
        { pid: 42, parentPid: 41, name: 'electron.exe', path: 'C:\\App\\electron.exe', commandLine: 'electron.exe --type=renderer' },
        { pid: 801, parentPid: 1, name: 'notepad.exe', path: 'C:\\Windows\\notepad.exe', commandLine: 'notepad.exe' },
        { pid: 900, parentPid: 1, name: 'worker.exe', path: 'C:\\App\\worker.exe', commandLine: 'worker.exe' },
    ];
    const descriptions = {
        41: { ownerPid: 41, processes: processes.slice(0, 2), windows: [{ hwnd: '1001', pid: 41, title: 'Electron App', bounds: {} }] },
        801: { ownerPid: 801, processes: [processes[2]], windows: [{ hwnd: '8001', pid: 801, title: 'Notepad', bounds: {} }] },
        900: { ownerPid: 900, processes: [processes[3]], windows: [] },
    };
    const bridge = {
        enumerateWindows: async () => [
            { hwnd: '1001', pid: 42, title: 'Electron App', processName: 'electron.exe', path: 'C:\\App\\electron.exe' },
            { hwnd: '8001', pid: 801, title: 'Notepad', processName: 'notepad.exe', path: 'C:\\Windows\\notepad.exe' },
        ],
        enumerateProcesses: async () => processes,
        describeTarget: async (hwnd) => JSON.parse(JSON.stringify(hwnd === '1001' ? descriptions[41] : descriptions[801])),
        describeProcess: async (pid) => JSON.parse(JSON.stringify(descriptions[pid])),
    };
    const desktopCapturer = { getSources: async () => [{ id: 'window:1001:0', name: 'Electron App', thumbnail: { isEmpty: () => true }, appIcon: image('electron') }] };
    const service = new UniversalInterfaceService({ platform: 'win32', bridge, desktopCapturer, cdp: { probe: async () => ({ available: false }) } });
    const picker = await service.listWindows();
    assert.deepEqual(picker.map((item) => [item.discoveryGroup, item.pid, item.sourceId]), [
        ['electron', 42, 'window:1001:0'],
        ['uia', 801, 'window:8001:0'],
        ['memory', 900, 'process:900'],
    ]);
    assert.equal(picker.filter((item) => item.pid === 41 || item.pid === 42).length, 1, 'Electron process family must appear once, not again under UIA or memory');
    const memoryTarget = await service.attachWindow('process:900', { scopeId: 'project-1' });
    assert.equal(memoryTarget.connectionKind, 'process');
    assert.equal(memoryTarget.capabilities.chromium.detected, false);
    assert.equal(memoryTarget.capabilities.windowsUia.detected, false);
    assert.equal(memoryTarget.capabilities.memory.available, true);
});

