    assert.match(source, /\$pids\.ContainsKey\(\[int\]\$_\.ProcessId\)/u);
    assert.doesNotMatch(source, /\$pids\.Contains\(/u, 'process description must not call Contains on a scalar-collapsible PowerShell return value');
