// TEST MODULE: backend/Dev/tests/workspace-delete-native-modal-regression.test.js
// ============================================================================
TEST_FACTORIES.set("backend/Dev/tests/workspace-delete-native-modal-regression.test.js", function(module, exports, require, __filename, __dirname) {
'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..', '..', '..');
const source = (file) => fs.readFileSync(path.join(root, file), 'utf8');

function classList(initial = []) {
    const values = new Set(initial);
    return {
        add: (...names) => names.forEach((name) => values.add(name)),
        remove: (...names) => names.forEach((name) => values.delete(name)),
        contains: (name) => values.has(name),
    };
}

function modalElement() {
    return {
        classList: classList(),
        attributes: { 'aria-hidden': 'true' },
        setAttribute(name, value) { this.attributes[name] = String(value); },
    };
}

function createContext() {
    const listeners = {};
    const deleteCalls = [];
    const appRoot = {
        inert: false,
        attributes: {},
        hasAttribute(name) { return Object.prototype.hasOwnProperty.call(this.attributes, name); },
        getAttribute(name) { return this.attributes[name] ?? null; },
        setAttribute(name, value) { this.attributes[name] = String(value); },
        removeAttribute(name) { delete this.attributes[name]; },
    };
    const previousFocus = { isConnected: true, focused: 0, focus() { this.focused += 1; } };
    const elements = {
        appRoot,
        workspaceDeleteModal: modalElement(),
        workspaceDeleteModalTitle: { textContent: '' },
        workspaceDeleteModalDescription: { textContent: '' },
        workspaceDeleteCancelButton: { focused: 0, focus() { this.focused += 1; } },
        workspaceDeleteConfirmButton: { textContent: '', focused: 0, focus() { this.focused += 1; } },
    };
    const context = {
        console: { log() {}, warn() {}, error() {} },
        Promise,
        Date,
        Map,
        Set,
        JSON,
        Math,
        Number,
        String,
        Boolean,
        Array,
        Object,
        RegExp,
        activeProjectId: 7,
        document: {
            body: { classList: classList() },
            activeElement: previousFocus,
            getElementById(id) { return elements[id] || null; },
            querySelector(selector) {
                if (selector === '.app-container') return appRoot;
                return null;
            },
            querySelectorAll() { return []; },
            addEventListener(type, handler) {
                if (!listeners[type]) listeners[type] = [];
                listeners[type].push(handler);
            },
            createElement() { return {}; },
        },
        darkstar: {
            workspace: {
                async deleteEntry(workspaceId, relativePath) {
                    deleteCalls.push([workspaceId, relativePath]);
                    return { success: true };
                },
            },
        },
        setTimeout() { return 1; },
        clearTimeout() {},
        setInterval() { return 1; },
        clearInterval() {},
        innerWidth: 1200,
        innerHeight: 800,
    };
    context.window = context;
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(source('backend/renderer/modal-coordinator.js'), context, { filename: 'modal-coordinator.js' });
    vm.runInContext(source('backend/renderer/workspace.js'), context, { filename: 'workspace.js' });
    return { context, elements, deleteCalls, listeners, previousFocus };
}

function evaluate(context, expression) {
    return vm.runInContext(expression, context);
}

test('workspace explorer deletion uses Darkstar modal and never window.confirm', async () => {
    const workspace = source('backend/renderer/workspace.js');
    const html = source('backend/shell/index.html');
    const css = source('backend/shell/styles.css');
    const modalCoordinator = source('backend/renderer/modal-coordinator.js');

    assert.doesNotMatch(workspace, /window\.confirm\s*\(/u);
    assert.match(html, /id="workspaceDeleteModal"[^>]*role="dialog"[^>]*aria-modal="true"/u);
    assert.match(html, /<button\b(?=[^>]*\bid="workspaceDeleteCancelButton")(?=[^>]*\btype="button")[^>]*>/u);
    assert.match(html, /<button\b(?=[^>]*\bid="workspaceDeleteConfirmButton")(?=[^>]*\btype="button")[^>]*>/u);
    const listeners = source('backend/renderer/event-listeners.js');
    assert.match(listeners, /bindClickById\('workspaceDeleteCancelButton', closeWorkspaceDeleteModal\)/u);
    assert.match(listeners, /bindClickById\('workspaceDeleteConfirmButton', confirmWorkspaceDeleteModal\)/u);
    assert.match(css, /body\.workspace-delete-modal-open \.app-container/u);
    assert.match(workspace, /overlayReason:\s*'workspace-delete-modal'/u);
    assert.match(modalCoordinator, /setOfflineBrowserOverlayBlockReason/u);

    const { context, elements, deleteCalls } = createContext();
    const opened = await evaluate(context, `deleteWorkspaceEntry({ kind: 'file', name: 'notes.txt', relativePath: 'docs/notes.txt' })`);
    assert.equal(opened, true);
    assert.equal(deleteCalls.length, 0, 'opening the modal must not delete anything');
    assert.equal(elements.workspaceDeleteModal.classList.contains('active'), true);
    assert.equal(elements.workspaceDeleteModal.attributes['aria-hidden'], 'false');
    assert.equal(elements.workspaceDeleteModalTitle.textContent, 'Delete “notes.txt”?');
    assert.match(elements.workspaceDeleteModalDescription.textContent, /permanently deletes the file/u);
    assert.match(elements.workspaceDeleteModalDescription.textContent, /cannot be undone/u);
    assert.equal(elements.workspaceDeleteConfirmButton.textContent, 'Delete File');

    const deleted = await evaluate(context, 'confirmWorkspaceDeleteModal()');
    assert.equal(deleted, true);
    assert.deepEqual(deleteCalls, [['project-7', 'docs/notes.txt']]);
    assert.equal(elements.workspaceDeleteModal.classList.contains('active'), false);
    assert.equal(elements.workspaceDeleteModal.attributes['aria-hidden'], 'true');
});

test('workspace folder deletion gets folder-specific destructive copy and Escape closes without deleting', async () => {
    const { context, elements, deleteCalls, listeners } = createContext();
    await evaluate(context, `deleteWorkspaceEntry({ kind: 'directory', name: 'build', relativePath: 'build' })`);
    assert.equal(elements.workspaceDeleteConfirmButton.textContent, 'Delete Folder');
    assert.match(elements.workspaceDeleteModalDescription.textContent, /permanently deletes the folder/u);

    const keydown = listeners.keydown && listeners.keydown[listeners.keydown.length - 1];
    assert.equal(typeof keydown, 'function');
    let prevented = 0;
    let stopped = 0;
    keydown({ key: 'Escape', preventDefault() { prevented += 1; }, stopPropagation() { stopped += 1; } });
    assert.equal(prevented, 1);
    assert.equal(stopped, 1);
    assert.equal(elements.workspaceDeleteModal.classList.contains('active'), false);
    assert.equal(deleteCalls.length, 0);
});
});

