TEST_FACTORIES.set("backend/Dev/tests/workspace-sidebar-resize-regression.test.js", function(module, exports, require, __filename, __dirname) {
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const read = rel => fs.readFileSync(path.join(ROOT, rel), 'utf8');

test('workspace sidebar has a bounded native in-app horizontal resize surface', () => {
    const html = read('backend/shell/index.html');
    const css = read('backend/shell/styles.css');
    const workspace = read('backend/renderer/workspace.js');
    assert.match(html, /id="workspaceSidebarResizeHandle"[^>]*title="Resize sidebar"/u);
    assert.match(css, /\.workspace-sidebar-resize-handle \{[\s\S]*?right: 0;[\s\S]*?width: 8px;[\s\S]*?cursor: col-resize;[\s\S]*?touch-action: none;/u);
    assert.match(css, /\.workspace-sidebar\.collapsed \.workspace-sidebar-resize-handle \{[\s\S]*?pointer-events: none;[\s\S]*?visibility: hidden;/u);
    assert.match(workspace, /WORKSPACE_SIDEBAR_MIN_WIDTH = 220/u);
    assert.match(workspace, /WORKSPACE_SIDEBAR_MAX_WIDTH = 420/u);
    assert.match(workspace, /function beginWorkspaceSidebarResize\(event\)[\s\S]*?setPointerCapture[\s\S]*?applyWorkspaceSidebarWidth/u);
    assert.match(workspace, /darkstar\.workspaceSidebar\.width/u);
});

test('workspace sidebar width clamps, persists, and moves the dependent tab/browser layout', () => {
    const values = new Map();
    const rootStyle = {
        values,
        setProperty(name, value) { values.set(name, value); },
        getPropertyValue(name) { return values.get(name) || ''; },
    };
    const sidebar = {
        classList: { contains(name) { return name === 'collapsed' ? false : false; } },
        getBoundingClientRect() {
            const width = Number.parseFloat(values.get('--workspace-sidebar-width')) || 280;
            return { width };
        },
    };
    const tabBar = { style: {} };
    let tabRefreshes = 0;
    let browserRefreshes = 0;
    const context = {
        console, Map, Set, Number, String, Boolean, Array, Object, JSON, Math, RegExp, Promise,
        document: {
            documentElement: { style: rootStyle },
            body: { classList: { add() {}, remove() {} } },
            getElementById(id) {
                if (id === 'workspaceSidebar') return sidebar;
                if (id === 'tabBar') return tabBar;
                return null;
            },
            querySelector() { return null; },
            addEventListener() {},
        },
        localStorage: {
            getItem(key) { return values.get('storage:' + key) || null; },
            setItem(key, value) { values.set('storage:' + key, String(value)); },
        },
        scheduleTabLayoutRefresh() { tabRefreshes += 1; },
        updateOfflineBrowserBounds() { browserRefreshes += 1; },
        setTimeout() { return 1; }, clearTimeout() {}, setInterval() { return 1; }, clearInterval() {},
        addEventListener() {},
    };
    context.window = context;
    context.globalThis = context;
    vm.createContext(context);
    vm.runInContext(read('backend/renderer/modal-coordinator.js'), context, { filename: 'modal-coordinator.js' });
    vm.runInContext(read('backend/renderer/workspace.js'), context, { filename: 'workspace.js' });

    assert.equal(vm.runInContext('clampWorkspaceSidebarWidth(100)', context), 220);
    assert.equal(vm.runInContext('clampWorkspaceSidebarWidth(999)', context), 420);
    assert.equal(vm.runInContext('clampWorkspaceSidebarWidth(333)', context), 333);
    assert.equal(vm.runInContext('applyWorkspaceSidebarWidth(999, true)', context), 420);
    assert.equal(values.get('--workspace-sidebar-width'), '420px');
    assert.equal(tabBar.style.left, '420px');
    assert.equal(values.get('storage:darkstar.workspaceSidebar.width'), '420');
    assert.ok(tabRefreshes > 0);
    assert.ok(browserRefreshes > 0);
});

test('startup and restored sidebar geometry use the current resized width instead of hardcoded 280px', () => {
    const init = read('backend/renderer/init.js');
    const session = read('backend/renderer/chat-session.js');
    const workspace = read('backend/renderer/workspace.js');
    assert.match(init, /currentWorkspaceSidebarWidth/u);
    assert.match(session, /currentWorkspaceSidebarWidth/u);
    assert.match(workspace, /tabBar\.style\.left = collapsed \? '28px' : currentWorkspaceSidebarWidth\(\) \+ 'px'/u);
    assert.doesNotMatch(workspace, /tabBar\.style\.left = collapsed \? '28px' : '280px'/u);
});
});

function factoryBody(factory) {
    const text = Function.prototype.toString.call(factory);
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    let body = start >= 0 && end > start ? text.slice(start + 1, end) : '';
    if (body.startsWith('\n')) body = body.slice(1);
    if (body.endsWith('\n')) body = body.slice(0, -1);
    return body + '\n';
}

