test('attached UIP targets reuse a fresh descriptor within the refresh window and invalidate it after an action failure', async () => {
    let descriptions = 0;
    let closes = 0;
    const description = {
        ownerPid: 42,
        processes: [{ pid: 42, parentPid: 0, name: 'notepad.exe', path: 'C:/Windows/notepad.exe', commandLine: '' }],
        windows: [{ hwnd: '100', pid: 42, title: 'Notepad', bounds: { x: 0, y: 0, width: 800, height: 600 }, visible: true }],
    };
    const bridge = { async describeTarget() { descriptions += 1; return structuredClone(description); }, close() { closes += 1; } };
    const passive = { available: () => false, clear() {}, release() {} };
    let fail = false;
    const memoryInterface = { available: () => true, clear() {}, release() {}, async control() { if (fail) throw new Error('stale target'); return { success: true }; } };
    const service = new UniversalInterfaceService({
        platform: 'win32', refreshTtlMs: 5000, bridge,
        uiaBridge: { close() { closes += 1; } }, memoryBridge: { close() { closes += 1; } },
        accessibility: passive, chromiumInterface: passive, uiaInterface: passive, memoryInterface,
        cdp: { async probe() { throw new Error('native app must not probe CDP'); } },
    });
    const attached = await service.attachWindow('window:100:0', { scopeId: 'project-a' });
    assert.equal(descriptions, 1);
    await service.memoryControl(attached.id, { scopeId: 'project-a', action: 'memory_info' });
    await service.memoryControl(attached.id, { scopeId: 'project-a', action: 'memory_info' });
    assert.equal(descriptions, 1, 'fresh target description should be reused');
    fail = true;
    await assert.rejects(service.memoryControl(attached.id, { scopeId: 'project-a' }), /stale target/u);
    fail = false;
    await service.memoryControl(attached.id, { scopeId: 'project-a' });
    assert.equal(descriptions, 2, 'a failed operation must invalidate descriptor cache before the next operation');
    service.shutdown();
    assert.equal(closes, 3);
});

